def _стълби_редове(entry, direction, dec=2):
    """Трите информативни реда с по-късите стълби. Празен списък = изключено.

    НЕ пипа нито сделката, нито стоп-пазача, нито журнала — само текст.
    """
    if not СТЪЛБИ_КАРТА or entry is None:
        return []
    # 🔴 25.08 · ПЪРВАТА МИ ВЕРСИЯ БЕШЕ ТРИ РЕДА и счупи правилото «7 реда /
    # 400 знака», което пази картата четима на телефон (ОДИТ-29). Тестът П24 и
    # стил.py я хванаха ПРЕДИ качване: 8 реда, 459 знака. По-старото правило е
    # по-важно от новото допълнение — то се подчинява, не обратното.
    # Затова: ЕДИН ред, а бележката за пълния стоп влиза в него.
    _ч = []
    for име, t1, t2, t3, sl, удря, упълн in СТЪЛБИ_ДОП:
        lv = _levels_gen(float(entry), direction, t1, t2, t3, sl, dec)
        # 🔴 26.08 · СВИТО. Дългата форма («73%→77% с пълен стоп», два пъти)
        # изяде тавана от 400 знака, щом влезе предупреждението за скоростта.
        # Правилото за телефон е по-старо от двете допълнения. Остава числото,
        # което важи за ТАЗИ стълба; съотношението «близка цел + ПЪЛЕН стоп
        # удря 77%/83%» е мерено и стои в коментара при СТЪЛБИ_ДОП горе.
        # И разделителят на хиляди пада — четирицифрено число се чете и без него.
        _ч.append(f"{име.split('/')[0]}п <code>{lv['tp1']:.{dec}f}</code>|"
                  f"<code>{lv['tp2']:.{dec}f}</code>|"
                  f"<code>{lv['tp3']:.{dec}f}</code> "
                  f"🛑<code>{lv['sl']:.{dec}f}</code> {удря:.0f}%")
    return ["🪜 " + " · ".join(_ч)]
