def _режим_тегло(direction, regime):
    """(тегло, дума) — колко от риска, според мереното за режима.

    Само за ЛОНГА: мереното е за него. Шортът остава непокътнат, защото за
    него нито един режим не оцеля преизмерването (0 от 30 комбинации на плюс).
    """
    if direction != "long" or not isinstance(regime, dict):
        return 1.0, ""
    под = regime.get("below_sma200")
    ниска = regime.get("low_vol")
    if под is True:
        return РЕЖИМ_W_ПОД, "златото е ПОД 200-дневната средна — там мереното е слабо"
    if под is False and ниска is True:
        return РЕЖИМ_W_НИСКА, "над 200-дневната и спокоен пазар — най-силното съчетание"
    if под is False:
        return 1.0, "над 200-дневната средна"
    return 1.0, ""
