# ---------- дърпане на данни (упорито) ----------
def _retry(fn, tries=3, base_wait=4):
    import time
    last = None
    for i in range(tries):
        try:
            return fn()
        except Exception as e:
            last = e
            print(f"  опит {i+1}/{tries} неуспешен: {type(e).__name__}; чакам {base_wait*(i+1)}с")
            time.sleep(base_wait * (i + 1))
    raise last


def _yf(sym, period="2y", interval="1d"):
    def go():
        import yfinance as yf
        df = yf.download(sym, period=period, interval=interval, progress=False, auto_adjust=True)
        if df is None or len(df) == 0:
            raise RuntimeError(f"празни данни за {sym} ({interval})")
        df.columns = [a if isinstance(a, str) else a[0] for a in df.columns]
        idx = pd.DatetimeIndex(df.index)
        if idx.tz is not None:
            idx = idx.tz_convert("UTC")   # интрадей идва в NY време → първо в UTC!
        df.index = idx.tz_localize(None) if idx.tz is not None else idx
        return df.dropna(subset=["Close"])
    return _retry(go)


def _fred(series_id):
    def go():
        url = f"https://fred.stlouisfed.org/graph/fredgraph.csv?id={series_id}"
        with urllib.request.urlopen(url, timeout=30) as r:
            df = pd.read_csv(io.BytesIO(r.read()))
        df.columns = ["date", "v"]
        df["date"] = pd.to_datetime(df["date"]); df["v"] = pd.to_numeric(df["v"], errors="coerce")
        return df.dropna().set_index("date")["v"]
    return _retry(go)


# О9 · КОЯ ВЕЛИЧИНА СА ЛИХВИТЕ В ТОЗИ РЪН. Пълни се от `_rates()` и влиза в
# дневника. Дотук смяната реални→номинални се казваше само с print() — в
# stdout, който умира с Actions лога.
ЛИХВИ_ИЗТОЧНИК = {}


def _rates():
    """🔴 О9 · РЕАЛНИ (DFII10) и НОМИНАЛНИ (^TNX) НЕ СА ЕДНО И СЪЩО.
    Номиналните са реалните плюс инфлационни очаквания — разлика от порядъка на
    2 процентни пункта. Бектестът, който дава числата на гейта, е мерен на
    DFII10. Падне ли FRED, ботът съди днешния ден с ДРУГА величина, отколкото
    са мерени клетките. Сега това се казва в дневника, не само в лога."""
    ЛИХВИ_ИЗТОЧНИК.clear()
    try:
        s = _fred("DFII10")
        ЛИХВИ_ИЗТОЧНИК.update(вид="реални", тикер="DFII10", резерва=False)
        print("  лихви: FRED DFII10 (реални) ✓")
    except Exception:
        df = _yf("^TNX", "2y", "1d")
        s = df["Close"] / 10.0
        ЛИХВИ_ИЗТОЧНИК.update(вид="НОМИНАЛНИ", тикер="^TNX", резерва=True)
        print("  лихви: ^TNX (резерва — НОМИНАЛНИ, не реални)")
    # О9 №2 · ЗАСТОЯЛ FRED. Публикува с закъснение и мълчи в празници; върне ли
    # серия отпреди седмици, `r - r.shift(20)` мери СТАР прозорец и изглежда
    # напълно здраво. Досега нямаше никаква проверка на възрастта.
    try:
        _посл = pd.Timestamp(s.dropna().index[-1]).tz_localize(None)
        ЛИХВИ_ИЗТОЧНИК["дни"] = int((pd.Timestamp.utcnow().tz_localize(None) - _посл).days)
    except Exception:
        ЛИХВИ_ИЗТОЧНИК["дни"] = None
    return s


# ---------- сигнал (ЯДРОТО — непипнато от v4) ----------
def _macro(gold_d, gdx_d, dxy_d, rr, health=None):
    """🔴 ОДИТ-5: `bool(NaN > 0)` е False — няма състояние «не знам». Значи ТРИ МЪРТВИ ФИЙДА
    дават {False, False, False}, което `_resolve` чете като m3s (макро 3/3 за ШОРТ) и `_tier`
    вдига на ПРЕМИУМ. Максимално мечи пазар и три умрели входа са БАЙТ-ЗА-БАЙТ неразличими.
    Живият борд е шорт 14 722 клетки, лонг 0, 74.3% премиум — точно този подпис.
    `health` (ако е подаден) се пълни с реалната стойност на всяко краче + дали е било NaN,
    за да влезе в дневника: досега краката се печатаха само в stdout и умираха с Actions лога."""
    idx = gold_d.index
    g = gold_d["Close"]; gd = gdx_d["Close"].reindex(idx).ffill()
    dx = dxy_d["Close"].reindex(idx).ffill(); r = rr.reindex(idx).ffill()
    raw = {"миньори": (gd.pct_change(50) - g.pct_change(50)).iloc[-1],
           "долар": (-(dx.pct_change(20))).iloc[-1],
           "лихви": (-(r - r.shift(20))).iloc[-1]}
    if health is not None:
        for k, v in raw.items():
            bad = v is None or (isinstance(v, float) and np.isnan(v))
            health[k] = None if bad else round(float(v), 6)
        health["мъртви"] = [k for k in raw if health.get(k) is None]
    return {k: bool(v > 0) if not (v is None or (isinstance(v, float) and np.isnan(v))) else False
            for k, v in raw.items()}


def _от_резерва(spot):
    """🔴 ОДИТ-53 · КАЗВА ЛИ СЕ, ЧЕ ЦЕНАТА НЕ Е ОТ ЗЛАТНИЯ ФИЙД.
    `spot_src` влизаше само в дневника; собственикът виждаше число и мислеше, че
    е златният фийд. А PAXG търгува с ~$1-4 премия — самият код го знае и го
    изключва от базис-EMA-то по същата причина. Число на карта, за което не се
    казва откъде идва, е точно това, което този бот не бива да прави."""
    return str((spot or {}).get("src") or "").startswith("paxg")


def _пипс(долари, метал="XAUUSD"):
    """🔴 ОДИТ-67 · РАЗСТОЯНИЕТО НА ЕЗИКА НА СОБСТВЕНИКА.
    Мерено: 231 карти, НУЛА пишат пипсове. Той брои «4420→4415 = 50 пипса»,
    ботът пишеше «5.00$» — всяка карта искаше превъртане наум и вече го обърка
    веднъж («200 срещу 20»). PIP=0.10 съществуваше от началото и никога не
    стигаше до текста.
    Среброто е на друга скала: 0.001$ = 1 пипс (цена ~65$, стоп 0.54$)."""
    try:
        д = abs(float(долари))
    except Exception:
        return ""
    стъпка = PIP if метал == "XAUUSD" else 0.001
    return f"{д / стъпка:,.0f} пипса"


# 🔴 21.08 · ТУК ЩЕ ВЛЯЗАТ `_бр` / `_ппз` / `_зона_текст` — ЗАЕДНО с картите,
# които ги ползват. Добавих ги преди тях и П63 ги хвана като мъртъв код.
# Прав е: «скоро ще потрябват» не е оправдание за функция без викащ.
def _сила(мн):
    """(емоджи, дума, дял) от РЕАЛНИЯ множител на риска.

    🔴 18.08 · Размерът има ШЕСТ реални стойности (ZONE_W × МАЛЪК_РАЗМЕР_W:
    1.000 · 0.670 · 0.500 · 0.335 · 0.330 · 0.165), а картата казваше само
    «малък размер» или нищо. Изпълнено: карта при ×1.000 и карта при ×0.165 се
    различаваха с ЕДНА ДУМА — при 6× разлика в парите. Най-силният клас
    (day1: 79.9% печели от 4019 сделки) изглеждаше като най-слабия.

    Дялът Е множителят — не е измислено число, а точно колкото ботът вече
    смята. Лот НЕ се дава: собственикът каза «всеки си преценя» и е прав —
    лотът зависи от неговата сметка и брокер, които ботът не знае.
    """
    # 🔴 ПОПРАВЕНО (армия, 18.08) · ПЪРВАТА МИ ВЕРСИЯ ГРЕШЕШЕ ПО ТРИ НАЧИНА:
    #   · думите бяха за УВЕРЕНОСТ («НОРМАЛНО»), а стояха до КОЛИЧЕСТВО («⅔») —
    #     тоест «нормално» описваше НАМАЛЕН размер. Числото и думата до него не
    #     бива да си противоречат; сега всички думи са количества.
    #   · нулата нямаше дума изобщо, а тя е най-важната
    #   · четири нови емоджита (💪👍🪶🍃) за нещо, което едно (📏 мярка) върши
    # 🔴 25.08 · ЧЕТВЪРТИЯТ НАЧИН, ПО КОЙТО ГРЕШЕШЕ — намерен от армия и
    # ПОТВЪРДЕН чрез изпълнение на всичките реални множители:
    #     0.0825 ( 8.2%) → «⅙ от пълния» = 16.7%  ← обявява 2.02× ПОВЕЧЕ
    #     0.1650 (16.5%) → «⅙ от пълния» = 16.7%  ✅
    #     0.2500 (25.0%) → «⅓ от пълния» = 33.3%  ← обявява 1.33× ПОВЕЧЕ
    #     0.3300 (33.0%) → «⅓ от пълния» = 33.3%  ✅
    # ДЕВЕТ реални множителя се свиваха до ПЕТ надписа чрез «най-близката
    # красива дроб». Собственикът СМЯТА позицията си от тази дроб — прочете ли
    # «⅙», а ботът да е сметнал 1/12, той влиза с ДВОЕН риск спрямо замисленото.
    # Точно грехът, срещу който е писана самата функция: «дялът Е множителят».
    # Сега дробта се показва САМО когато е вярна до 1 процентен пункт; иначе
    # се пише истинският процент. Думата (количество) остава непокътната.
    _д = [(1.0, "пълен размер"), (2 / 3, "⅔ от пълния"), (1 / 2, "½ от пълния"),
          (1 / 3, "⅓ от пълния"), (1 / 6, "⅙ от пълния")]
    if мн <= 0.001:
        return "📏", "НУЛА", "не влизам"
    _бл = min(_д, key=lambda t: abs(t[0] - мн))
    дял = _бл[1] if abs(_бл[0] - мн) <= 0.01 else f"{100.0 * мн:.0f}% от пълния"
    # 🔴 26.08 · прагът беше 0.85 и след новите тегла на зоните излизаше
    # «ВСИЧКО · 85% от пълния» — думата и числото си противоречат, точно
    # грехът, срещу който е писана тази функция. «Всичко» значи всичко.
    if мн >= 0.95:
        return "📏", "ВСИЧКО", дял
    if мн >= 0.55:
        return "📏", "МНОГО", дял
    if мн >= 0.40:
        return "📏", "ПОЛОВИНАТА", дял
    if мн >= 0.25:
        return "📏", "ЛЕКО", дял
    return "📏", "ЕДВА", дял


def _пари(долари, метал="XAUUSD"):
    """ПЕЧАЛБА/ЗАГУБА НА ЕЗИКА НА СОБСТВЕНИКА.

    `_разст` мери разстояние МЕЖДУ ДВЕ НИВА и винаги е положително. Печалбата
    има ЗНАК и не се вади от две цени — затова досега шест карти пишеха само
    долари: `+7.50$/унция` (= 75 пипса), `+8.90$` (= 89), `+40.60$` (= 406).
    Собственикът брои пипсове; всеки път превърташе наум.
    """
    стъпка = PIP if метал == "XAUUSD" else 0.001
    # един и същ знак на двете места: Python дава ASCII «-», а пипсовете
    # ползват типографско «−». На една карта два различни минуса си личат.
    зн = "+" if долари >= 0 else "−"
    _п = abs(долари) / стъпка
    # 🔴 «−0 пипса (−0.05$)» се чете като нула, а не е нула. Под един пипс се
    # казва с думи — числото пак стои в долари до него.
    if abs(долари) < 1e-9:
        return "0 пипса (0.00$)"
    if _п < 1:
        return f"под 1 пипс ({зн}{abs(долари):.2f}$)"
    return f"{зн}{_п:,.0f} пипса ({зн}{abs(долари):.2f}$)"


def _разст(a, b, метал="XAUUSD", dec=2):
    """«200 пипса (20.00$/oz)» — двете мерки на един ред, неговата отпред.

    🔴 26.08 · ЕДИНИЦАТА ЛИПСВАШЕ. Картата казваше «200 пипса (20.00$)»,
    а това е долари НА УНЦИЯ. Собственикът чете «стопът ми е 20 долара»,
    докато при един стандартен лот (100 унции) стопът е 2000 ДОЛАРА.
    Сто пъти разлика в четенето на едно и също число.
    Стълбицата, за да се вижда наведнъж:
        1 унция (0.01 лот)   1 пипс = 0.10$   стоп 200п = −20$
        10 унции (0.10 лот)  1 пипс = 1.00$   стоп 200п = −200$
        100 унции (1 лот)    1 пипс = 10.00$  стоп 200п = −2000$
    Лотът НЕ се връща на картата (ОДИТ-41: «всеки си преценя») — връща се
    само ЕДИНИЦАТА, за да не се чете грешно.
    """
    try:
        д = abs(float(a) - float(b))
    except Exception:
        return ""
    _ед = "$/oz" if метал == "XAUUSD" else "$/oz"
    return f"{_пипс(д, метал)} ({д:,.{dec}f}{_ед})"


ЧАСОВИ_ЗОНИ_СЧУПЕНИ = ""


def _tz(име):
    """ZoneInfo с ЕДНО общо знаме при провал.

    🔴 21.08 · `_market_closed`, `_cme_pause` и `_in_shield` питат САМО за
    'America/New_York' и всеки завършва с `except: return False` = «безопасно е».
    ИЗПЪЛНЕНО: без тази зона СЪБОТА минава за отворен пазар, CME паузата изчезва
    (значи базисът ре-анкерва върху фалшив скок, а спотът пуска крипто-прокси
    срещу затворен фючърс) и US-щитът изчезва. Нито print, нито бележка.
    Пазачът не се чупи — той тихо престава да съществува. Сега поне се обажда.
    """
    global ЧАСОВИ_ЗОНИ_СЧУПЕНИ
    from zoneinfo import ZoneInfo
    try:
        return ZoneInfo(име)
    except Exception as _e:
        ЧАСОВИ_ЗОНИ_СЧУПЕНИ = f"{име} ({type(_e).__name__})"
        raise


def _sofia(iso_utc=None):
    from datetime import datetime, timezone
    try:
        dt = datetime.fromisoformat(str(iso_utc)) if iso_utc else datetime.now(timezone.utc).replace(tzinfo=None)
        return dt.replace(tzinfo=timezone.utc).astimezone(_tz("Europe/Sofia")).strftime("%H:%M")
    except Exception:
        return "?"


def _sofia_dt(iso_utc):
    """«дд.мм HH:MM» — ДАТАТА И ЧАСЪТ в ЕДНА И СЪЩА зона (София).

    🔴 21.08 · Дотук картите лепяха `evt.strftime('%d.%m')` (UTC ДАТА) до
    `_sofia(...)` (СОФИЙСКИ ЧАС). Изпълнено: събитие 25.08 22:30 UTC, което е
    26.08 01:30 София → картата казваше «25.08 01:30 София». Грешен ДЕН за
    всяко събитие след 21:00 UTC. Тук двете идват от един и същи момент.
    """
    from datetime import datetime, timezone
    try:
        dt = datetime.fromisoformat(str(iso_utc).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(_tz("Europe/Sofia")).strftime("%d.%m %H:%M")
    except Exception:
        return "?"


def _sofia_ако_друг_ден(iso_utc, спрямо_utc=None):
    """«14:20» ако е СЪЩИЯТ софийски ден · «12.08 15:42» ако е друг.

    🔴 21.08 · Час без дата е верен само докато денят е един. Мерено:
    3 от 3 дупки на бота пресичат софийска полунощ (две по 49 часа) и
    1 от 17 наблюдения се затваря на следващия ден. В тези случаи картата
    сочеше час, който се чете като днешен — и противоречеше на собствения
    си първи ред («СПА 49ч» до «от 23:55 до 01:02»).
    """
    from datetime import datetime, timezone
    С = _tz("Europe/Sofia")
    def _в_софия(x):
        dt = datetime.fromisoformat(str(x).replace("Z", "+00:00"))
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(С)
    try:
        т = _в_софия(iso_utc)
    except Exception:
        return "?"
    try:
        сега = _в_софия(спрямо_utc) if спрямо_utc else datetime.now(timezone.utc).astimezone(С)
    except Exception:
        сега = datetime.now(timezone.utc).astimezone(С)
    return т.strftime("%H:%M") if т.date() == сега.date() else т.strftime("%d.%m %H:%M")


def _ts_le(a, b):
    """ОДИТ-5 (L1-01): сравнение на моменти по СТОЙНОСТ, не по низ. «2026-07-29 03:00:00» и
    «2026-07-29T02:10» са един и същи ден, но като низове интервалът е по-малък от 'T' →
    старото `str(ts) <= be_since` връщаше True за цял ден и гасеше безрисковия стоп.
    При неразбираем вход връща False = «не гаси» (безопасната страна)."""
    try:
        return pd.Timestamp(a) <= pd.Timestamp(b)
    except Exception:
        return False


def _sofia_hour(iso_utc=None):
    """Софийският ЧАС като число (0-23), с лятно/зимно време. −1 при повреден вход."""
    from datetime import datetime, timezone
    try:
        dt = datetime.fromisoformat(str(iso_utc)) if iso_utc else datetime.now(timezone.utc).replace(tzinfo=None)
        return dt.replace(tzinfo=timezone.utc).astimezone(_tz("Europe/Sofia")).hour
    except Exception:
        return -1


def _reoffer_hour_ok(iso_utc=None):
    """🔴 ОДИТ-3: повторното предлагане важи САМО в часове, в които човек може да влезе.
    Мерено на реалния дневник: без този филтър 17 от 46 карти падаха между 23:00 и 07:00
    София — предложение за вход в 02:20 е шум, не помощ. С филтъра нощните падат на 9,
    и всичките 9 са ИСТИНСКИ нови сетъпи (смяна на борда), не повторения."""
    h = _sofia_hour(iso_utc)
    return REOFFER_LO <= h <= REOFFER_HI


def _in_shield(now_utc=None):
    """В US-прозореца 8:25–9:15 НЮ ЙОРКСКО време ли сме (данните в 8:30 ET)?
    Дефиниран в ET, не в София — лятното време се мести в различни седмици."""
    try:
        dt = datetime.fromisoformat(str(now_utc)) if now_utc else datetime.now(timezone.utc).replace(tzinfo=None)
        et = dt.replace(tzinfo=timezone.utc).astimezone(_tz("America/New_York"))
        m = et.hour * 60 + et.minute
        return SHIELD_ET[0] <= m <= SHIELD_ET[1]
    except Exception:
        return False


def _shield_sofia_label():
    """Прозорецът на щита, преведен в София час (за картите)."""
    try:
        today = datetime.now(timezone.utc).astimezone(_tz("America/New_York")).date()
        a = datetime(today.year, today.month, today.day, SHIELD_ET[0] // 60, SHIELD_ET[0] % 60,
                     tzinfo=_tz("America/New_York")).astimezone(_tz("Europe/Sofia"))
        b = datetime(today.year, today.month, today.day, SHIELD_ET[1] // 60, SHIELD_ET[1] % 60,
                     tzinfo=_tz("America/New_York")).astimezone(_tz("Europe/Sofia"))
        return f"{a.strftime('%H:%M')}–{b.strftime('%H:%M')} София"
    except Exception:
        return "15:25–16:15 София"


def _streaks(gold_d, gdx_d, dxy_d, rr):
    """ОДИТ-10 (04.08): ПОДРЕЖДАНЕТО вече е по ДОЛАРА и РЕАЛНИТЕ ЛИХВИ — БЕЗ миньорите.

    Причина, мерена на 114813 сделки (блоков бутстрап по ден, доставената геометрия):
       правило                 общо      карти/г   2006-11  2011-16  2016-21  2021-26  МЕЧИ 13-18
       и трите (СТАРОТО)    +32 560$        45      +1.68    +1.72    +2.34    +0.71     +1.41
       2 от 3 (всички)      +58 918$       116      +1.90    +0.31    +1.63    +0.61     +0.07
       ДОЛАР+ЛИХВИ (ново)   +44 462$        72      +1.52    +1.15    +2.01    +0.82     +0.54
       2 от 3 + долар       +47 953$        89      +1.60    +0.59    +1.51    +0.97     +0.10
    Избрано «долар+лихви», а НЕ най-голямото число: то е ЕДИНСТВЕНОТО, което не пада
    под +0.5$ в нито един режим. Пълното «2 от 3» прави повече пари, но дава +0.07$ в
    страничен/мечи пазар и има 2.4× по-дълбока просадка (−9544$ срещу −3929$).
    Логиката е и смислена: миньорите (GDX) са АКЦИИ — в страничен пазар се движат по
    борсата, не по златото, и внасят шум. Доларът и реалните лихви са пряко вързани.
    Късмет-тест: 0 от 60 случайни правила със същата плътност бият резултата.

    ⚠️ Клетките в backtest_stats.json СА ПРЕСМЕТНАТИ ПОД ТОВА ПРАВИЛО (fresh.*.day1/
    fresh/mixed/stale). Смени ли се правилото пак — клетките се смятат наново, иначе
    гейтът съди новите дни със стари числа.
    `gdx_d` остава в подписа: миньорите СЕ ПОКАЗВАТ на картата като контекст (`_macro`),
    просто вече не участват в ПОДРЕЖДАНЕТО."""
    idx = gold_d.index
    dx = dxy_d["Close"].reindex(idx).ffill(); r = rr.reindex(idx).ffill()
    m_l = ((-(dx.pct_change(20))) > 0) & ((-(r - r.shift(20))) > 0)      # доларът пада И лихвите падат
    m_s = ((dx.pct_change(20)) > 0) & ((r - r.shift(20)) > 0)            # доларът расте И лихвите растат
    def last_streak(s):
        s = s.fillna(False)
        return int(s.groupby((~s).cumsum()).cumsum().iloc[-1])
    return {"long": last_streak(m_l), "short": last_streak(m_s)}


def _изблик(df, колко=60):
    """🔴 О9 №3 · СБЪРКАН БАР ВЛИЗА ПРАВО В КЛАСА.
    `_scores` чете само `iloc[-1]`; един spike-бар от Yahoo може да вдигне класа
    и да отвори сделка. Тук само ОТКРИВАМЕ и КАЗВАМЕ — НЕ поправяме цената
    мълчаливо, защото тиха «поправка» на пазарни данни е по-опасна от дефекта.
    Връща (той_е_изблик, колко_пъти_над_обичайното) или (False, 0.0)."""
    try:
        c = df["Close"].dropna()
        if len(c) < 12:
            return False, 0.0
        д = c.diff().abs()
        обич = float(д.iloc[-колко:-1].median())
        посл = float(д.iloc[-1])
        if not np.isfinite(обич) or обич <= 0:
            return False, 0.0
        return (посл / обич >= ИЗБЛИК_Х), посл / обич
    except Exception:
        return False, 0.0


def _refs(gold_d):
    c, h, l = gold_d["Close"], gold_d["High"], gold_d["Low"]
    def last(x):
        v = x.iloc[-1]; return float(v) if pd.notna(v) else np.nan
    return {"sma50": last(c.rolling(50).mean()), "sma20": last(c.rolling(20).mean()),
            "ago5": last(c.shift(5)), "ago20": last(c.shift(20)),
            "low20": last(l.rolling(20).min()), "high20": last(h.rolling(20).max())}


def _regime(gold_hist, gold_today=None):
    """Ф9.1: стойностите (SMA, вол) — от ЗАВЪРШЕНИ дни (gold_hist);
    MA-докосванията — с ДНЕШНИЯ жив бар (gold_today, ако е подаден)."""
    c, h, l = gold_hist["Close"], gold_hist["High"], gold_hist["Low"]
    sma50 = c.rolling(50).mean().iloc[-1]; sma200 = c.rolling(200).mean().iloc[-1]
    vol20 = c.pct_change().rolling(20).std()
    volmed = vol20.rolling(252).median().iloc[-1]
    src = gold_today if gold_today is not None else gold_hist
    cN, hN, lN = float(src["Close"].iloc[-1]), float(src["High"].iloc[-1]), float(src["Low"].iloc[-1])
    below = bool(cN < sma200) if pd.notna(sma200) else None
    lowv = bool(vol20.iloc[-1] < volmed) if pd.notna(volmed) and pd.notna(vol20.iloc[-1]) else None
    vr = vol20.rolling(504).rank(pct=True).iloc[-1]
    vol_rank = float(vr) if pd.notna(vr) else None
    ma = {}
    if pd.notna(sma50):
        ma["long_ma50"] = bool(lN <= sma50 and cN > sma50)
        ma["short_ma50"] = bool(hN >= sma50 and cN < sma50)
    if pd.notna(sma200):
        ma["long_ma200"] = bool(lN <= sma200 and cN > sma200)
        ma["short_ma200"] = bool(hN >= sma200 and cN < sma200)
    return {"below_sma200": below, "low_vol": lowv, "ma": ma, "vol_rank": vol_rank,
            "sma50": float(sma50) if pd.notna(sma50) else None,
            "sma200": float(sma200) if pd.notna(sma200) else None}


def _scores(df, refs, macro, price_adj=0.0):
    """price_adj (ОДИТ 28.07): корекция за КОНТРАКТЕН БАЗИС. refs идват от ДНЕВНАТА
    крива на GC=F, а df е ИНТРАДЕЙ крива — Yahoo ги дава на РАЗЛИЧНО ниво (различен
    контрактен месец). Измерено: интрадей стои над дневния с медиана 9.3$ (5м, 60д)
    и 17.6$ (1час, 2г), в 69-89% от дните, всичките 11 квартала в една посока.
    Без корекция лонг-тестовете (cN>sma50/sma20/ago20, hN>=high20) палят излишно —
    сменя ПОСОКАТА на 6.9% от дните. price_adj=0.0 → старото поведение (фрейм «1ден»,
    който е на СЪЩАТА крива като refs, и всички тестове)."""
    cN = float(df["Close"].iloc[-1]) + price_adj
    lN = float(df["Low"].iloc[-1]) + price_adj
    hN = float(df["High"].iloc[-1]) + price_adj
    def nn(v): return not (v is None or (isinstance(v, float) and np.isnan(v)))
    ml = [macro["миньори"], macro["долар"], macro["лихви"]]
    ms = [not m for m in ml]
    lp = [nn(refs["sma50"]) and cN > refs["sma50"], nn(refs["sma20"]) and cN > refs["sma20"],
          nn(refs["ago20"]) and cN > refs["ago20"],
          nn(refs["ago5"]) and nn(refs["ago20"]) and (cN / refs["ago5"] - 1 < 0) and (cN / refs["ago20"] - 1 > 0),
          nn(refs["low20"]) and lN <= refs["low20"] * 1.015]
    sp = [nn(refs["sma50"]) and cN < refs["sma50"], nn(refs["sma20"]) and cN < refs["sma20"],
          nn(refs["ago20"]) and cN < refs["ago20"],
          nn(refs["ago5"]) and nn(refs["ago20"]) and (cN / refs["ago5"] - 1 > 0) and (cN / refs["ago20"] - 1 < 0),
          nn(refs["high20"]) and hN >= refs["high20"] * 0.985]
    return sum(ml) + sum(1 for x in lp if x), sum(ms) + sum(1 for x in sp if x), cN


def _tier(score, m3):
    if m3: return ("premium", "ПРЕМИУМ")
    if score >= 6: return ("strong", "СИЛЕН")
    if score >= 4: return ("medium", "СРЕДЕН")
    return ("weak", "ЧАКАЙ")


# 🔴 25.08 · ПРЕВЕСЪТ. `_resolve` връща max(ls, ss) — сбора на ПОБЕДИТЕЛЯ —
# и ИЗХВЪРЛЯ разликата ls−ss. А разликата носи пари, при ИНАЧЕ ЕДНАКЪВ сбор.
# МЕРЕНО на 6846 входа, 7 959 839 минутни бара, доставената геометрия,
# интервал ВЪРХУ САМАТА РАЗЛИКА (бутстрап по ден, преизбрани ГРУПИ):
#
#
# 🔴🔴 26.08 · ЧИСЛАТА ОТДОЛУ БЯХА НАДУТИ 2.2× ОТ НАДНИЧАНЕ НАПРЕД.
# Трите скрипта mer_preves.py/2/3, които ги произведоха, пресмятаха дъската
# наново от дневна рамка БЕЗ `.shift(1)`: cN/hN/lN идваха от календарния ден
# НА ВХОДА, а sma50/sma20/high20/low20 — от целия ден. Средно 9.83 ЧАСА
# БЪДЕЩЕ, в 100.0% от 6846-те входа. Тези три скрипта дават НЕВАЛИДНИ числа
# и не бива да се цитират повече.
#
# ЧЕСТНОТО «широк (≥3) срещу тесен (≤2)», сметнато от ls/ss В САМИЯ ХАРНЕС
# (причинни, каквито ботът ги вижда):
#     ЛОНГ · всички       +1.892$ [+0.49, +3.28] ✅   (беше +4.206)
#     ЛОНГ · 2004-2014    +4.309$ [+2.17, +6.41] ✅
#     ЛОНГ · 2015-2026    ⚪ [−1.68, +2.03]            ← ПАДА
#     ШОРТ · всички       ⚪ [−0.44, +2.51]            ← ПАДА
# Тоест ДВЕТЕ самохвалби отдолу са ОБОРЕНИ: НЕ работи в двете посоки и НЕ
# работи в двете епохи. Оставям ги задраскани, за да се вижда какво падна.
#
# ⚖️ НО РЕШЕНИЕТО НЕ Е ЧИСЛОТО ОТГОРЕ. Правилото не сравнява две кофи — то
# ДАВА ПОЛОВИН РАЗМЕР на тесния. Това е друго количество и е премерено
# ПРЯКО, сдвоено по ден (със и без правилото върху ЕДНИ И СЪЩИ входове):
#     и двете посоки  Δ +0.217$/сделка [+0.09, +0.35] ✅  n=6846
#     ШОРТ            Δ +0.342$        [+0.07, +0.63] ✅
#     ЛОНГ            Δ +0.099$        [−0.15, +0.35] ⚪
# ДЕЙСТВИЕТО се плаща → ПРАВИЛОТО ОСТАВА.
#
# ⚠️ ЧЕСТНАТА ЗАБЕЛЕЖКА КЪМ СОБСТВЕНОТО МИ ЧИСЛО: печалбата идва от ШОРТА,
# а целият шорт-тефтер губи (шорт·тесен −1.339$ [−2.46,−0.22] 🔴). Тоест
# това е довод за ПО-МАЛЪК ШОРТ, не доказателство, че превесът различава.
# При лонга превесът наистина различава (тесен −0.456$ ⚪, широк +1.436$ ✅),
# но разликата вече НЕ е доказана.
#
# ЗАДРАСКАНОТО (беше цитирано като истина до 26.08):
#   ✗ ЛОНГ всички +4.206 · ЛОНГ 2004-2014 +5.009 · ЛОНГ 2015-2026 +3.668
#   ✗ ШОРТ всички +2.784 · праг ≥4: ЛОНГ +2.574 · ШОРТ +1.982
#   ✗ «работи в ДВЕТЕ ПОСОКИ» · ✗ «работи в ДВЕТЕ ЕПОХИ»
#   (плацебото 0 от 9 беше пуснато върху СЪЩИТЕ надничащи числа → невалидно)
#
# ТЕСНИЯТ превес получава ПОЛОВИН размер — както «под 200-дневната».
# Не се добавя нов вход; само се пази по-малко върху по-слабата половина.
# Път назад: ПРЕВЕС_W_ТЕСЕН=1.0 (изключва правилото без качване).
ПРЕВЕС_ТЕСЕН = int(os.environ.get("ПРЕВЕС_ТЕСЕН", "2"))     # ≤ това е «тесен»
ПРЕВЕС_W_ТЕСЕН = float(os.environ.get("ПРЕВЕС_W_ТЕСЕН", "0.5"))


def _превес_тегло(превес):
    """Тегло върху размера от ПРЕВЕСА на дъската (ls − ss).

    Липсва ли превес (стар извикващ) → 1.0, тоест точно старото поведение.
    """
    try:
        п = abs(int(превес))
    except (TypeError, ValueError):
        return 1.0, ""
    if п <= ПРЕВЕС_ТЕСЕН:
        return ПРЕВЕС_W_ТЕСЕН, ("превесът е ТЕСЕН (%d) — двете посоки са почти "
                                "изравнени, там мереното е по-слабо" % п)
    return 1.0, "превесът е широк (%d)" % п


def _resolve(ls, ss, macro):
    m3l = all(macro.values()); m3s = not any(macro.values())
    if ls > ss:
        tk, tn = _tier(ls, m3l); return ("long", ls, tk, tn)
    if ss > ls:
        tk, tn = _tier(ss, m3s); return ("short", ss, tk, tn)
    return ("wait", max(ls, ss), "weak", "ЧАКАЙ")


def _спряна_msg(direction, best, price_user, причина, обяснение, now_utc, board):
    """ОДИТ-26/29 · виждам сетъп, спирачка го спира. Четири реда, без нива."""
    ико = "🟢" if direction == "long" else "🔴"
    посока = "покупка" if direction == "long" else "продажба"
    # ОДИТ-45г: «/7» беше невярно — рамките са копия (84.6% буквално еднакви
    # на 1965 живи ръна). Броим РАЗЛИЧНИТЕ отчети; един отчет не се брои.
    _за, _общо = _съгласни(board, direction)
    return "\n".join([
        f"⏸ ВИЖДАМ {посока.upper()} · но не я давам · {_sofia(now_utc)}",
        f"{ико}{f' {_за} от {_общо} отчета натам ·' if _общо > 1 else ''} "
        f"<code>{_fmt(price_user, 2)}</code>",
        # 🔴 18.08 · `обяснение` ВЛИЗАШЕ И СЕ ИЗХВЪРЛЯШЕ. Всичките 7 места, които
        # вдигат спирачка, подават втори елемент с ЧИСЛОТО зад нея («мерено на
        # 19.7 години: −1.59$/сделка»). Картата рендерираше само причината —
        # изпълнено: подмяна на обяснението даваше БАЙТ-ИДЕНТИЧНА карта.
        # 🔴 И ВТОРА ПОПРАВКА НА СОБСТВЕНАТА МИ ПОПРАВКА: първо го сложих на
        # ОТДЕЛЕН ред и счупих правилото «четири реда» (ОДИТ-29, за телефон).
        # Тестът П24 го хвана. Числото влиза на СЪЩИЯ ред — картата остава 4 реда.
        f"📌 {причина}" + (f" · {обяснение}" if обяснение else ""),
        "👁 нищо сега · пиша щом падне спирачката"])

def _standing_msg(direction, best, age_h, spot, bar_price, price_user, board, macro, health,
                  now_utc, таван=None):
    """ОДИТ-29 · сетъпът стои, но не е пресен. Четири реда."""
    ико = "🟢" if direction == "long" else "🔴"
    посока = "покупка" if direction == "long" else "продажба"
    _за, _общо = _съгласни(board, direction)   # ОДИТ-45г: виж близнак 1
    lv = _levels(round(price_user, 2), direction)
    # 🔴 ОДИТ-67 · ВЪЗРАСТТА БЕШЕ ОТ ЗАМРАЗЕН КЛЮЧ, А НИВАТА ОТ ДНЕШНАТА ЦЕНА.
    # Мерено на живо: «вече 276ч» при key_since 06.08 (злато 4261.75), а нивата
    # смятани от 4396.60 — цената е избягала 6.7 ПЪТИ стопа. Сетъпът, който
    # «стои», отдавна е ударил стопа си шест пъти. Двете не могат да са верни
    # едновременно, затова възрастта се показва САМО докато нивата още важат.
    _възр = (f"вече {age_h:.0f}ч" if (age_h is not None and age_h < СТОЯЩ_МАКС_Ч)
             else "нивата са от сега")
    L = [f"⏸ СТОИ · {посока} злато · {_sofia(now_utc)}",
         f"{ико}{f' {_за} от {_общо} отчета натам ·' if _общо > 1 else ''} {_възр}",
         f"🎯 <code>{_fmt(price_user, 2)}</code> · 🛑 <code>{_fmt(lv['sl'], 2)}</code>"
         f" · {_разст(price_user, lv['sl'])}",
         # 🔴 РЕД 4.1 · ДОТУК ТУК ЦЕЛИТЕ БЯХА ГОЛИ ЦЕНИ. Стопът отдолу вече
         # носи «200 пипса (20.00$)», а целите — само число. Собственикът брои
         # в пипсове и трябваше да вади наум от входа, който е на ДРУГ ред.
         # Кратката форма «(75п)» е заради тавана на реда: три цели наведнъж.
         " · ".join(f"{n} <code>{_fmt(lv[k], 2)}</code> "
                    f"({abs(lv[k] - price_user) / PIP:,.0f}п)"
                    for n, k in (("1️⃣", "tp1"), ("2️⃣", "tp2"), ("3️⃣", "tp3")))]
    # ОДИТ-35 · `macro` се подаваше на функцията и НЕ се ползваше никъде.
    # Точно то решава дали сетъпът има шанс — картата мълчеше за него.
    _реш = [k for k in ("долар", "лихви") if k in (macro or {})]
    _за = sum(1 for k in _реш if (macro[k] if direction == "long" else not macro[k]))
    if _реш:
        L.append("📌 доларът и лихвите са в същата посока" if _за == len(_реш)
                 else ("⚠️ доларът и лихвите са СРЕЩУ тази посока" if _за == 0
                       else "⚠️ доларът и лихвите не са единодушни"))
    if health and health.get("мъртви"):
        L.append(f"⚠️ мълчи: {', '.join(health['мъртви'])}")
    # 🔴 21.08 · «не е пресен» е присъда БЕЗ ЧИСЛО. Собственикът гледа графиката и
    # решава сам — трябва му ПРИЧИНАТА, не настроението. Мерено: за 119 ръна, в
    # които гейтът каза ДА в 116, това беше единственото, което получи.
    # Нивата вече са на реда отгоре; тук идва «защо не влизам» с числа.
    # 🔴 ОДИТ-67 ОСТАВА В СИЛА: възрастта се казва САМО докато нивата още важат.
    # Иначе картата твърди «вече 276ч» до нива, смятани от ДНЕШНАТА цена — две
    # неща, които не могат да са верни едновременно. Причината обаче се казва
    # ВИНАГИ, с числото на правилото — тя не зависи от възрастта.
    # 🔴 25.08 · ТРЕТИЯТ БЛИЗНАК: тази карта отива при СОБСТВЕНИКА и печаташе
    # голото 12ч, независимо от клетката. Сега получава своя таван отвън.
    _т = REOFFER_MAX_AGE_H if таван is None else float(таван)
    if age_h is not None and age_h < СТОЯЩ_МАКС_Ч:
        L.append(f"👁 не влизам: сетъпът е на {age_h:.0f}ч, правилото пуска до "
                 f"{_т:.0f}ч · решаваш ти")
    else:
        L.append(f"👁 не влизам: правилото пуска повторен вход до {_т:.0f}ч "
                 f"· нивата са от сега, решаваш ти")
    return "\n".join(L)

def _demote_if_dead(resolved, health):
    """🔴 ОДИТ-5: ПРЕМИУМ значи «и трите макро-крака са съгласни». Ако някое краче е МЪРТВО
    (NaN → False), съгласието е фалшиво — мълчанието на счупен фийд се брои за глас «за».
    Затова при мъртво краче класът пада ПРЕМИУМ → СИЛЕН. Не спираме сигнала (цената още
    говори), но не го обявяваме за максимална увереност на основа, която не съществува."""
    if not health or not health.get("мъртви"):
        return resolved
    d, sc, tk, tn = resolved
    if tk == "premium":
        return (d, sc, "strong", "СИЛЕН")
    return resolved


def _levels_gen(entry, direction, tp1, tp2, tp3, sl, dec=2):
    s = 1 if direction == "long" else -1
    return {"tp1": round(entry + s * tp1, dec), "tp2": round(entry + s * tp2, dec),
            "tp3": round(entry + s * tp3, dec), "sl": round(entry - s * sl, dec)}


def _levels(entry, direction):
    return _levels_gen(entry, direction, TPS[0][2], TPS[1][2], TPS[2][2], SL_D, 2)


def _levels_silver(entry, direction):
    return _levels_gen(entry, direction, S_TPS[0], S_TPS[1], S_TPS[2], S_SL, 3)


# ---------- спот в реално време + санити (Ф8.3) ----------
SPOT_MAX_AGE = 90        # A1: котировка по-стара от 90 сек не е «реално време»
# 🔴 18.08 · CLOCK_SKEW = 60 ПАДНА. Режеше age < −60, а СКЮ_ДОПУСК = 2 реже
# age < −2 три реда по-долу. Първото множество е ПОДМНОЖЕСТВО на второто →
# не можеше да отсее нищо ново. Проверено на 800 стойности: 615 отхвърлени
# със и без него, ИДЕНТИЧНИ. Константа, която нищо не прави, и тест, който я
# пази — шаблонът от ОДИТ-48.
# 🔧 О15 · КОЛКО «БЪДЕЩЕ» СЕ ПРИЕМА ЗА ПРЯСНО. Дотук всичко до -60с се клампваше
# до age=0, тоест платформа с часовник +60с И ЗАСТОЯЛА цена минаваше за съвсем
# прясна. Истинското скю е ~1с; 2с е достатъчно и не крие застой.
СКЮ_ДОПУСК = float(os.environ.get("СКЮ_ДОПУСК", "2"))
def _spot(instr="XAU/USD", market_closed=False, cme_pause=False, реф=None, следа=None):
    """Swissquote публичен фийд, без ключ; за злато има РЕЗЕРВНА ВЕРИГА (PAXG: Binance → Coinbase → Kraken).
    A1: избира цена САМО от ПРЯСНА платформа; прозорец 90 сек. Връща bid/ask/mid/src/age_sec.
    T1: под-секундно часово разминаване (age малко под 0) НЕ бракува фийда."""
    import time as _t
    try:
        url = "https://forex-data-feed.swissquote.com/public-quotes/bboquotes/instrument/" + instr
        with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=8) as r:
            data = json.loads(r.read().decode())
        best = None; best_age = None
        now_ms = _t.time() * 1000
        for plat in data:
            age = (now_ms - plat.get("ts", 0)) / 1000.0
            if age > SPOT_MAX_AGE:                       # застояла котировка
                continue
            # 🔧 О15: -60с..-2с вече НЕ минава за «сега» — това е часовник, който
            # води, и може да крие застояла цена. Пропускаме тази платформа;
            # другите в същия отговор пак се разглеждат.
            if age < -СКЮ_ДОПУСК:
                continue
            age = max(age, 0.0)                          # T1: истинско скю (~1с) → «сега»
            for p in plat.get("spreadProfilePrices", []):
                if p["bid"] < p["ask"] and (best is None or (p["ask"] - p["bid"]) < (best[1] - best[0])):
                    best = (p["bid"], p["ask"]); best_age = age
        if best is not None:
            if следа is not None:
                следа.append(("swq", "ok"))
            return {"bid": round(best[0], 3), "ask": round(best[1], 3),
                    "mid": round((best[0] + best[1]) / 2, 3), "src": "swq",
                    "age_sec": round(best_age, 1)}
        if следа is not None:
            следа.append(("swq", "празен отговор"))
    except Exception as _еs:
        # 🔴 21.08 · ДОТУК ТУК СТОЕШЕ ГОЛО `pass`. Умре ли мрежата или смени ли
        # Swissquote схемата си (bid/ask → buy/sell), функцията връщаше None
        # ТОЧНО както при затворен пазар — двете състояния бяха неразличими,
        # а в главния поток разликата се губеше докрай.
        # ЧЕСТНО ЗА ТЕЖЕСТТА: латентно, не текущо — от 4242 живи ръна има 76
        # случая spot=None без отрязване и ВСИЧКИТЕ 76 са в час 21 UTC (CME
        # паузата), тоест по устройство. Реални попадения от мъртва мрежа: 0.
        if следа is not None:
            следа.append(("swq", type(_еs).__name__))
    # 🔴 ОДИТ-53 · И В ДНЕВНАТА CME ПАУЗА. Дотук пазачът беше само уикендът, а
    # CME Globex спира и всеки делник по един час (17:00 Ню Йорк). Тогава
    # фючърсът е затворен, а PAXG е крипто и върви 24/7 — цена, която никой не
    # арбитрира срещу затворен фючърс, показвана като злато.
    # `_cme_pause` вече съществува и се ползва в `_basis_update` по СЪЩАТА
    # причина; на спот-резервата просто не беше подаден.
    if market_closed or cme_pause:                        # T5: без крипто-прокси при спрял фючърс
        return None
    if instr == "XAU/USD":
        # 🔴 ОДИТ-6 (29.07): РЕЗЕРВАТА БЕШЕ МЪРТВА. Мерено на реалния дневник: 267 от 1674
        # делнични ръна (15.9%) са БЕЗ спот, и spot_src е {'swq': 1407, None: 267} —
        # PAXG не е дал НИТО ЕДНА котировка. Причината: GitHub Actions рънърите са в САЩ,
        # а Binance връща 451 на американски IP-та. Тествано на живо от БГ машина: Binance
        # работи (bid 4041.71). Тоест резервата беше проверена там, където не работи ботът.
        # Без спот `_advice_entry(stale_price=True)` връща ok=False и за двете посоки →
        # `pending_trade` се блокира → ботът НЕ МОЖЕ да отвори сделка на всеки шести рън.
        # ФИКС: верига от три източника. Coinbase и Kraken са американски борси — те се
        # виждат от Actions. Всеки връща собствен `src`, за да се вижда в дневника кой е дал.
        for src, url, pick in (
            ("paxg-bin", "https://api.binance.com/api/v3/ticker/bookTicker?symbol=PAXGUSDT",
             lambda q: (float(q["bidPrice"]), float(q["askPrice"]))),
            ("paxg-cb", "https://api.exchange.coinbase.com/products/PAXG-USD/ticker",
             lambda q: (float(q["bid"]), float(q["ask"]))),
            ("paxg-kr", "https://api.kraken.com/0/public/Ticker?pair=PAXGUSD",
             lambda q: (lambda t: (float(t["b"][0]), float(t["a"][0])))(list(q["result"].values())[0])),
        ):
            try:
                req = urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"})
                with urllib.request.urlopen(req, timeout=8) as r:
                    q = json.loads(r.read().decode())
                b, a = pick(q)
                # 🔴 21.08 · ДОТУК: `500 < b < 20000` — абсолютни долари на ЕДИНСТВЕНАТА
                # резервна верига. Долната граница е под всяка цена на златото от
                # 2005 г. (мъртва); горната е ЖИВА СТЕНА — мине ли я златото,
                # резервата връща None ТИХО и ботът спира да предлага входове
                # винаги когато основният фийд мълчи. Днес 4639$ е 23.2% от нея.
                # Същият шаблон като убития дефект, само с по-далечна дата.
                # Сега санитито е спрямо БАРА: по-строго И не може да остарее.
                # Без подадена референция — старите граници като резерва.
                try:
                    _р = abs(float(реф)) if реф else 0.0
                except (TypeError, ValueError):
                    _р = 0.0
                _низ = (0.80 * _р <= b <= 1.20 * _р) if _р > 0 else (500 < b < 20000)
                if 0 < b < a and _низ:                    # груб санити: злато в разумен диапазон
                    return {"bid": round(b, 2), "ask": round(a, 2), "mid": round((b + a) / 2, 2),
                            "src": src, "age_sec": None}
            except Exception as _ер:
                if следа is not None:
                    следа.append((src, type(_ер).__name__))
                continue
    return None


def _bar_range(fine, n=5):
    """A4: среден диапазон (High−Low) на последните n бара — мярка за скорост/новина."""
    try:
        if fine is None or len(fine) < n:
            return None
        w = fine.iloc[-n:]
        return float((w["High"] - w["Low"]).mean())
    except Exception:
        return None


def _spot_sane(spot, reference, base_diff, bar_rng=None, spot_jump=None, следа=None):
    """Санити: спотът е близо до ОЧАКВАНОТО (бар−базис).
    A4: при новина цената скача $20-40 за секунди; фиксиран праг би отрязал живия спот.
    T3: барът ИЗОСТАВА → освен него ползвай и СКОКА на самия спот (spot_jump = |спот
    сега − спот преди|), който реагира моментално на новината."""
    if spot is None or reference is None:
        return None
    tol = base_diff
    if bar_rng:
        tol = max(tol, 1.8 * bar_rng)
    if spot_jump:
        # F2: спотът скочи → новина. НО глич също скача → не му позволявай да се
        # САМОВАЛИДИРА отвъд това, което барът подкрепя (иначе $100 глич минава сам).
        jump_cap = 2.5 * bar_rng if bar_rng else base_diff * 2
        tol = max(tol, min(1.5 * spot_jump, jump_cap))
    # 🔴 ОДИТ-55 · КОГА И С КОЛКО Е ОТРЯЗАНО. Измерено: 267 от 2158 ръна (12.4%)
    # губят живата цена ТУК, и нито едно не оставя следа защо. Без това число
    # не може да се каже дали допускът е тесен — а прагът пази пари (един $100
    # глич минаваше сам, виж F2), значи не се пипа по догадка. Първо мерим.
    _разлика = abs(reference - spot["mid"])
    if следа is not None:
        следа.update({"разлика": round(float(_разлика), 3), "допуск": round(float(tol), 3),
                      "база": round(float(base_diff), 3),
                      "диапазон": (round(float(bar_rng), 3) if bar_rng else None),
                      "скок": (round(float(spot_jump), 3) if spot_jump else None),
                      "мина": bool(_разлика <= tol)})
    return spot if _разлика <= tol else None


def _entry_side(spot, direction):
    """Правилната страна на спреда: SHORT продава на BID, LONG купува на ASK."""
    return spot["bid"] if direction == "short" else spot["ask"]


def _to_ny(now_utc):
    """T2: UTC → Ню Йорк (America/New_York) — сам смята лятно/зимно време."""
    dt = datetime.fromisoformat(str(now_utc)) if not isinstance(now_utc, datetime) else now_utc
    return dt.replace(tzinfo=timezone.utc).astimezone(_tz("America/New_York"))


def _market_closed(now_utc):
    """A3/T2: пазарът затворен ли е — по НЮЙОРКСКО време (сам ловим DST).
    Затворено: петък 17:00 ET → неделя 18:00 ET (CME златото отваря нед 18:00 ET)."""
    try:
        et = _to_ny(now_utc); wd = et.weekday(); h = et.hour   # 0=пон … 4=пет, 5=съб, 6=нед
    except Exception:
        return False
    if wd == 5:                                        # цяла събота
        return True
    if wd == 4 and h >= 17:                            # петък след 17:00 ET
        return True
    if wd == 6 and h < 18:                             # неделя до 18:00 ET (после отваря)
        return True
    return False


# ---------- състояние: желязно четене (Ф8.2) ----------
def _запиши_атомарно(path, текст):
    """Пише през .tmp + os.replace — прекъснат процес не може да остави отрязан файл.

    🔴 21.08 · meta.json се пишеше с write_text (отрязване, после запис). Умре ли
    процесът по средата (таймаут на Actions), файлът остава отрязан → `_load_state`
    го преименува на .corrupt и почва чисто → студен старт на базиса → санитито
    реже живата цена на всеки рън. Кодът вече знаеше, че това се случва: има цял
    коментар за същото при outbox.jsonl. os.replace е атомарен и на Windows.
    """
    _tmp = path.with_suffix(path.suffix + ".tmp")
    _tmp.write_text(текст, encoding="utf-8")
    os.replace(str(_tmp), str(path))


def _load_state(path, default):
    """Повреден файл → самолекуване: преименува го и започва чисто."""
    try:
        if path.exists():
            return json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        try:
            path.rename(path.with_suffix(".corrupt"))
            print(f"  ⚠ повреден {path.name} → чист старт (старият е .corrupt)")
        except Exception:
            pass
    return default


# ---------- базис фючърс−спот (Ф9.2 + роловър Ф9.7) ----------
def _cme_pause(now_utc):
    """A5/T2: CME Globex дневна пауза 17:00-18:00 НЮ ЙОРК (ловим DST сами).
    Тогава фючърсът спира, спотът върви → базисът «скача» фалшиво. Не ре-анкервай."""
    try:
        return _to_ny(now_utc).hour == 17
    except Exception:
        return False


def _basis_update(state, key, raw_spot, bar_close, notes, cap=None, now_utc=None,
                  скок=None):        # О13: прагът за роловър е per-инструмент
    """EMA на базиса. ПОЛЗВА СУРОВИЯ спот (преди санитито) — иначе роловърът
    (скок +$25-30) реже спота, базисът замръзва и детекторът не се задейства = deadlock.
    Скок >$8 = роловър → ре-анкер, НО само ако е под cap (глич) И не сме в CME паузата (A5)."""
    if raw_spot is None or bar_close is None:
        return state.get(key, 0.0)
    now_b = bar_close - raw_spot["mid"]
    # 🔴 21.08 · Дотук `cap=40.0` стоеше като стойност ПО ПОДРАЗБИРАНЕ. И двата
    # живи извиквача подават `cap=`, но всяко бъдещо извикване, което го пропусне
    # (нов метал, сянка-двигател, копнат ред), мълчаливо възстановява точно
    # дефекта, спрял бота за два дни. Сега ПРАВИЛНОТО е безплатното, а грешното
    # иска изрично усилие.
    if cap is None:
        cap = _basis_cap(bar_close, "XAGUSD" if "_s" in str(key) else "XAUUSD")
    old = state.get(key)
    prev_bar = state.get(key + "_bar")
    state[key + "_bar"] = round(bar_close, 3)        # за кръстосана проверка следващия рън
    # НАХОДКА-B: резервата PAXG търгува с ~$1-4 премия → НЕ замърсявай базис-EMA с нея;
    # дръж последния swq-базис за конверсията, изчакай swq да се върне.
    # ОДИТ-6: резервата вече е ВЕРИГА (paxg-bin / paxg-cb / paxg-kr) → пазачът хваща по ПРЕФИКС,
    # иначе новите имена биха се промъкнали и биха замърсили базиса с крипто-премията.
    if str(raw_spot.get("src") or "").startswith("paxg"):
        # 🔴 21.08 · ТОЗИ РАНЕН ИЗХОД СТОЕШЕ ПРЕДИ ЦЕЛИЯ ПРЕКЪСВАЧ. Смисълът му е
        # верен — PAXG носи 1-4$ крипто-премия и не бива да цапа EMA-то — но
        # излизаше БЕЗ да пипне брояча, БЕЗ памет и БЕЗ нито една дума.
        # ИЗПЪЛНЕНО: 200 ръна само с резервата → базисът не мръдва от 25.52,
        # бележките са ПРАЗЕН СПИСЪК, ключът `_отказ` дори не съществува; после
        # санитито мери 21.48$ при допуск 8$ и реже живата цена. Това е БУКВАЛНО
        # заключването от 19-20.08, само през друга врата — и без брояч, който
        # да го развърже. Вратата е отворена в продукцията: paxg-cb в 66 ръна.
        # Сега: брои, обажда се, и при много дълга тишина закотвя наново — със
        # свалена премия, защото стар базис е по-лоша догадка от нов минус 2$.
        _рез = key + "_резерва"
        state[_рез] = int(state.get(_рез, 0)) + 1
        if state[_рез] >= РЕЗЕРВА_ОТКОТВИ:
            _чист = now_b - (PAXG_ПРЕМИЯ if now_b > 0 else -PAXG_ПРЕМИЯ)
            notes.append(f"🔓 базисът стои {state[_рез]} ръна без златния фийд — "
                         f"закотвям наново на {_чист:+.2f} (резерва минус премията "
                         f"{PAXG_ПРЕМИЯ:.1f}$); стар базис лъже повече от нов с премия")
            state[key] = round(_чист, 3)
            state[_рез] = 0
        elif state[_рез] >= BASIS_STUCK_N:
            notes.append(f"⚠️ базисът не се обновява от {state[_рез]} ръна — златният "
                         f"фийд мълчи, карам на резерва (пазя {state.get(key)})")
        return state.get(key, round(now_b, 3))
    if old is None:                                 # НАХОДКА-D: студен старт без глич-защита
        if abs(now_b) <= cap:
            state[key] = round(now_b, 3)
        else:
            # 🔴 21.08 · ДОТУК ТОЗИ КЛОН НЯМАШЕ ИЗХОД. При празна памет и първи
            # сампъл над тавана се връщаше 0.0 и в state НЕ СЕ ЗАПИСВАШЕ НИЩО —
            # завинаги. ИЗПЪЛНЕНО: 200 руна, ключът не се появява нито веднъж;
            # базис 0.0 → санитито мери разминаване 203.58$ при допуск 8$ →
            # живата цена се реже на ВСЕКИ рън. Пълен рън на бота го показа
            # дословно: «студен старт ... изчаквам» + «живата цена отрязана» +
            # «signal НЕ пратен». Празната памет НЕ е хипотеза: _load_state сам
            # преименува повреден meta.json на .corrupt.
            if _прекъсвач(state, key, now_b, notes, BASIS_STUCK_N,
                          "базисът (студен старт)") is None:
                notes.append(f"студен старт: базис {now_b:+.1f} извън диапазон — изчаквам "
                             f"· {state[key + '_отказ']}-и пореден")
                return 0.0
            state.pop(key + "_презакотвен", None)        # студен старт ≠ смяна на скала
            return state[key]
    elif abs(now_b - old) > (скок if скок is not None
                             else _roll_jump(bar_close, "XAGUSD" if "_s" in str(key) else "XAUUSD")):
        moved = prev_bar is not None and abs(bar_close - prev_bar) >= 0.5 * abs(now_b - old)
        if _cme_pause(now_utc):                     # A5: нощна пауза → игнорирай скока, пази базиса
            notes.append(f"скок на базиса ({now_b:+.1f}) в CME паузата — игнориран, пазя {old:+.2f}")
        elif abs(now_b) <= cap and moved:           # НАХОДКА-A: ре-анкер САМО ако и БАРЪТ скочи сходно
            notes.append(f"роловър на контракта ({old:+.2f}→{now_b:+.2f}, барът скочи) — ре-анкер")
            state[key] = round(now_b, 3)
        else:
            # 🔴 21.08 · ПРЕКЪСВАЧ СРЕЩУ ЗАКЛЮЧВАНЕ. Дотук този клон просто пазеше
            # стария базис — завинаги. Мерено: на 21.08 отхвърли 80 от 80 ръна и
            # заключи бота в момента, в който макрото се подреди за пръв път от
            # 19 дни. Порочният кръг: грешен базис → санитито реже спота →
            # «стара цена» → без вход. Пазачът срещу глич ОСТАВА, но вече не може
            # да заключи бота завинаги: щом «стария» отхвърля N ПОРЕДНИ пъти,
            # значи той вече не описва пазара, а описва себе си.
            if _прекъсвач(state, key, now_b, notes, BASIS_STUCK_N, "базисът") is None:
                notes.append("отхвърлен скок на базиса (%+.1f) — глич/несходно с бара, "
                             "пазя %+.2f · %d-и пореден отказ"
                             % (now_b, old, state[key + "_отказ"]))
    else:
        state[key] = round(old + BASIS_ALPHA * (now_b - old), 3)
        state[key + "_отказ"] = 0        # прието → броячът на отказите се нулира
        state[key + "_отказани"] = []
        state[key + "_резерва"] = 0      # златният фийд се върна
    return state[key]


TF_BASIS_ALPHA = 0.25      # EMA изглаждане на контрактния базис дневна↔интрадей
# 🔴 18.08 · ЕДИН ТАВАН ЗА ДВА МЕТАЛА БЕШЕ ГРЕШКА. 120$ е 2.7% от златото
# (4400$), но 185% от среброто (65$) — сребърен «базис» от +119$ минаваше за
# истински и влизаше в `_scores(price_adj=...)`, откъдето може да ОБЪРНЕ
# посоката на картата. Съседната `_basis_update` ВЕЧЕ е разделена по метал
# (cap 40 злато / 3 сребро) — близнакът е разделен там, но не и тук.
# Сребърният таван пази СЪЩОТО отношение: 120 × (3/40) = 9.0$ = 13.8% от 65$.
# 🔴 21.08 · БЛИЗНАКЪТ. Фиксиран таван 120$ = 6.00% от 2000$, но 2.59% от 4639$.
# Живата стойност е порасла −3.9$ (02.08) → −61.6$ (21.08), 15.8× за 19 дни;
# докстрингът долу сам мери −238$ при роловър. А тук НЯМАШЕ нито брояч, нито
# изход: мине ли веднъж тавана, функцията връща стария до края на времето.
TF_BASIS_CAP = 120.0
TF_BASIS_CAP_PCT = float(os.environ.get("TF_BASIS_CAP_PCT", "0.03"))   # 3% от цената
TF_BASIS_STUCK_N = int(os.environ.get("TF_BASIS_STUCK_N", "12"))
TF_BASIS_CAP_S = float(os.environ.get("TF_BASIS_CAP_S", "9.0"))       # |базис| над това = глич/сменен инструмент → пази стария
def _tf_basis(state, key, intra, daily, notes, days=20, cap=None):
    """ОДИТ 28.07 · КОНТРАКТЕН БАЗИС. Дневната и интрадей кривите на GC=F/SI=F от
    Yahoo НЕ са на едно ценово ниво (дневната следи по-близък контрактен месец).
    Мерено: дневен Close − интрадей Close = медиана −9.3$ (5м/60д) и −17.6$ (1час/2г),
    интрадей е ПО-ГОРЕ в 69-89% от дните, всичките 11 квартала в една посока, а при
    роловър скача до −238$. Това е РАЗЛИЧНО от meta['basis_g'] (фючърс↔Swissquote спот),
    който превежда баровете в спот-света на брокера за леджъра — той НЕ поправя refs.
    Връща стойност, която се ДОБАВЯ към интрадей цената, за да легне на дневното ниво.
    МЕДИАНА (устойчива на роловър-скокове) + EMA, с cap срещу глич."""
    _cap = cap                                       # смята се долу, щом има цена
    def _тих(причина):
        """🔴 21.08 · ДОТУК И ТРИТЕ ИЗХОДА ТУК ВРЪЩАХА СТАРОТО МЪЛЧАЛИВО, а
        прекъсвачът живееше САМО в клона «над тавана». ИЗПЪЛНЕНО с КОНТРОЛА:
        по клона «над тавана» — 60 бележки + отключване; по клона `except` —
        60 ръна, 0 бележки, брояч 0. Дефектът беше точно в разликата.
        Тук няма ЖИВА стойност, с която да се презакотви, затова след N поредни
        стойността пада на 0.0 и се обявява: нулата е честно «не знам», а старо
        число е тихо твърдение, което мести дневните референции на 6 рамки."""
        # 🔴 21.08 · СВОЙ БРОЯЧ. Дотук този клон делеше `_отказ` с `_прекъсвач`,
        # но никога не пълнеше `_отказани` — тоест вдигаше прага за медианата,
        # без да дава нито едно наблюдение за нея. Двете беди са различни:
        # тук НЯМА жива стойност (падаме на 0.00), там ИМА (закотвяме на медиана).
        _бк = key + "_тих"
        state[_бк] = int(state.get(_бк, 0)) + 1
        if state[_бк] >= TF_BASIS_STUCK_N:
            notes.append(f"🔓 контрактният базис не се пресмята {state[_бк]} ръна "
                         f"({причина}) — пускам го на 0.00 вместо да твърдя старото")
            state[key] = 0.0
            state[_бк] = 0
            return 0.0
        notes.append(f"контрактният базис не се пресмята ({причина}) — пазя стария "
                     f"· {state[_бк]}-и пореден отказ")
        return state.get(key, 0.0)

    try:
        if intra is None or daily is None or len(intra) == 0 or len(daily) == 0:
            return _тих("няма данни")
        r = intra.resample("1D").agg(Close=("Close", "last")).dropna()
        j = r.join(daily[["Close"]], how="inner", rsuffix="_d")
        if len(j) < 5:                                   # малко застъпване → не гадай
            return _тих("малко застъпване")
        now = float((j["Close_d"] - j["Close"]).tail(days).median())
        if _cap is None:                                 # таван ПО ЦЕНА, не закован
            _ц = abs(float(j["Close_d"].iloc[-1]))
            _cap = max(TF_BASIS_CAP, TF_BASIS_CAP_PCT * _ц)
        if not np.isfinite(now) or abs(now) > _cap:
            if np.isfinite(now):
                # СЪЩИЯТ прекъсвач: N поредни отказа значат, че ПАЗЕНОТО е старо.
                # Дотук тази функция нямаше дори БРОЯЧ — мине ли веднъж тавана,
                # връщаше стария до края на времето, мълчаливо.
                _нов = _прекъсвач(state, key, now, notes, TF_BASIS_STUCK_N,
                                  "контрактният базис")
                if _нов is not None:
                    return _нов
            notes.append("контрактен базис %+.1f$ извън диапазон — пазя стария "
                         "· %d-и пореден отказ" % (now, state.get(key + "_отказ", 0)))
            return state.get(key, 0.0)
        old = state.get(key)
        state[key] = round(now if old is None else old + TF_BASIS_ALPHA * (now - old), 3)
        state[key + "_отказ"] = 0                        # прието → броячите се нулират
        state[key + "_тих"] = 0
        state[key + "_отказани"] = []
        return state[key]
    except Exception as _e:
        return _тих(type(_e).__name__)


