ПАЗАЧ_ПРОЗОРЕЦ_Ч = float(os.environ.get("ПАЗАЧ_ПРОЗОРЕЦ_Ч", "4"))


def _пазач_n(guard, key, now_utc):
    """Колко стопа брои пазачът СЕГА (с давност), а не «колко има днес».

    Връща записания брой, докато последният стоп е по-млад от прозореца,
    и 0 след това. При ПАЗАЧ_ПРОЗОРЕЦ_Ч=0 връща брояча както преди.
    Липсва ли клеймо (стар guard.json), пази СТАРОТО поведение — да не
    отпуши мълчаливо нещо, което не е мерено.
    """
    n = int((guard or {}).get(key, 0) or 0)
    if n <= 0 or ПАЗАЧ_ПРОЗОРЕЦ_Ч <= 0:
        return n
    _клеймо = (guard or {}).get(str(key) + "_t")
    if not _клеймо:
        return n
    try:
        _ч = ((datetime.fromisoformat(str(now_utc))
               - datetime.fromisoformat(str(_клеймо))).total_seconds() / 3600.0)
    except Exception:
        return n
    return n if 0 <= _ч < ПАЗАЧ_ПРОЗОРЕЦ_Ч else 0


def _пазач_плюс(guard, key, now_utc):
    """Брои стоп И запомня КОГА — без клеймото давността е сляпа."""
    guard[key] = int(guard.get(key, 0) or 0) + 1
    guard[str(key) + "_t"] = now_utc
    return guard[key]
