# Тоест `fresh` е положителен на ВСЕКИ хоризонт; `day1` не е; останалите — не.
# Затова таванът се вдига САМО за `long·fresh`. Път назад: една променлива.
# ⚠️ 26.08 · и тази мярка е по КЛЕТКА, значи е засегната от надничането.
# Реплеят на ЖИВИЯ дневник (2795 блокирани ръна, 23 → 64 карти) НЕ Е
# засегнат — той брои карти, не пари, и не ползва клетки.
# Виж пълната поправка при ТАВАН_СДЕЛКИ.
# 🔴🔴 25.08 (втора мярка, В НОВАТА РЕШЕТКА) · 24ч → 480ч.
# Първата мярка беше при таван 1 сделка / пазач 2 стопа / пауза 45 мин.
# Доказах, че спирачките ВЗАИМОДЕЙСТВАТ, затова я направих наново при
# живата решетка (5 · 1 стоп · 15мин), ЛОНГ · клетките на гейта, 19.9 г:
#
#   таван на възрастта  сделки  /год  $/сделка   $ НА ГОДИНА    просадка
#    6 часа               580   29.2   +2.334   +68$ [+22,+112]    338$
#   12 часа ← БЕШЕ        662   33.3   +2.420   +81$ [+29,+132]    327$
#   18 часа               702   35.3   +2.261   +80$ [+24,+134]    397$
#   24 часа               754   37.9   +2.144   +81$ [+23,+137]    418$
#   48 часа               821   41.3   +2.481  +102$ [+40,+161]    372$
#   БЕЗ таван             871   43.8   +2.741  +120$ [+58,+182]    301$
#
# «БЕЗ таван» бие по ВСИЧКО наведнъж: най-много пари, най-висока ДОЛНА
# граница И най-МАЛКА просадка. Същото важи и в старата решетка.
#
# И РЕПЛЕЙ НА ЖИВИЯ ДНЕВНИК (4488 ръна, 22.8 дни) — кой блокира какво:
#   пауза 45 · възраст 12ч   23 карти  1.01/ден   ВЪЗРАСТТА реже 2795 ръна
#   пауза 15 · възраст 24ч   31        1.36
#   пауза 15 · възраст 48ч   34        1.49
#   пауза 15 · БЕЗ таван     64        2.81   ← почти 3× повече карти
# 2795 ръна умират на това правило — повече от всички други спирачки
# взети заедно. А 2.81 карти на ден НЕ Е спам (спамът беше 17-21/ден).
# Прагът от 3-6 часа между напомнянията върши истинското ограничаване;
# таванът е бил само тапа отгоре.
#
# ЗАЩО 240/480, А НЕ БУКВАЛНО «БЕЗ»: моята «възраст» в мярката се брои от
# началото на поредицата в клетката, а ботът брои от смяната на КЛЮЧА —
# двете не са едно и също. Най-старият жив ключ е 115ч, най-старият в
# мярката 110ч. 240ч е «на практика без таван» за всичко реално, но пази
# от ЗАМРЪЗНАЛА дъска, която да пали вечно. Клетъчната стълба остава.
MAX_AGE_ПРЕСЕН = float(os.environ.get("MAX_AGE_ПРЕСЕН", "480"))


def _max_age_h(direction, streak_n):
    """Таванът на възрастта — ПО КЛЕТКА, защото мереното е различно.

    `long·fresh` → по-широк (положителен на всеки мерен хоризонт).
    Всичко останало → както е било (мерено нула, минус или разбъркано).
    """
    if direction == "long" and _cell_name(streak_n) == "fresh":
        return MAX_AGE_ПРЕСЕН
    return REOFFER_MAX_AGE_H


def _reoffer_h(direction, streak_n):
    """Часовете между две напомняния — ПО КЛЕТКА, защото мереното е различно.

    `day1`/`fresh` за ЛОНГ → по-кратко (мерено +4.03$ с чист интервал).
    Всичко останало → както е било (мерено нула или минус при свиване).
    """
    if direction == "long" and _cell_name(streak_n) in ("day1", "fresh"):
        return REOFFER_H_ПРЕСЕН
    return REOFFER_H
# 🔴 21.08 · 4ч → 2ч. Тази карта НЕ отваря сделка и НЕ пипа стоп-пазача — тя е
# ИНФОРМАЦИЯ. Мерено: за 119 ръна, в които гейтът каза ДА в 116, излязоха ДВЕ
# карти. При 2 часа стават ~6 на делник — колкото собственикът да вижда нивата,
# докато решава сам. Мереното правило за ВХОД не се пипа с нищо.
STANDING_H = int(os.environ.get("STANDING_H", "2"))
_STANDING_СТАРО = 4    # ОДИТ-20: беше 8 → изпратени общо 6 карти за целия живот на бота,
                       # и то само в 08:01 и 16:01. На 4 часа стават ~3 на делник — колкото
                       # човек да види, че посоката се държи, без да е спам. Тази карта НЕ
                       # отваря сделка и НЕ пипа стоп-пазача, затова честотата ѝ е безопасна.
                       # (реплей показа 4 от 9 дни с НУЛА златни карти само от тавана)
# 🔴 21.08 · ТВЪРДЕНИЕТО «вход в 02:20 е шум» Е ОБОРЕНО С МЕРЕНЕ.
# На 22-годишната лента, блоков бутстрап по ден, доставената геометрия:
#     long · ВЪТРЕ в 8-22 София      +0.423$  [-0.591, +1.446]  ⚪ шум
#     long · ИЗВЪН 8-22 София        +0.864$  [+0.073, +1.654]  ✅ ЧИСТ ПЛЮС
#     long · 14-21 UTC (американска) +1.174$  [+0.014, +2.317]  ✅ ЧИСТ ПЛЮС
# Тоест изключените часове са ПО-ДОБРАТА половина, а не шумът.
# Прозорецът се отваря; пътят назад е една променлива от средата.
REOFFER_LO = int(os.environ.get("REOFFER_LO", "0"))
REOFFER_HI = int(os.environ.get("REOFFER_HI", "23"))
def _advice_entry(direction, streak_n, stats, fast, shield, guard_n, sym="XAUUSD",
                  stale_price=False, dd20=None, trace=None):
    """(текст, ok) за реда «ВЛИЗАЙ». В1: сребро цитира САМО сребърни числа.
    Г2: изходът е ясен — ДА / ИЗЧАКАЙ / НЕ. В5: губещ клас се казва явно.
    ОДИТ-15/б: `trace` (по избор) казва КОЙ ПЛАСТ е решил. Без него дневникът
    записваше кофата дори когато решението е дошло от стоп-пазача, щита или
    старата цена — тоест ПРЕДИ клетката изобщо да бъде погледната. Който после
    брои «колко отказа клетката mixed», брои чужди откази."""
    # 🔴 ОДИТ-49 · БЕЗ ЧИСЛА НЯМА ВХОД — ПЪРВАТА ПРОВЕРКА, преди всичко друго.
    # Изпълнено преди поправката: празна статистика → «ДА (малък размер)»,
    # липсващ `fresh` → «ДА», None и боклук → AttributeError. А `stats = {}` е
    # точно каквото прави ботът, когато файлът не се чете.
    # Същият принцип като О1: не виждам ли — не отварям.
    if СТАТ_ЗАДЪЛЖИТЕЛНА:
        _добра = isinstance(stats, dict) and isinstance(stats.get("fresh"), dict)
        if not _добра:
            if trace is not None:
                trace["by"] = "липсва статистика"
            return ("НЕ — историческите числа не се четат, не предлагам вход", False)

    def _by(k):
        if trace is not None:
            trace["by"] = k

    def _мерено(seg, етикет):
        """ОДИТ-28: числата от бектеста НЕ отиват при собственика — отиват в дневника.
        Той иска присъда; проверимостта остава за одит-робота и за мен."""
        if trace is not None and seg:
            # 🔴 21.08 · +`дни`. НЕ е дубликат на `n`: 4019 входа са разпръснати в
            # само 208 РАЗЛИЧНИ ДНИ. Карта, която каже «4 019 случая», подсказва
            # 4 019 независими залога — а те не са. Затова текстът ще води с ДНИТЕ.
            trace["мерено"] = {"кофа": етикет, "win": seg.get("win"), "net": seg.get("net"),
                               "n": seg.get("n"), "lo": seg.get("lo"), "hi": seg.get("hi"),
                               "дни": seg.get("дни")}

    if guard_n >= ПАЗАЧ_СТОПОВЕ:
        _by("стоп-пазач")
        # ОДИТ-35: «два» беше заковано, а `guard_n` може да е 3, 4…
        # При трети стоп картата лъжеше за собствения му ден.
        # 🔴 25.08 · «1 стопа» е грешно. Числото се смени на 1 и граматиката
        # трябва да го следва — картата отива при човек, не в лог.
        return (f"НЕ — {guard_n} {'стоп' if guard_n == 1 else 'стопа'} днес "
                f"в тази посока, спирам до утре"), False
    if shield and direction == "short":
        _by("US-щит")
        return f"НЕ — американски данни {_shield_sofia_label()}, чакам ги", False
    if stale_price:                                      # Г9: спотът недостъпен → цената е стара
        _by("стара цена")
        return "ИЗЧАКАЙ — живата цена мълчи, само лимитна поръчка", False
    is_gold = sym == "XAUUSD"
    # 🔴 F24г · СРЕБЪРНИТЕ ВХОДОВЕ СА ИЗКЛЮЧЕНИ ПО ПОДРАЗБИРАНЕ.
    # F24 премери 12858 сделки: след реалистичен спред не оцелява нито една
    # клетка. Адверсарната проверка отиде по-дълбоко — сделките с НУЛА мъртви
    # бара в прозореца дават −0.0298$ ПРЕДИ какъвто и да е спред (n=1526), тоест
    # «ръбът» изобщо не съществува, а числото, което приличаше на такъв, идва от
    # дни, които данните не са записали (27% плоски барове, 53.6% с H−L<|ΔC|).
    # Стои ПРЕДИ клетките — за да не зависи от това дали някой е свалил спреда.
    if (not is_gold) and not СРЕБРО_ВХОД:
        _by("сребро изключено")
        return ("НЕ — среброто е изключено: няма измерим ръб, а данните за него "
                "не стигат, за да се мери"), False
    # 🔴 ОДИТ-59 · СРЕБРО + РАЗБЪРКАНО МАКРО = НЯМА ИЗМЕРВАНЕ = НЯМА ВХОД.
    # Мерено: 1518 от 1518 ръна с оценка са `mixed`, а среброто е отваряло
    # сделки в тях по числата на ДРУГА клетка.
    if (not is_gold) and streak_n == 0 and СРЕБРО_MIXED != "stale":
        _св = (stats.get("silver", {}) or {}).get(direction, {}) or {}
        if not isinstance(_св.get("mixed"), dict):
            _by("клетка")
            return ("НЕ — доларът и лихвите се карат, а за среброто такъв "
                    "пазар не е мерен"), False
    if is_gold:
        fr = stats.get("fresh", {}).get(direction, {})
        seg_fresh = fr.get("day1" if streak_n == 1 else "fresh", {})
        seg_stale = fr.get("stale", {})
        # ОДИТ-8: смесено макро (стрийк 0) вече има СВОЯ клетка. Липсва ли я (стар
        # stats файл) — падаме на `stale`, тоест точно старото поведение.
        seg_mixed = fr.get("mixed") or seg_stale
        seg_near = fr.get("near_high") or {}          # ОДИТ-16; липсва → мъртва клетка
        src = "пресен ден-" + str(streak_n)
    else:                                                # В1: сребро — от stats['silver'], не злато!
        sv = stats.get("silver", {}).get(direction, {})
        # 🔴 F24 · ДОТУК ТУК ПИШЕШЕ само `sv.get("fresh")` — тоест ПЪРВИЯТ ден се
        # съдеше по клетката за ден 2-3. Златото има `day1` от самото начало;
        # среброто нямаше такава измерена клетка, затова падаше на съседната.
        # F24 я премери (n=303) → сега всеки метал се съди по СВОЯТА клетка.
        seg_fresh = sv.get("day1" if streak_n == 1 else "fresh") or sv.get("fresh", {})
        seg_stale = sv.get("stale", {})
        # 🔴 ОДИТ-59 · ДОТУК ТУК ПИШЕШЕ `sv.get("mixed") or seg_stale` — тоест
        # разбърканото макро се съдеше по клетката «остарял сигнал». За златото
        # точно това сливане беше разделено на 04.08: mixed −0.47$ срещу
        # stale +0.94$. Среброто просто няма измерена клетка за това състояние.
        seg_mixed = sv.get("mixed") or (seg_stale if СРЕБРО_MIXED == "stale" else {})
        seg_near = {}                                 # ОДИТ-16: среброто НЯМА такова измерване
        src = "сребро пресен"
    # F4: «ден N» валиден само за ЗЛАТОТО (стрийкът е от златната цена); сребро → без ден-номер
    dn = f"ден {streak_n}" if is_gold else "по макро-подреждане"
    if 1 <= streak_n <= 3:
        seg = seg_fresh
        # ── ОДИТ-16 · «ШОРТ ДО ВЪРХА». Единственото, което този клон може да направи, е да
        # превърне ОТКАЗ в ПУСКАНЕ, и то САМО за ЗЛАТО-ШОРТ при стрийк 2-3. Днес този
        # случай е БЕЗУСЛОВЕН ОТКАЗ (short/fresh: n=5162, нето −0.71, нулата е в интервала)
        # → нищо съществуващо не се отнема. Няма ли `near_high` в stats (стар файл) или
        # няма dd20 (стар извикващ) → клонът МЪЛЧИ и ботът е точно какъвто беше.
        # Стои СЛЕД стоп-пазача, щита и старата цена — те продължават да го бият.
        if (is_gold and direction == "short" and 2 <= streak_n <= 3
                and dd20 is not None and np.isfinite(dd20) and dd20 < NEAR_HIGH_DD20
                and seg_near.get("n", 0) >= MIN_N and seg_near.get("net", 0) > 0
                and not _noise(seg_near)):
            _by("клетка"); _мерено(seg_near, "връх-шорт")
            return "ДА — злато на върха си от 20 дни, обръща се" + _fast(fast), True
        # ОДИТ-10: шум-пазачът важи и ТУК. Дотук само `mixed`/`stale` го имаха, а
        # `day1`/`fresh` минаваха на голо «нето>0» — тоест short/day1 (+0.44$, интервал
        # [−1.07 .. +1.85], тоест НУЛАТА е вътре) щеше да пуска вход върху шум.
        # Измерването, което избра това правило, го третираше като ОТКАЗ — гейтът трябва
        # да прави същото, иначе ботът работи по едни числа, а е оценен по други.
        if seg.get("n", 0) >= MIN_N and (seg.get("net", 0) <= 0 or _noise(seg)):
            _by("клетка"); _мерено(seg, src)
            # 🔴 F24 · «ИЗЧАКАЙ» обещава, че утре може да е друго. За среброто НЕ
            # може: мерено на 12858 сделки, след спред 0.03$ не оцелява нито една
            # клетка, а всяка лонг клетка сменя знака между епохите. Картата да
            # обещава промяна, която няма да дойде, е лъжа с добри намерения.
            if not is_gold:
                return "НЕ — среброто няма измерен ръб над спреда", False
            return "ИЗЧАКАЙ — прясно е, но такива случаи не носят нищо", False
        _by("клетка"); _мерено(seg, src)
        # 🔴 ОДИТ-30 · ОБЪРНАТ ЗНАК, качен от мен днес. В кода `m_l` (лонг
        # стрийк) значи доларът ПАДА и лихвите ПАДАТ — това вдига златото
        # (`macro["долар"]=True` е `-(dx.pct_change(20))>0`). Първата ми
        # версия писа «доларът и лихвите НАГОРЕ» на карта за ПОКУПКА —
        # точно обратното на истината, върху реда, по който той решава.
        _накъде = "падат" if direction == "long" else "растат"
        _откога = (("от днес" if streak_n == 1 else f"вече {streak_n} дни")
                   if is_gold else "днес")
        _ефект = "вдига" if direction == "long" else "сваля"
        # 🔴 ОДИТ-59б · МЕТАЛЪТ БЕШЕ ЗАКОВАН. Сребърна карта казваше «това вдига
        # ЗЛАТОТО» — редът, по който собственикът решава, назоваваше чужд метал.
        # Мерено: засяга всичките сребърни клонове със стрийк 1-3; в живия
        # sent_log вече има пратени такива карти.
        _мет = "златото" if is_gold else "среброто"
        return (f"ДА — доларът и лихвите {_накъде} {_откога}, това {_ефект} {_мет}"
                + _fast(fast)), True
    # ОДИТ-8 (04.08): кофата `stale` СЛИВАШЕ две различни състояния — «макрото ДНЕС е
    # смесено» (стрийк 0) и «сигналът е ОСТАРЯЛ от дни» (стрийк 4+). Мерено на същите
    # 114813 сделки, блоков бутстрап по ден: long/mixed −0.04$ (ШУМ, n=40094) срещу
    # long/stale +1.18$ (ПЕЧЕЛИ, n=12062). Слети даваха +0.24$ — размит сигнал, и ботът
    # пращаше «ДА (слаб)» на 40 хиляди сделки, които не носят нищо.
    # Разделени: +0.518 → +1.469$/сделка, общо +32956 → +34571$. Картите падат от 152
    # на 53 дни/година — но махнатите са именно тези на нулата.
    mixed = streak_n == 0
    seg = (seg_mixed if mixed else seg_stale)
    if seg.get("n", 0) >= MIN_N and (seg.get("net", 0) < 0 or _noise(seg)):
        # НЕ обвинявай «макрото» (то може да е за тази посока, напр. 0/3 подкрепя шорт) —
        # губещ е ИСТОРИЧЕСКИЯТ КЛАС на този сетъп.
        _by("клетка"); _мерено(seg, "mixed" if mixed else "stale")
        if not is_gold:
            return "НЕ — среброто няма измерен ръб над спреда", False
        if mixed:
            return "НЕ — доларът и лихвите се карат днес", False
        _откога = f"отпреди {streak_n} дни"
        return f"НЕ — подреждането е {_откога}, изхабило се е", False
    # положителен-но-слаб клас: текстът СЪОТВЕТСТВА на action (следи се) — «ДА (слаб)», не «ИЗЧАКАЙ»
    _by("клетка"); _мерено(seg, "mixed" if mixed else "stale")
    if mixed:
        return "ДА (малък размер) — макрото мълчи, само по цена" + _fast(fast), True
    _откога = (f"отпреди {streak_n} дни" if is_gold else "отдавна")
    return f"ДА (малък размер) — подреждането е {_откога}" + _fast(fast), True


def _cell_name(streak_n):
    """ОДИТ-15: ИМЕТО на кофата, с която `_advice_entry` съди — за да може решението
    да се ЗАПИШЕ в дневника. Дотук гейтът беше единственото важно решение на бота
    БЕЗ трайна следа: `macro` и `board` се пишат (ОДИТ-5), присъдата — не. Затова
    «защо отказа този шорт на 23.07» се четеше по археология в текста на картите,
    а картите отпреди v6.0 дори не носят причината.
    Пази се синхронно с `_advice_entry` чрез ИЗПЪЛНЯВАН тест (П18), не чрез греп."""
    if streak_n == 1:
        return "day1"
    if 2 <= streak_n <= 3:
        return "fresh"
    if streak_n == 0:
        return "mixed"
    return "stale"


def _noise(seg):
    """ОДИТ-8: клетка, чийто 95% интервал минава през нулата, е ШУМ — не ръб.
    Празни lo/hi (стар stats файл) → не съдим, връщаме False (старото поведение).

    🔴 F24 (18.08) · ВТОРО УСЛОВИЕ: клетка, която сменя ЗНАКА между епохите, също
    е шум — дори интервалът ѝ да е изцяло над нулата. Такова число описва един
    отминал пазар, не правило. Клетки без `_епохи_съгласни` (златото) не се
    засягат — `.get` връща None и условието мълчи.

    🔴 ПОПРАВКА НА СОБСТВЕНОТО МИ ТВЪРДЕНИЕ (F24г, същия ден). Писах «ВСЯКА
    сребърна лонг клетка сменя знака». На СУРОВОТО нето това е вярно само за
    `fresh` и `mixed`; `day1` (+0.0986 / +0.0019) и `stale` (+0.0397 / +0.0150)
    са положителни в ДВЕТЕ епохи, и смяната им се появява едва СЛЕД изваждането
    на спреда. Значи епохите не са независимо второ основание — за половината
    клетки са преразказ на теста за разхода. Условието остава полезно; описанието
    беше по-силно от мереното."""
    lo, hi = seg.get("lo"), seg.get("hi")
    if seg.get("_епохи_съгласни") is False:
        return True
    return lo is not None and hi is not None and lo <= 0 <= hi


def _сребро_разход(stats, notes=None):
    """F24 · СУРОВИТЕ сребърни клетки минус реалния спред.

    Златните клетки са мерени на 7.96М едноминутни бара С ДВЕТЕ СТРАНИ на спреда
    — разходът е ВЪТРЕ в числата. Сребърните са от дневни барове по средна цена,
    без спред. Да ги сравняваш направо значи да мериш двата метала с различен
    аршин. Тук се изравняват.

    Няма ли `_сурово` (стар stats файл) — клетката се оставя както си е.
    """
    sv = (stats or {}).get("silver")
    if not isinstance(sv, dict):
        return 0
    пипнати = 0
    for посока in ("long", "short"):
        клетки = sv.get(посока)
        if not isinstance(клетки, dict):
            continue
        for име, а in клетки.items():
            if not isinstance(а, dict):
                continue
            сур = а.get("_сурово")
            if not isinstance(сур, dict):
                continue
            for к in ("net", "lo", "hi"):
                v = сур.get(к)
                if v is not None:
                    а[к] = round(float(v) - СРЕБРО_СПРЕД, 4)
            # 🔴 F24б · СЪГЛАСИЕТО НА ЕПОХИТЕ СЕ СМЯТА ТУК, НЕ ВЪВ ФАЙЛА.
            # Първата ми версия го записа в JSON-а с фиксиран разход 0.03$ →
            # свалеше ли собственикът `СРЕБРО_СПРЕД` до 0.00, клетките пак
            # оставаха мъртви и «пътят назад» беше декорация. Мереното: сурово
            # day1/long дава +0.0986$ (2000-2012) и +0.0019$ (2013-2026) — двете
            # ПОЛОЖИТЕЛНИ; след 0.03$ разход стават +0.0686 и −0.0281, тоест
            # РАЗЛИЧНИ. Един и същ ред данни сменя присъдата според разхода,
            # затова разходът трябва да е вътре в сметката, не преди нея.
            еп = а.get("_епохи")
            if isinstance(еп, dict):
                _з = [float(v) - СРЕБРО_СПРЕД for v in еп.values() if v is not None]
                # само при ДВЕ измерими епохи има какво да се сравнява
                а["_епохи_съгласни"] = (len(_з) < 2
                                        or all(x > 0 for x in _з)
                                        or all(x < 0 for x in _з))
            пипнати += 1
    if пипнати and notes is not None and СРЕБРО_СПРЕД != 0.03:
        notes.append(f"🥈 сребърните клетки са смятани със спред {СРЕБРО_СПРЕД}$ "
                     f"(по подразбиране 0.03$)")
    return пипнати


def _zones(h1, direction):
    """ЗОНИТЕ ОТ ИНДИКАТОРА (FVG) — качество на входа. ОДИТ-14 (05.08).

    Индикаторът AERO PRO ги рисува от седмици; ботът не ги ползваше. Измерено на
    114813 сделки под доставената геометрия, върху допуснатите от гейта 31854:

       A · зона отдолу + чисто отгоре   32.6%   +1.998$  [+1.41 .. +2.59]  ПЕЧЕЛИ
       B · едно от двете                42.5%   +1.457$  [+0.85 .. +2.05]  ПЕЧЕЛИ
       C · нито едно                    24.9%   +0.502$  [−0.19 .. +1.19]  ШУМ
       (гейтът сам: +1.396$)

    Подредбата A>B>C е чиста — шумово разделяне не се подрежда така. Устойчива е
    и в четирите четвъртини на 22 години, и е НАЙ-СИЛНА в последната (2021-2026:
    +0.819 → +1.145). Късмет-тест: 0 от 60 случайни подмножества със същия размер
    бият резултата (средно +1.380, максимум +1.609 срещу +1.998).

    НИЩО НЕ СЕ РЕЖЕ — само размерът се степенува 1.00/0.67/0.33, при което рискът
    на собственика ОСТАВА таван: +1.396 → +1.597$ на единица риск, при 31% по-малко
    пари в риск.

    FVG (fair value gap) = празнина, оставена от бърз ход: бичи, ако low[i] > high[i-2].
    Запълва се, когато цената се върне под долния ѝ ръб. Ползва се 1-ЧАСОВАТА рамка —
    измерена като най-силната (15м и 4ч дават по-малко).
    Връща (клас, текст) — при липса на данни ('B', ''), тоест НЕУТРАЛНО, не наказва."""
    try:
        if h1 is None or len(h1) < 30:
            return "B", ""
        hi = h1["High"].values[-400:]; lo = h1["Low"].values[-400:]
        bull = bear = None                       # долен ръб на бичи · горен ръб на мечи
        for i in range(2, len(hi)):
            if lo[i] > hi[i - 2]:
                bull = float(hi[i - 2])
            if bull is not None and lo[i] < bull:
                bull = None                      # запълнена
            if hi[i] < lo[i - 2]:
                bear = float(lo[i - 2])
            if bear is not None and hi[i] > bear:
                bear = None
        if direction == "short":                 # огледално за шорт
            bull, bear = bear, bull
        have, clean = bull is not None, bear is None
        if have and clean:
            return "A", f"🟩 <b>СИЛНА ЗОНА</b> — празнина под цената ({_fmt(bull, 2)}), чисто отгоре"
        if have:
            return "B", f"🟨 зона отдолу ({_fmt(bull, 2)}), но има насрещна отгоре"
        if clean:
            return "B", "🟨 чисто отгоре, но без зона-опора отдолу"
        return "C", "🟧 без опора отдолу и с насрещна зона отгоре"
    except Exception:
        return "B", ""


# 🔴 26.08 · ТЕЖЕСТИТЕ БЯХА ИЗБРАНИ «НА ТРЕТИ», НЕ МЕРЕНИ.
# 1.00 / 0.67 / 0.33 е красива стълба, но никъде нямаше число зад нея.
# МЕРЕНО на 6846 входа, `_zones` викана ТОЧНО както я вика ботът (от
# 1-часовата рамка), доставената геометрия, интервали блоков бутстрап
# по ден, ЛОНГ · клетките на гейта (клетките са с .shift(1) — без
# надничане напред, след поправката от 26.08):
#
#   зона A  n=410  +2.687$ [+0.90, +4.35] ✅  отношение към A = 1.00
#   зона B  n=401  +2.395$ [+0.38, +4.17] ✅  отношение към A = 0.89
#   зона C  n=397  +1.654$ [−0.24, +3.50] ⚪  отношение към A = 0.62
#
# Тоест зона B печели 89% от A, а получаваше 67% размер; зона C печели
# 62%, а получаваше 33% — почти двойно подрязана. `_сила` сама казва
# «дялът Е множителят»; тук дялът НЕ беше множителят.
#
# НОВИТЕ ТЕЖЕСТИ са мерените отношения, закръглени НАДОЛУ заради
# несигурността:
#   A = 1.00  (мерено 1.00)
#   B = 0.85  (мерено 0.89 — надолу, защото A и B са статистически
#              НЕРАЗЛИЧИМИ: интервалите им се застъпват почти изцяло)
#   C = 0.50  (мерено 0.62 — надолу ПОВЕЧЕ, защото интервалът на C
#              минава през нулата, тоест C НЕ Е доказано печеливша)
#
# ⚠️ ТОВА КАЧВА РАЗМЕРА, а размерът е най-опасната промяна. Затова:
#   · нито една зона не отива на пълен размер освен A (както беше)
#   · C остава под половината, докато не се докаже
#   · пътят назад е една дума: ZONE_W_СТАРИ=да
ZONE_W = ({"A": 1.00, "B": 0.67, "C": 0.33}
          if os.environ.get("ZONE_W_СТАРИ") == "да"
          else {"A": 1.00, "B": 0.85, "C": 0.50})   # ОДИТ-14: рискът е ТАВАН


def _скорост(meta, spot, now_utc, notes=None):
    """Колко се е движила ЖИВАТА цена за ~10 минути. Пази си своя история.

    Връща (долари_за_10мин | None, знам_ли_изобщо).
    Второто е False, когато няма достатъчно пресни проби (например след
    дупка) — тогава картата казва «не знам», вместо да мълчи подвеждащо.
    """
    _м = None
    if isinstance(spot, dict):
        _м = spot.get("mid")
    elif isinstance(spot, (int, float)):
        _м = spot
    _ист = list(meta.get("спот_проби") or [])
    if _м is not None:
        try:
            _ист.append([str(now_utc), round(float(_м), 3)])
        except (TypeError, ValueError):
            pass
    _ист = _ист[-БЪРЗ_ПАМЕТ:]
    meta["спот_проби"] = _ист
    if _м is None or len(_ист) < 2:
        return None, False
    try:
        _сега = datetime.fromisoformat(str(now_utc))
    except Exception:
        return None, False
    # най-старата проба ВЪТРЕ в прозореца 8-14 минути назад
    _най = None
    for _t, _p in _ист[:-1]:
        try:
            _д = (_сега - datetime.fromisoformat(str(_t))).total_seconds() / 60.0
        except Exception:
            continue
        if 6.0 <= _д <= 16.0:
            _най = _p
            break
    if _най is None:
        # няма пресен ориентир (дупка, първи рън) → НЕ мълчи, кажи го
        return None, False
    return round(abs(float(_м) - float(_най)), 1), True


def _fast(fast):
    """ОДИТ-28: «БЪРЗ ПАЗАР ±$12/10мин» е телеграма. Казва се с думи."""
    # 🔴 26.08 · `fast=False` вече значи «спокойно», а `fast=None` значи
    # «НЕ ЗНАМ» (няма пресни проби — след дупка или първи рън). Мълчание при
    # незнание е подвеждащо точно когато е най-опасно.
    if fast is None:
        # 🔴 26.08 · дълго беше «не знам колко бърз е пазарът (няма пресни
        # проби)» — 55 знака и три карти минаха тавана от 400. Правилото за
        # телефон е по-старо. Смисълът остава: не знам скоростта → лимитна.
        return " · скоростта неясна — лимитна"
    return f" · бърз пазар ±${fast:.0f}/10мин, само лимитна" if fast else ""


def _reentry_ban(meta, direction, streak_n, why=None, set_it=False, ден=None):
    """О4 · забраната за ре-влизане ПЕРСИСТИРА, докато същият пресен стрийк е жив.

    Дотук `_reentry_verdict` пазеше САМО рънa на затварянето — следващият рън,
    пет минути по-късно, минаваше покрай нея и отваряше точно шорта, за който
    същото правило казва, че губи −2.75$/сделка (мерено на 19.7 години).

    Ключът носи ПОСОКАТА и СТРИЙКА. Смени ли се стрийкът (макрото се преподреди
    или изтече), забраната пада САМА — не се трие на ръка и не увисва.
    """
    ключ = "reentry_ban"
    ст = meta.get(ключ) or {}
    # 🔴 21.08 · ЗАПИСЪТ НЯМАШЕ ДАТА, а причината му обещава срок: «2 стопа днес
    # в тази посока — спирам ДО УТРЕ». Нищо в записа не можеше да изпълни това
    # обещание: той падаше само при СМЯНА на посоката или стрийка. При застоял
    # дневен бар (празник, тънка сесия — ботът има отделна бележка за това)
    # стрийкът стои същият с дни и забраната се произнася наново.
    # ИЗПЪЛНЕНО: ден 1 → забранен · ден 2, същият стрийк → пак забранен.
    # `guard.json` СЕ нулира по дата; замразената му причина — не. Сега и тя.
    if set_it and why:
        meta[ключ] = {"dir": direction, "streak": int(streak_n), "why": why, "date": ден}
        return True, why
    if ден and ст.get("date") and str(ст.get("date")) != str(ден):
        meta.pop(ключ, None)          # «до утре» вече наистина значи «до утре»
        return False, ""
    if (ст.get("dir") == direction and int(ст.get("streak", -1)) == int(streak_n)
            and 1 <= int(streak_n) <= 3):
        return True, ст.get("why") or "ре-влизането е спряно за този сигнал"
    if ст and (ст.get("dir") != direction or int(ст.get("streak", -1)) != int(streak_n)):
        meta.pop(ключ, None)          # стрийкът се смени → забраната пада сама
    return False, ""


def _reentry_verdict(direction, streak_n, shield, guard_n):
    """(може_ли, защо) за ре-влизане след приключена сделка — F18 правилата."""
    # ОДИТ-35 · единственият текст, който не бях пипал днес — още носеше
    # «F18», «US-щит» и латиница. Той влиза в реда «♻️ ново влизане».
    if guard_n >= ПАЗАЧ_СТОПОВЕ:
        return False, (f"{guard_n} {'стоп' if guard_n == 1 else 'стопа'} днес "
                       f"в тази посока — спирам до утре")
    if direction == "short" and shield:
        return False, (f"американските данни излизат в {_shield_sofia_label()} — "
                       f"продажба в този прозорец губи")
    if direction == "short" and 1 <= streak_n <= 3:
        return False, "втора продажба по същия пресен сигнал исторически губи"
    return True, ""


# ---------- СЪОБЩЕНИЯ v5 — компактни, спот-първи ----------
def _fmt(p, dec=2):
    return f"{p:,.{dec}f}"


def _sig_msg(direction, score, agree_n, tier_name, spot, bar_price, bar_ts, lv, entry,
             advice_txt, macro, streak_n, regime, stats, balance, risk_pct, weekly=None,
             reentry=False, open_trade=None, sym="XAUUSD", dec=2, extra_ctx=None, adv_ok=True,
             shadow_on=None, zone=None, other_trade=None, мерено=None, now_utc=None,
             превес=None):
    """ОДИТ-29 · един ред, едно нещо, едно емоджи отпред.
    Дотук картата беше добър български и лоша карта: изречения с подчинени
    и точка в средата. На телефон се чете РЕД, не абзац."""
    метал = "ЗЛАТО" if sym == "XAUUSD" else "СРЕБРО"
    _, _, защо = advice_txt.partition(" — ")
    защо = защо or advice_txt

    if open_trade:
        hit = open_trade.get("hit", {}); ol = open_trade["levels"]
        L = [f"📌 СДЕЛКАТА ТЕЧЕ · {метал} "
             f"{'покупка' if open_trade.get('direction', direction) == 'long' else 'продажба'} · "
             f"{_sofia()}",
             f"🎯 вход <code>{_fmt(open_trade['entry'], dec)}</code>",
             # ОДИТ-30: съди по САМИЯ стоп, не по флага. `track_trade` мести
             # `lv["sl"]` на входа при ТП1; ако по някаква причина не е преместен,
             # картата не бива да твърди «без риск».
             "🛑 стоп <code>%s</code>%s" % (
                 _fmt(ol["sl"], dec),
                 " (на входа — без риск)"
                 if abs(float(ol.get("sl", 0)) - float(open_trade["entry"])) < 0.01 else
                 " · " + _разст(open_trade["entry"], ol["sl"], sym, dec)),
             # 🔴 БЛИЗНАК · същата функция, съседен клон: главният клон получи
             # разстояния на 18.08, този остана с голи числа. Прибраните цели
             # НЕ носят разстояние (те вече са факт), непостигнатите — да.
             " · ".join(f"{n} <code>{_fmt(ol[k], dec)}</code>"
                        + (" ✅" if hit.get(k) else
                           f" ({abs(ol[k] - open_trade['entry']) / (PIP if sym == 'XAUUSD' else 0.001):,.0f}п)")
                        for n, k in (("1️⃣", "tp1"), ("2️⃣", "tp2"), ("3️⃣", "tp3")))]
        if spot:
            L.append(f"💵 сега <code>{_fmt(spot['mid'], dec)}</code>"
                     + (" ⚠️ от крипто-резерва, не от златния фийд"
                        if _от_резерва(spot) else ""))
        L.append("👁 дръж я · не отваряй нова")
        return "\n".join(L)

    if not adv_ok:
        L = [f"⏸ БЕЗ ВХОД · {метал} "
             f"{'нагоре' if direction == 'long' else 'надолу'} · {_sofia()}",
             f"📌 {защо}",
             # 🔴 БЛИЗНАК · трети клон на същата функция. «Ако решиш сам» е точно
             # мястото, където разстоянието трябва да се вижда — човекът решава
             # сам и няма как да го извади наум от два реда по-горе.
             f"🎯 ако решиш сам: <code>{_fmt(entry, dec)}</code> · "
             f"🛑 <code>{_fmt(lv['sl'], dec)}</code> · {_разст(entry, lv['sl'], sym, dec)}",
             " · ".join(f"{n} <code>{_fmt(lv[k], dec)}</code> "
                        f"({abs(lv[k] - entry) / (PIP if sym == 'XAUUSD' else 0.001):,.0f}п)"
                        for n, k in (("1️⃣", "tp1"), ("2️⃣", "tp2"), ("3️⃣", "tp3")))]
        # 🪜 25.08 · И ТУК. Това е картата «не влизам, но ако решиш сам» — точно
        # мястото, където по-късите стълби вършат работа: ботът не влиза, а
        # собственикът може да открадне ТП1 на 38 пипса.
        L.extend(_стълби_редове(entry, direction, dec))
        # 🔴 ДОТУК ТОЗИ КЛОН ВРЪЩАШЕ БЕЗ ДУМА ЗА РАЗМЕРА. Картата даваше пълен
        # план — вход, стоп, три цели — и НИТО ДУМА, че размерът е НУЛА. Точно
        # там, където е най-важно да се разбере, че не се влиза.
        L.append("📏 размер: НУЛА · не влизам")
        if shadow_on and abs(float(shadow_on.get("entry", entry)) - entry) >= 0.01:
            L.append(f"👁 следя наум от <code>{_fmt(float(shadow_on['entry']), dec)}</code>")
        else:
            L.append("👁 следя го наум")
        return "\n".join(L)

    ико = "🟢" if direction == "long" else "🔴"
    глагол = "КУПИ" if direction == "long" else "ПРОДАЙ"
    # 🔴 21.08 · ВТОРИЯТ ЕЛЕМЕНТ СПИРА ДА СЕ ХВЪРЛЯ — той е обяснението на
    # зоната, готово от 05.08 и никога стигало до карта.
    _zc, _zt = (zone if zone else (None, ""))
    _zw = ZONE_W.get(_zc, 1.0) if _zc else 1.0
    # 🔴 О2(в) · «ДА (малък размер)» беше САМО ДУМА. Проверено: застоял сигнал
    # даваше 0.05 лот / ≈$100 — точно колкото пресен. Присъдата обещаваше
    # намаление, което кодът не правеше. Сега думата има число зад себе си.
    _малък = "малък размер" in (advice_txt or "")
    # 🔴 21.08 · РЕЖИМЪТ ВЛИЗА В РАЗМЕРА. Дотук `regime` се подаваше на тази
    # функция и се ползваше само за текст. Мерено: под SMA200 лонгът дава
    # −1.248$, над нея +1.069$ [+0.206, +1.925]. Еднакъв размер за двете е
    # плащане за губещата половина.
    _рw, _рдума = _режим_тегло(direction, regime)
    # 🔴 25.08 · ПРЕВЕСЪТ ВЛИЗА В РАЗМЕРА. Ботът го смяташе на всеки рън
    # (ls и ss) и го хвърляше — `_resolve` връща само max(ls, ss).
    # Мерено: широк превес срещу тесен = +4.206$ [+2.68, +5.70] на сделка
    # при ЛОНГ и +2.784$ [+1.12, +4.40] при ШОРТ; и в двете епохи; и 0 от
    # 9 плацебо-разбърквания го бият. Тесният получава половин размер.
    _пw, _пдума = _превес_тегло(превес)
    риск = (balance * risk_pct / 100.0 * _zw
            * (МАЛЪК_РАЗМЕР_W if _малък else 1.0) * _рw * _пw)
    ед = SL_D if sym == "XAUUSD" else S_SL
    дел = 100.0 if sym == "XAUUSD" else 5000.0
    лот = риск / ед / дел
    # ОДИТ-29: рискът се смята ОТ ЗАКРЪГЛЕНИЯ лот, не от целта преди закръгляне.
    # Дотук при зона B картата казваше «0.03 лот · риск $67», а 0.03 лот рискува
    # $60 — двете числа на един и същи ред си противоречаха. Човекът оразмерява
    # по лота; значи числото до него трябва да е неговото.
    лот_окр = round(лот, 2)
    риск = лот_окр * дел * ед if лот_окр >= 0.01 else риск
    # 🔴 25.08 · СТЕПЕНТА СЕ ВРЪЩА НА КАРТАТА. Собственикът я иска дословно
    # («ПРОСТО ДА СТЕПЕНУВА СИГНАЛИТЕ КАКТТО СИ БЕШЕ»), ботът я СМЯТА — и я
    # ИЗХВЪРЛЯШЕ. Проверено с AST върху самата функция: 12 от 28 ѝ аргумента
    # не се четат НИКЪДЕ, сред тях `tier_name`, `score` и `agree_n`.
    # Тоест картата за ПРЕМИУМ сетъп и картата за СРЕДЕН се различаваха с
    # НУЛА знака — при 6× разлика в размера на позицията.
    # Влиза на СЪЩИЯ ред (правилото «7 реда / 400 знака» е за телефон и е
    # по-старо от това допълнение): «🟢 КУПИ ЗЛАТО · ПРЕМИУМ 7/8 · 6 отчета».
    # 🔴 И ТУК СИ ХВАНАХ ТИХ ДЕФЕКТ ВЕДНАГА: първата ми версия добавяше и
    # съгласието чрез `_съгласни(board, direction)` — но `board` НЕ Е аргумент
    # на тази функция, а `try/except Exception` глътна NameError-а МЪЛЧАЛИВО и
    # редът просто изчезна. Точно капанът, срещу който е целият този проект.
    # Съгласието и без това НЕ бива да се брои от `agree_n`: ОДИТ-45г вече
    # доказа, че «/7» е невярно — рамките са копия (87.0% буквално еднакви,
    # премерено днес наново). Броят на РАЗЛИЧНИТЕ отчети не е достъпен тук,
    # затова картата не го твърди. По-добре мълчание, отколкото невярно число.
    _ст = str(tier_name or "").strip()
    _сб = f" {int(score)}/8" if isinstance(score, (int, float)) else ""
    L = [f"{ико} {глагол} {метал}" + (f" · {_ст}{_сб}" if _ст else "")
         + f" · {_sofia()}",
         f"🎯 вход <code>{_fmt(entry, dec)}</code> · "
         f"🛑 стоп <code>{_fmt(lv['sl'], dec)}</code> · "
         f"{_разст(entry, lv['sl'], sym, dec)}"
         + ("" if spot else " <i>(по бара — живата цена мълчи)</i>"),
         # 🔴 «по 1/3» стои ПРИ ЦЕЛИТЕ — там му е мястото: то казва колко се
         # прибира на всяка, а не колко се влиза. Първата ми версия го изгуби
         # заедно със стария ред за стопа.
         " · ".join(f"{n} <code>{_fmt(lv[k], dec)}</code> "
                    f"({abs(lv[k] - entry) / (PIP if sym == 'XAUUSD' else 0.001):,.0f}п)"
                    for n, k in (("1️⃣", "tp1"), ("2️⃣", "tp2"), ("3️⃣", "tp3")))
         + " · по 1/3"]
    # 🪜 25.08 · и по-късите стълби, поискани два пъти. Само нива, нищо друго.
    L.extend(_стълби_редове(entry, direction, dec))
    if лот < 0.01:
        # О2(а) · «риск $27» не казва нищо, ако не знаеш от колко. Мин. лот при
        # среброто е 50 унции — при малък баланс това е далеч над целевия процент.
        _мин_р = ед * (1.0 if sym == "XAUUSD" else 50.0)
        _мин_п = (_мин_р / balance * 100.0) if balance else 0.0
        # 🔴 редът за стопа вече е на РЕД 2 на картата — тук беше вторият му дом
        if _мин_п > risk_pct + 0.05:
            L.append(f"⚠️ и с най-малката позиция (0.01 лот) рискуваш "
                     f"{_мин_п:.1f}% — над целта {risk_pct:g}%")
    else:
        # ОДИТ-35 · «риск $60» е обещание. Кодът нарочно пишеше «макс ≈»:
        # собственият тракер е записал −23.88$ при стоп −20.00 (гап).
        # Стопът пази НИВОТО, не цената.
        # 🔴 ОДИТ-41 · ЛОТЪТ ПАДА. Собственикът, 18-ия час: «не искам лотове,
        # всеки си преценя». Прав е — лотът зависи от неговата сметка, от
        # брокера и от това колко сделки държи едновременно; ботът не ги знае.
        # Остава числото, от което САМ се смята размер: колко струва стопът
        # на една унция. Плюс препоръката за размер с ДУМИ, когато е намален.
        pass
    # 🔴 18.08 · РАЗМЕРЪТ ПОЛУЧАВА СВОЙ РЕД, И ТОЙ Е ИЗВЪН ДВАТА КЛОНА.
    # Дотук шест различни размера се свиваха до «⚠️ малък размер» или до НИЩО —
    # ×1.000 и ×0.165 се различаваха с ЕДНА ДУМА при 6× разлика в парите.
    # 🔴 И ВТОРА МОЯ ГРЕШКА, хваната при рендиране: първо го сложих само в
    # клона `else`, а при малък баланс зоните B и C минават през ДРУГИЯ клон —
    # тоест точно слабите сетъпи оставаха без думата за размер. Класическият
    # близнак: поправка, минала през един от два съседни клона.
    _нам2 = []
    if _zw < 0.999:
        _нам2.append("зоната е по-слаба")
    if _малък:
        _нам2.append("сигналът не е пресен")
    # 🔴 «ВЛЕЗ» ПАДА: ред 1 вече казва КУПИ/ПРОДАЙ. Втора заповед на същата карта
    # обърква, а на картата «БЕЗ ВХОД» би излязло «ВЛЕЗ НУЛА» — безсмислица.
    # 🔴 25.08 · БЛИЗНАКЪТ. Рискът СЕ смяташе с превеса (_пw), а ДУМАТА за
    # размера — БЕЗ него. Тоест картата щеше да казва «ВСИЧКО · пълен размер»
    # върху половин позиция. Точно грехът, срещу който е писана :
    # «дялът Е множителят». Хванато от собствения ми тест П99 ПРЕДИ качване.
    _е, _дума, _дял = _сила(_zw * (МАЛЪК_РАЗМЕР_W if _малък else 1.0) * _рw * _пw)
    L.append(f"{_е} размер: {_дума} · {_дял}"
             + (f" · {' и '.join(_нам2)}" if _нам2 else ""))
    L.append(f"📌 {защо}")
    # 🔴 «по 1/3 на всяка цел» слиза при последния ред: то е за КАК се излиза,
    # не част от размера. Така картата пази тавана от 7 реда дори при пълна
    # конфигурация (друга сделка + ре-влизане), която тестът досега не рендерираше.
    # О3 · златото и среброто вървят заедно (корелация ~0.8). Две сделки в
    # една посока не са два независими залога, а един двоен. Дотук това се
    # казваше само във вечерната равносметка — часове след решението.
    if other_trade and other_trade.get("direction") == direction:
        _друг = "среброто" if sym == "XAUUSD" else "златото"
        L.append(f"⚠️ вече държиш {_друг} в същата посока · рискът е един голям, "
                 f"не два малки")
    if reentry:
        L.append("♻️ ре-влизане · предишната приключи")
    return "\n".join(L)

def _ladder_pnl(kind, hit, lv, entry, sign, dol, hit_px=None):
    """ОДИТ-6/Н1: сметката по стълбата 1/3 — ЕДИН източник за реалния И за сянка-изхода.
    Преди това само `_exit_msg` я имаше; `_shadow_exit_msg` показваше голото
    (изход − вход), тоест «+0.00$» на безрисков стоп след взети ТП1+ТП2, където
    стълбата дава +6.50$. Мерено в live/sent_log.jsonl: 4 карти, скрити +22.00$/oz.
    Връща (сметка_по_стълбата, брой_вече_прибрани_ТП)."""
    thirds = 0.0
    n_hit = 0
    for k2 in ("tp1", "tp2"):
        if hit.get(k2) and k2 != kind:
            # 🔧 О12: реалното попълване, ако го знаем; иначе нивото (както досега).
            # Сделка отпреди тази версия няма `hit_px` → смята се точно както преди.
            _ц = (hit_px or {}).get(k2)
            thirds += ((float(_ц) if _ц is not None else lv[k2]) - entry) * sign / 3.0
            n_hit += 1
    thirds += dol * (3 - n_hit) / 3.0
    if abs(thirds) < 0.005:                      # «0.00», не «-0.00»
        thirds = 0.0
    return round(thirds, 2), n_hit


def _прибрано(kind, hit, lv, entry, sign, dol, hit_px=None):
    """Колко е ПРИБРАНО НАИСТИНА (излезли трети), без марката по цена.

    🔴 26.08 · `_ladder_pnl` смята ПОСЛЕДНАТА трета по ТЕКУЩАТА цена, все
    едно е излязла — а тя още стои. При ТП2 това дава +10.50$, докато
    ПРИБРАНОТО е +6.50$. СЛУЧИ СЕ ЖИВО на 25.08:
        05:08 вход 4636.19 · 05:22 ТП1 · 05:32 ТП2 → картата обеща +10.50$
        07:11 остатъкът излезе на входа → реалното беше +6.50$
    Картата не бива да смесва прибрано с марка по цена. «Носи» звучи като
    прибрано, а не е.
    Връща (прибрано, виси_на_хартия, брой_излезли_трети).
    """
    _приб = 0.0
    _n = 0
    for k2 in ("tp1", "tp2", "tp3"):
        if not hit.get(k2):
            continue
        _ц = (hit_px or {}).get(k2)
        _приб += ((float(_ц) if _ц is not None else lv[k2]) - entry) * sign / 3.0
        _n += 1
    _висят = max(0, 3 - _n)
    _виси = dol * _висят / 3.0
    if abs(_приб) < 0.005:
        _приб = 0.0
    if abs(_виси) < 0.005:
        _виси = 0.0
    return round(_приб, 2), round(_виси, 2), _n


def _отворена_стълба(tr, spot, notes=None):
    """🔴 ОДИТ-61 · КОЛКО ПРАВИ ОТВОРЕНАТА СДЕЛКА, ПО СТЪЛБАТА.
    Трите карти (равносметка, «КЪДЕ СМЕ», пулс) показваха ГОЛАТА разлика за
    цялата позиция — на същия ред, на който изброяват прибраните трети.
    Изходната карта отдавна има вярната сметка (`_ladder_pnl`); тук просто
    никога не е била пусната.
    Връща (пари, брой_прибрани) или (None, 0) без жива цена."""
    if not tr or not spot:
        return None, 0
    try:
        зн = 1 if tr.get("direction") == "long" else -1
        ост = (float(spot["mid"]) - float(tr["entry"])) * зн
        return _ladder_pnl("отворена", tr.get("hit", {}) or {}, tr["levels"],
                           float(tr["entry"]), зн, ост, tr.get("hit_px"))
    except Exception as _e:
        # 🔴 ОДИТ-68 · ДОТУК ТУК СТОЕШЕ ГОЛО `return None, 0`. Счупи ли се
        # сметката по стълбата, трите карти (равносметка, «КЪДЕ СМЕ», пулс)
        # просто НЕ показваха пари и никой не разбираше. Мълчание на паричен
        # път — точно класът, който днес ме ухапа три пъти.
        if notes is not None:
            notes.append(f"🔴 сметката по стълбата гръмна ({type(_e).__name__}: "
                         f"{str(_e)[:60]}) — картата е без число")
        return None, 0


def _exit_msg(kind, tr, price_hit, when, via, gap, spot=None, next_line="", dec=2):
    """ОДИТ-29 · КОЯ цел · КОЛКО пари · КАКВО правиш. По един ред всяко."""
    _сим = tr.get("sym", "XAUUSD")
    метал = "ЗЛАТО" if _сим == "XAUUSD" else "СРЕБРО"
    посока = "покупка" if tr["direction"] == "long" else "продажба"
    e = tr["entry"]; lv = tr["levels"]; hit = tr.get("hit", {})
    знак = 1 if tr["direction"] == "long" else -1
    дол = (price_hit - e) * знак
    if abs(дол) < 0.005:
        дол = 0.0
    стълба, взети = _ladder_pnl(kind, hit, lv, e, знак, дол, tr.get("hit_px"))
    час = _sofia(when) if via in ("бар", "спот") else _sofia()
    гап = " · с гап" if gap else ""
    глави = {"tp1": ("✅", "ЦЕЛ 1"), "tp2": ("✅", "ЦЕЛ 2"), "tp3": ("🏆", "ВСИЧКО ПРИБРАНО"),
             "sl": ("🛑", "СТОП"), "flip": ("⏸", "ЗАТВОРЕНА · посоката се обърна"),
             "time": ("⏸", "ЗАТВОРЕНА · по време")}
    ико, дума = глави.get(kind, ("📌", kind))
    if kind == "sl" and взети > 0:
        # 🔴 26.08 · «НУЛА» СТОЕШЕ ВЪРХУ ПЕЧАЛБА. Сделка, взела ТП1 и върнала
        # се на входа, е ПРИБРАЛА една трета: +25 пипса (+2.50$/oz). Картата
        # обявяваше «✅ НУЛА» и веднага под нея «0 пипса (0.00$)» — ДВА реда
        # нула върху плюс, а истината идваше чак на третия ред. Собственикът
        # на 26.08: «печалбата е голяма, всеки път я занижаваш».
        # МЕРЕНО защо това не е рядък ъгъл: be-stop-after-tp1 е 24.6% от
        # всичките 6846 сделки (+2.461$/oz средно) и be-stop-after-tp2 още
        # 14.6% (+6.495$) — тоест ВСЯКА ЧЕТВЪРТА до ВСЯКА ТРЕТА карта е
        # минавала през този надпис.
        if стълба > 0.005:
            ико, дума = "✅", "ПЕЧАЛБА"
        elif стълба < -0.005:
            ико, дума = "🛑", "СТОП"
        else:
            ико, дума = "✅", "НУЛА"
        дума += " · стопът беше на входа"
    # 🔴 26.08 · вторият ред печаташе ДВИЖЕНИЕТО НА ЦЕНАТА. При изход на
    # входа то е точно 0 — вярно число, което казва грешното нещо, защото
    # прибраната трета вече е в джоба. Само в този случай редът казва КАКВО
    # СЕ Е СЛУЧИЛО С ОСТАТЪКА; навсякъде другаде остава както беше.
    _нулев_ход = (kind == "sl" and взети > 0 and abs(дол) < 0.005)
    L = [f"{ико} {дума} · {метал} {посока} · {час}",
         (f"💵 <code>{_fmt(e, dec)}</code> → <code>{_fmt(price_hit, dec)}</code> · "
          + (f"остатъкът излезе на входа · <b>{_пари(стълба, _сим)}</b> прибрани"
             if _нулев_ход else f"<b>{_пари(дол, _сим)}</b>") + гап)]
    if kind == "tp1":
        L.append(f"🛑 премести стопа на <code>{_fmt(e, dec)}</code> · оттук нататък без риск")
        # 🔴 голи числа точно там, където се решава «държа ли още»
        _ст = PIP if _сим == "XAUUSD" else 0.001
        L.append(f"🎯 остават 2️⃣ <code>{_fmt(lv['tp2'], dec)}</code> "
                 f"({abs(lv['tp2'] - price_hit) / _ст:,.0f}п оттук) · "
                 f"3️⃣ <code>{_fmt(lv['tp3'], dec)}</code> "
                 f"({abs(lv['tp3'] - price_hit) / _ст:,.0f}п)")
        # 🔴 26.08 · и ТП1 казва КОЛКО Е ПРИБРАЛ. Дотук показваше само ДВИЖЕНИЕТО
        # (+7.50$), а прибраната трета е +2.50$ — три пъти по-малко. Движението
        # е вярно число, но не е това, което влиза в сметката.
        _пр1, _вс1, _ = _прибрано(kind, hit, lv, e, знак, дол, tr.get("hit_px"))
        if _пр1:
            L.append(f"💰 ПРИБРАНО <b>{_пари(_пр1, _сим)}</b> (⅓ от позицията)")
    elif kind == "tp2":
        # ОДИТ-35: `_ladder_pnl` смята общата сметка безусловно, а картата не я
        # печаташе при ТП1/ТП2 — сянката я казваше, реалният изход не.
        # 🔴 26.08 · «дотук сделката носи» СМЕСВАШЕ прибрано с марка по цена.
        # Сега двете се казват поотделно: прибраното е ТВОЕ, останалото виси.
        _пр2, _вс2, _бр2 = _прибрано(kind, hit, lv, e, знак, дол, tr.get("hit_px"))
        L.append(f"💰 ПРИБРАНО <b>{_пари(_пр2, _сим)}</b>"
                 + (f" · последната ⅓ виси на {_пари(_вс2, _сим)}, без риск"
                    if _вс2 else " · останалото е без риск"))
        L.append(f"🎯 остава 3️⃣ <code>{_fmt(lv['tp3'], dec)}</code> "
                 f"({abs(lv['tp3'] - price_hit) / (PIP if _сим == 'XAUUSD' else 0.001):,.0f}п "
                 f"оттук) · 2/3 са прибрани")
    else:
        L.append(f"💰 сделката донесе <b>{_пари(стълба, _сим)}</b> общо")
        L.append("👁 затворена · чакам нов сигнал")
    if next_line:
        L.append(f"♻️ ново влизане: {next_line}")
    return "\n".join(L)

def _shadow_exit_msg(kind, tr, price_hit, when, via, gap, spot=None, dec=2):
    """ОДИТ-29 · «онова, което ти казах да не пипаш, стигна дотук». Три реда.

    🔴 18.08 · `gap` влизаше и се изхвърляше. Реалната изходна карта пише «· с
    гап», сянката — не. Две карти за едно и също събитие, с различна честност:
    сянката премълчаваше, че цената е прескочила нивото вместо да го докосне."""
    _сим = tr.get("sym", "XAUUSD")
    метал = "ЗЛАТО" if _сим == "XAUUSD" else "СРЕБРО"
    посока = "покупка" if tr["direction"] == "long" else "продажба"
    e = tr["entry"]; lv = tr["levels"]; hit = tr.get("hit", {})
    знак = 1 if tr["direction"] == "long" else -1
    дол = (price_hit - e) * знак
    if abs(дол) < 0.005:
        дол = 0.0
    стълба, взети = _ladder_pnl(kind, hit, lv, e, знак, дол, tr.get("hit_px"))
    час = _sofia(when) if via in ("бар", "спот") else _sofia()
    какво = {"tp1": "щеше да хване ЦЕЛ 1", "tp2": "щеше да хване ЦЕЛ 2",
             "tp3": "щеше да мине докрай", "sl": "щеше да удари стоп",
             "flip": "посоката се обърна", "time": "щеше да излезе по време"}.get(kind, kind)
    if kind == "sl" and взети > 0:
        какво = "щеше да излезе на нула"
    return "\n".join([
        f"👁 НАУМ · {какво} · {метал} {посока} · {час}",
        f"💵 <code>{_fmt(e, dec)}</code> → <code>{_fmt(price_hit, dec)}</code> · "
        f"<b>{_пари(стълба, _сим)}</b>" + (" · с гап" if gap else ""),
        "📌 не съм влизал · само да знаеш"])

def _мозък_следене(файл, дневник, цена, now_utc, нов=None, бар=None, бележки=None):
    """ОДИТ-33 · хипотетично следене на мозъчен сетъп. Без пари, без лот.

    файл    : brain_track.json — единственото отворено следене
    дневник : brain_result.jsonl — всеки затворен изход, ред по ред
    цена    : ЖИВАТА цена (същата скала като нивата на картата)
    нов     : сетъп за отваряне, ако няма отворен
    бар     : (high, low) на последния бар, В ЖИВАТА СКАЛА (минус базиса)

    🔴 19.08 · ЗАЩО `бар` СЕ ДОБАВЯ. Дотук следенето съдеше по ЕДНА цена, а
    `track_trade` съди по HIGH/LOW. Стоп, докоснат МЕЖДУ две събуждания, беше
    невидим тук — но реалната сделка би го ударила.
    Мерено (Монте-Карло, истинско 5м злато, 2906 наблюдения, същата геометрия):
        проба 5 мин  : следене +1.862$ · честно +1.159$ → +60.6% завишаване
        проба 15 мин : следене +2.297$ · честно +1.159$ → +98.2%
    «барът казва СТОП, следенето казва ЦЕЛ2»: 149 срещу обратните 86.
    Този файл Е форуърд-тестът на логиката. Кантар, който показва 60% повече,
    е по-лош от липсващ — кара те да рискуваш повече, отколкото числото позволява.
    Няма ли бар → пада обратно на скаларната цена (старото поведение).

    Връща list[(tag, text)] — картите за пращане.
    Нищо тук не докосва trade.json, guard.json или статистиката.
    """
    msgs = []
    т = _load_state(файл, None)

    # 🔴 21.08 · НАБЛЮДЕНИЕТО НЯМАШЕ ИЗХОД ПО ВРЕМЕ. Затваряше се само при стоп
    # или цел2, а докато файлът стои, НИТО ЕДНО ново наблюдение не се приема.
    # Реалната сделка има изход по време (ДНИ_МАКС=30); наблюдението — не.
    # ИЗПЪЛНЕНО: 500 ръна с часовник 17 МЕСЕЦА след отварянето — файлът още
    # държи, новото наблюдение НЕ е прието, карти няма.
    # ЗА ЧЕСТНОСТ: в живия brain_result.jsonl всичките 17 записа се затварят
    # бързо (макс 17.2ч, медиана под 2ч) — механизмът е доказан, заклещване в
    # продукция НЕ е наблюдавано. Затова хоризонтът е широк: спира заклещването,
    # без да реже живи наблюдения.
    if т is not None and цена is not None and now_utc:
        try:
            _въз_ч = (pd.Timestamp(now_utc) - pd.Timestamp(т.get("отворен"))).total_seconds() / 3600.0
        except Exception:
            _въз_ч = None
        _хор = МОЗЪК_ЧАСОВЕ_БЪРЗИ if str(т.get("рамка", "")) in ("1мин", "5м") else МОЗЪК_ЧАСОВЕ_БАВНИ
        if _въз_ч is not None and _въз_ч >= _хор:
            _зн_в = 1 if т["посока"] == "long" else -1
            т["изход"] = "време"
            т["цена_изход"] = round(float(цена), 2)
            т["затворен"] = now_utc
            т["пари"] = round((float(цена) - float(т["вход"])) * _зн_в, 2)
            try:
                with io.open(str(дневник), "a", encoding="utf-8") as _ф:
                    _ф.write(json.dumps(т, ensure_ascii=False, default=str) + chr(10))
            except Exception:
                pass
            try:
                файл.unlink()
            except Exception:
                pass
            msgs.append(("brain-exit:време", _мозък_изход_msg(т, "време", float(цена), _зн_в)))
            т = None

    if т is not None and цена is not None:
        лонг = т["посока"] == "long"
        зн = 1 if лонг else -1
        удар = None
        # 🔴 19.08 · НАЙ-ЛОШАТА И НАЙ-ДОБРАТА ТОЧКА НА БАРА, не само последната
        # цена. Точно както `track_trade`: стопът се съди по екстремума СРЕЩУ
        # позицията, целите — по екстремума В нейна полза.
        _hi = _lo = float(цена)
        if бар:
            try:
                _bh, _bl = float(бар[0]), float(бар[1])
                # 🔴 21.08 · САНИТИ НА СКАЛАТА. Барът и цената трябва да са в
                # ЕДИН свят. Подаден на чужда скала (суров фючърс срещу спот-нива),
                # той фабрикува стоп/цел без никакво движение: измерено, разликата
                # Е базисът, тоест ~55$ при злато 4640$. Пазачът не гадае — мери:
                # не обгражда ли барът цената в рамките на БАР_САНИТИ_ПЦТ, той се
                # изхвърля и се пада на скаларната цена (СТАРОТО поведение).
                _далеч = min(abs(_bh - float(цена)), abs(_bl - float(цена)))
                if _далеч > БАР_САНИТИ_ПЦТ * abs(float(цена)):
                    raise ValueError(f"барът е на чужда скала ({_далеч:.1f}$ от цената)")
                _hi = max(_bh, float(цена))
                _lo = min(_bl, float(цена))
            except (TypeError, ValueError, IndexError) as _еб:
                _hi = _lo = float(цена)
                if "чужда скала" in str(_еб) and бележки is not None:
                    # ДИАГНОСТИКА, не карта: това е за дневника, не за собственика.
                    # Дотук щеше да излезе като съобщение в Телеграм.
                    бележки.append(f"🧠 {_еб} — падам на скаларната цена")
        _срещу = _lo if лонг else _hi          # най-лошото, което е видяла
        _за = _hi if лонг else _lo             # най-доброто, което е видяла
        # стопът се проверява ПРЪВ: ако и двете са докоснати в един рън,
        # честното допускане е по-лошото. Инак следенето би се хвалило.
        if (_срещу - т["стоп"]) * зн <= 0:
            # 🔴 19.08 · БЛИЗНАКЪТ НА №42, второ място. Дотук тук се записваше
            # НИВОТО на стопа като цена на изход, макар наблюдаваната цена вече
            # да е минала отвъд. Целите са лимитни и нивото им Е верният фил —
            # стопът е ПАЗАРЕН и се пълни там, където е пазарът.
            # Това храни `brain_result.jsonl`, тоест числата, по които се съди
            # съветникът. Занижени загуби → съветникът изглежда по-добър.
            удар = ("стоп", min(_срещу, т["стоп"]) if лонг else max(_срещу, т["стоп"]))
        elif т.get("цел2") is not None and (_за - т["цел2"]) * зн >= 0:
            удар = ("цел2", т["цел2"])          # лимитна → филът Е нивото
        elif not т.get("цел1_взета") and (_за - т["цел1"]) * зн >= 0:
            удар = ("цел1", т["цел1"])          # лимитна → филът Е нивото

        if удар and удар[0] == "цел1":
            т["цел1_взета"] = True
            _запиши_атомарно(файл, json.dumps(т, ensure_ascii=False, default=str))
            msgs.append(("brain-exit:цел1", _мозък_изход_msg(т, "цел1", удар[1], зн)))
        elif удар:
            msgs.append(("brain-exit:" + удар[0], _мозък_изход_msg(т, удар[0], удар[1], зн)))
            т["изход"] = удар[0]
            т["цена_изход"] = round(float(удар[1]), 2)
            т["затворен"] = now_utc
            # 🔴 ОДИТ-57 · ДОТУК ТУК СТОЕШЕ ГОЛОТО (изход − вход), което ИГНОРИРА,
            # че ЦЕЛ1 вече е била взета. Реалната сделка има стълба
            # (`_ladder_pnl`); следенето нямаше нищо и записваше ПЪЛНА загуба.
            # Мерено в живия brain_result.jsonl: 1 от 6 записа е така — 08-12
            # 03:51, взета цел1, изход стоп, записан −5.36$, докато първата
            # половина вече е била прибрана на печалба.
            # Това не е козметика: този файл Е форуърд-тестът на логиката.
            # Две цели → две части: половина на ЦЕЛ1, половина на крайния изход.
            _ч2 = (удар[1] - т["вход"]) * зн
            if т.get("цел1_взета") and удар[0] != "цел1":
                _ч1 = (т["цел1"] - т["вход"]) * зн
                т["част1"] = round(_ч1, 2)
                т["част2"] = round(_ч2, 2)
                т["резултат"] = round(_ч1 / 2.0 + _ч2 / 2.0, 2)
            else:
                т["резултат"] = round(_ч2, 2)
            try:
                with io.open(дневник, "a", encoding="utf-8") as f:
                    f.write(json.dumps(т, ensure_ascii=False, default=str) + "\n")
            except Exception:
                pass
            try:
                файл.unlink()
            except Exception:
                pass
            т = None

    # ── ново следене само ако няма отворено ──────────────────────────────
    if т is None and нов is not None:
        з = нов.get("залог") or {}
        if з.get("вход") is not None and з.get("стоп") is not None and з.get("цел") is not None:
            т = {"посока": "long" if нов.get("лонг") else "short",
                 "рамка": нов.get("рамка"), "степен": нов.get("степен"),
                 "точки": нов.get("точки"), "отворен": now_utc,
                 "вход": round(float(з["вход"]), 2), "стоп": round(float(з["стоп"]), 2),
                 "цел1": round(float(з["цел"]), 2),
                 "цел2": (round(float(з["цел2"]), 2) if з.get("цел2") is not None else None),
                 "цел1_взета": False}
            _запиши_атомарно(файл, json.dumps(т, ensure_ascii=False, default=str))
    return msgs


def _мозък_изход_msg(т, вид, цена, зн):
    """ОДИТ-33 · развръзката на едно наблюдение. Четири реда, като всичко друго."""
    посока = "нагоре" if т["посока"] == "long" else "надолу"
    пари = (цена - т["вход"]) * зн
    глави = {"цел1": ("✅", "ПЪРВАТА ЦЕЛ падна"),
             "цел2": ("🏆", "ВТОРАТА ЦЕЛ падна"),
             "стоп": ("🛑", "СТОПЪТ удари"),
             "време": ("⏰", "ВРЕМЕТО изтече")}
    ико, дума = глави.get(вид, ("📌", вид))
    L = [f"{ико} {дума} · наблюдението от "
         f"{_sofia_ако_друг_ден(т['отворен'])} · злато {посока}",
         f"💵 {_fmt(т['вход'], 2)} → {_fmt(цена, 2)} · <b>{пари:+.2f}$</b>/унция"]
    if вид == "цел1" and т.get("цел2") is not None:
        L.append(f"🎯 остава {_fmt(т['цел2'], 2)}")
    else:
        L.append("👁 наблюдението приключи")
    L.append("🧪 без пари — само за да знаеш дали работи")
    return "\n".join(L)


def _shadow_cycle(shadow_file, bars, basis, price_user, now_utc, spot,
                  open_dir, open_entry, open_lv, real_open, date, tier, sym, dec,
                  скок_базис=False):
    """СЯНКА-следене: хипотетична сделка от «не влизай» карта. Следи стария сетъп през
    дните (същият track_trade), праща «какво щеше да е» при всеки удар, отваря нова при
    информативна карта. НАПЪЛНО ИЗОЛИРАНА — не пипа guard/реалната сделка/статистиката.
    Връща list[(tag, text)] с what-if изходите."""
    msgs = []
    sh = _load_state(shadow_file, None)
    if sh is not None:
        sh_obj = copy.deepcopy(sh)                          # снимка за съобщенията
        sh, events = track_trade(sh, bars, basis, price_user, now_utc, spot=spot,
                                 скок_базис=скок_базис)
        cum = dict(sh_obj["hit"])
        for kind, px, when, via, gap in events:
            if kind in ("tp1", "tp2", "tp3"):
                cum[kind] = True
            o = dict(sh_obj); o["hit"] = dict(cum)
            msgs.append(("sh-exit:" + kind, _shadow_exit_msg(kind, o, px, when, via, gap, spot=spot, dec=dec)))
    if real_open:                                           # реалната сделка измества сянката
        sh = None
    elif open_entry is not None and open_dir in ("long", "short"):
        if sh is None or sh.get("direction") != open_dir:   # нов/обърнат сетъп → (пре)отвори
            sh = {"direction": open_dir, "entry": round(open_entry, dec), "opened": now_utc,
                  "checked": now_utc, "levels": dict(open_lv), "hit": {}, "status": "open",
                  "v2": True, "ledger": "spot", "tier": tier, "date": date, "sym": sym, "shadow": True}
    if sh is not None and sh.get("status", "open") == "open":
        _запиши_атомарно(shadow_file, json.dumps(sh, ensure_ascii=False))
    elif shadow_file.exists():
        shadow_file.unlink()                                # затворена/изместена → чист диск
    return msgs


def _ma_alert_msg(direction, ma_name, price, mb, macro):
    """ОДИТ-28/29 · знак за ниво, НЕ сделка. Нивата паднаха — картата даваше
    вход, по който сама казваше да не влизаш.

    🔴 F25 (18.08) · ДОТУК ТУК `mb` и `macro` СЕ ПОЛУЧАВАХА И СЕ ИЗХВЪРЛЯХА
    (потвърдено с AST), а редът «сметката е на минус» беше закован текст. В
    същото време `backtest_stats.json` твърдеше за същото събитие +4.64$ на
    сделка — тоест картата и файлът си противоречаха, и никой не питаше кой е
    прав. Преизмерено под доставената геометрия върху 1-минутната лента с
    реалния спред: long/ma50 −0.348$ [−1.591 .. +0.863] — ШУМ, и така и на
    четирите. «Не влизам» остава, но вече ЗАЩОТО Е МЕРЕНО, и числото се вижда.
    """
    ико = "🟢" if direction == "long" else "🔴"
    накъде = "нагоре" if direction == "long" else "надолу"
    мб = mb if isinstance(mb, dict) else {}
    нето, брой = мб.get("net"), мб.get("n")
    if нето is None or not брой:
        оценка = "👁 само знак · няма измерване за такъв отскок — не влизам"
    else:
        зн = "+" if нето > 0 else "−"
        пипс = abs(float(нето)) / PIP
        шум = bool(мб.get("шум")) or (мб.get("lo") is not None and мб.get("hi") is not None
                                      and мб["lo"] <= 0 <= мб["hi"])
        # ФАКТ, не лекция: числото и думата до него не бива да си противоречат.
        # 🔴 ЧИСЛОТО И ДУМАТА ДО НЕГО НЕ БИВА ДА СИ ПРОТИВОРЕЧАТ. Първата ми
        # версия лепваше «не влизам» и когато числото е уверено ПОЛОЖИТЕЛНО —
        # тоест картата щеше да казва «+46 пипса … не влизам». Днес случаят е
        # хипотетичен (и четирите са шум), но текстът не бива да зависи от това
        # кое число ще излезе утре. Отрицателно/шум → «не влизам», защото е
        # мерено. Положително → истинската причина е ДРУГА: този знак изобщо не
        # е вързан в машината за сделки — няма нива, няма следене.
        _слаб = шум or float(нето) <= 0
        оценка = (f"👁 само знак · мерено {зн}{пипс:.0f} пипса "
                  f"({зн}{abs(float(нето)):.2f}$) от {брой} случая"
                  + (" · нулата е в интервала" if шум else "")
                  + (" — не влизам" if _слаб else " — знак, не се следи"))
    return "\n".join([
        f"📌 НИВО · цената се обърна {накъде} от {ma_name.upper()} · {_sofia()}",
        f"{ико} злато <code>{_fmt(price)}</code>",
        оценка])

def _weekly(path, date=None, notes=None):
    try:
        p = Path(path)
        w = json.loads(p.read_text(encoding="utf-8")) if p.exists() else None
        if w and date and w.get("week_of"):                    # Ф8.7: остарял контекст
            try:
                age = (pd.Timestamp(date) - pd.Timestamp(w["week_of"])).days
                if age > 8:
                    if notes is not None:
                        notes.append(f"седмичният контекст е на {age} дни — скрит")
                    return None
            except Exception:
                pass
        return w
    except Exception:
        return None


def _daily_ctx(path, date, notes):
    """Ф4: дневният контекст (Кибер Алфа / анализ на деня). Валиден за ДНЕС —
    Б8: сравнява с КАЛЕНДАРНАТА дата ИЛИ датата на бара (рано сутрин барът още е вчерашен)."""
    try:
        p = Path(path)
        if not p.exists():
            return None
        d = json.loads(p.read_text(encoding="utf-8"))
        cal = str(datetime.now(timezone.utc).date())
        if str(d.get("date")) not in (str(date), cal):
            notes.append("дневният контекст е за друга дата — пропуснат")
            return None
        return d
    except Exception:
        notes.append("дневният контекст не се чете — пропуснат")
        return None


def _event_shield(ctx, now_utc):
    """Ф4.3: (активен_щит, етикет). Щит ±20 мин около събитие impact=high;
    етикет и за предстоящо събитие до 60 мин (само предупреждение)."""
    if not ctx:
        return False, None
    try:
        now_s = datetime.fromisoformat(str(now_utc)).replace(tzinfo=timezone.utc).astimezone(_tz("Europe/Sofia"))
        for ev in ctx.get("events", []):
            t = str(ev.get("time_sofia", ""))
            if ":" not in t:
                continue
            hh, mm = t.split(":")[:2]
            evt = now_s.replace(hour=int(hh), minute=int(mm), second=0, microsecond=0)
            dmin = (now_s - evt).total_seconds() / 60
            hi = str(ev.get("impact", "")).lower() == "high"
            if hi and -20 <= dmin <= 20:
                return True, f"{t} {ev.get('name', 'събитие')}"
            if hi and -60 <= dmin < -20:
                return False, f"предстои {t} {ev.get('name', 'събитие')}"
        return False, None
    except Exception:
        return False, None


def _digest_msg(out, date, trade, s_trade, spot_g, spot_s, guard, weekly_part=False):
    """ОДИТ-29 · какво стана с парите днес. Пет реда."""
    def _редове(файл, условие):
        f = out / файл
        if not f.exists():
            return []
        r = []
        for ln in f.read_text(encoding="utf-8").splitlines():
            try:
                j = json.loads(ln)
                if условие(j):
                    r.append(j)
            except Exception:
                pass
        return r
    рънове = _редове("live_journal.jsonl", lambda r: r.get("date") == date)
    пратени = _редове("sent_log.jsonl", lambda r: str(r.get("utc", ""))[:10] == date)
    L = [f"🌙 Как мина денят · {_sofia()}"]
    for нм, tr, sp, dec in (("🥇", trade, spot_g, 2), ("🥈", s_trade, spot_s, 3)):
        if tr:
            прибр = [n for n, k in (("1️⃣", "tp1"), ("2️⃣", "tp2"), ("3️⃣", "tp3"))
                     if tr.get("hit", {}).get(k)]
            # 🔴 ОДИТ-61: ПО СТЪЛБАТА, не гола разлика. Редът над този изброява
            # прибраните трети — беше противоречие на едно и също място.
            пл, _ = _отворена_стълба(tr, sp, notes if 'notes' in dir() else None)
            L.append(f"{нм} държим от <code>{tr['entry']:,.{dec}f}</code>"
                     + (f" · {' '.join(прибр)} ✅" if прибр else "")
                     # 🔴 26.08 · САМО ДОЛАРИ, без пипсове. Собственикът:
                     # «парите не са нужни, пипсовете да са точни на макс —
                     # хората си играят с каквито лотове могат». Третата карта
                     # (ред 2960) отдавна ползва `_пари`, тези две — не.
                     + (f" · <b>{_пари(пл, tr.get('sym', 'XAUUSD'))}</b>"
                        if пл is not None else ""))
        else:
            L.append(f"{нм} няма сделка")
    if trade and s_trade and trade["direction"] == s_trade["direction"]:
        L.append("⚠️ и двете в една посока · рискът е един голям, не два малки")
    стопове = sum(guard.get(k, 0) for k in ("long", "short", "s_long", "s_short"))
    if стопове:
        L.append(f"🛑 стопът ме изхвърли {стопове}×")
    # 🔴 ОДИТ-62 · «ЦЯЛ ДЕН» БЕШЕ НЕВЯРНА ДУМА. Равносметката тръгва в 21:00
    # София и брои ръновете от СЪЩИЯ календарен ден по UTC — но денят на бота
    # започва в 22:00 UTC предната вечер. Мерено: 27.9% от ръновете не влизат
    # в НИКОЯ равносметка. Сега казваме какво наистина покриваме.
    try:
        _ч = sorted(str(r.get("run_utc", ""))[11:16] for r in рънове if r.get("run_utc"))
        _обхват = f"{_ч[0]}–{_ч[-1]} UTC" if _ч else "днес"
    except Exception:
        _обхват = "днес"
    L.append(f"✅ буден · {len(рънове)} проверки ({_обхват}) · {len(пратени)} съобщения")
    L.append("👁 " + ("в понеделник пак съм тук" if weekly_part else "утре пак съм тук"))
    return "\n".join(L)

def _status_msg(board, new_dir, trade, s_trade, spot_g, spot_s, basis_g, basis_s,
                guard, shield, date, macro):
    """ОДИТ-29 · снимка на момента, четири реда."""
    L = [f"📌 КЪДЕ СМЕ · {_sofia()}"]
    # ОДИТ-35 · посоката падна и при празна сметка картата се свиваше до
    # «няма сделка · няма сделка · две цени». Той я пита НА РЪКА точно за да
    # разбере какво вижда ботът — а получаваше по-малко от автоматичния пулс.
    if new_dir:
        _за, _общо = _съгласни(board or [], new_dir)   # ОДИТ-45г: виж близнак 1
        L.append(f"{'🟢' if new_dir == 'long' else '🔴'} очертава се "
                 f"{'нагоре' if new_dir == 'long' else 'надолу'}"
                 + (f" · {_за} от {_общо} отчета" if _общо > 1 else ""))
    else:
        L.append("📌 посоката е разбъркана")
    if shield:
        L.append("⚠️ американски данни сега — продажбите чакат края им")
    for нм, tr, sp, dec in (("🥇", trade, spot_g, 2), ("🥈", s_trade, spot_s, 3)):
        if tr:
            прибр = [n for n, k in (("1️⃣", "tp1"), ("2️⃣", "tp2"), ("3️⃣", "tp3"))
                     if tr.get("hit", {}).get(k)]
            # 🔴 ОДИТ-61: ПО СТЪЛБАТА, не гола разлика. Редът над този изброява
            # прибраните трети — беше противоречие на едно и също място.
            пл, _ = _отворена_стълба(tr, sp, notes if 'notes' in dir() else None)
            L.append(f"{нм} {'покупка' if tr['direction'] == 'long' else 'продажба'} от "
                     f"<code>{tr['entry']:,.{dec}f}</code>"
                     + (f" · {' '.join(прибр)} ✅" if прибр else "")
                     + f" · 🛑 <code>{tr['levels']['sl']:,.{dec}f}</code>"
                     + (f" · <b>{_пари(пл, tr.get('sym', 'XAUUSD'))}</b>"
                        if пл is not None else ""))
        else:
            L.append(f"{нм} няма сделка")
    if spot_g:
        L.append(f"💵 злато <code>{spot_g['mid']:,.2f}</code>"
                 + (f" · сребро <code>{spot_s['mid']:,.3f}</code>" if spot_s else ""))
    # 🔴 18.08 · `guard` ВЛИЗАШЕ И СЕ ИЗХВЪРЛЯШЕ. Изпълнено: guard={long:2,short:2}
    # и {0,0} даваха БАЙТ-ИДЕНТИЧНА карта. Тоест картата, която собственикът иска
    # НА РЪКА, за да разбере какво става, не можеше да му каже най-важното — че
    # днес входовете са спрени от стоп-пазача. Спирачката съществува, картата
    # мълчеше за нея.
    _бл = [("покупки" if д == "long" else "продажби", int(н))
           for д, н in sorted((guard or {}).items())
           if isinstance(н, (int, float)) and н >= ПАЗАЧ_СТОПОВЕ]
    if _бл:
        L.append("🛑 спрени днес: " + " · ".join(f"{к} ({н} стопа)" for к, н in _бл))
    L.append("👁 само снимка · нищо не се прави")
    return "\n".join(L)

def _търговски_минути(от_utc, до_utc, крачка=15):
    """🔴 ОДИТ-48 · КОЛКО ОТ ДУПКАТА Е БИЛА В ОТВОРЕН ПАЗАР.
    Проверката ми в v9.7 гледаше само ДВАТА КРАЯ (`not weekend and not
    _market_closed(_посл)`). Реалната уикенд дупка е петък 20:55 → неделя 22:01:
    и двата края са в отворен пазар, а между тях лежи целият уикенд → картата
    палеше и всеки понеделник щеше да идва «БОТЪТ СПА 49ч».
    Тук се стъпва през дупката и се брои САМО отвореното време."""
    try:
        a = pd.Timestamp(от_utc); b = pd.Timestamp(до_utc)
    except Exception:
        return 0.0
    if b <= a:
        return 0.0
    общо = (b - a).total_seconds() / 60.0
    if общо > 60 * 24 * 14:          # абсурдна дупка (студен старт) → не гадаем
        return 0.0
    мин = 0.0
    t = a
    while t < b:
        стъпка = min(крачка, (b - t).total_seconds() / 60.0)
        if not _market_closed(t.isoformat()):
            мин += стъпка
        t += pd.Timedelta(minutes=крачка)
    return мин


def _сухо_msg(бр, причина, откога_utc, now_utc):
    """🔴 21.08 · «ПУСКАН СЪМ И НИЩО НЕ ИЗЛИЗА» — картата, която липсваше.

    Мерено: на 19-21.08 ботът мълча 320 ръна подред, а единственият будилник
    (дупка ≥45 мин) не пламна нито веднъж, защото кронът си вървеше изрядно.
    «Работи» и «върши работа» са два различни въпроса; дотук се задаваше само
    първият."""
    ч = бр * 5 / 60.0
    L = [f"🔴 <b>БУДЕН СЪМ, НО НЕ МОГА ДА РАБОТЯ</b> · {_sofia()}",
         f"📌 {бр} проверки подред без жива цена (около {ч:.1f}ч)",
         f"⏰ последно ставаше в {_sofia_ако_друг_ден(откога_utc, now_utc)}"
         if откога_utc else "⏰ откакто помня, не е ставало",
         f"⚠️ причина: {str(причина)[:110]}",
         "👁 нови входове НЕ се отварят · отворена сделка се следи както обикновено",
         "📌 това не е тих пазар — това е счупена тръба към цената"]
    return "\n".join(L)


def _спал_msg(мин, откога_utc, докога_utc):
    """ОДИТ-47 · ботът е спал по-дълго от прага. Казва го, вместо да се направи,
    че нищо не е било."""
    ч, м = int(мин // 60), int(мин % 60)
    колко = (f"{ч}ч {м:02d}мин" if ч else f"{м} мин")
    return "\n".join([
        f"😴 <b>БОТЪТ СПА {колко}</b> · {_sofia()}",
        f"📌 от {_sofia_ако_друг_ден(откога_utc, докога_utc)} до "
        f"{_sofia_ако_друг_ден(докога_utc)} · нито едно пускане",
        "⚠️ в тази дупка не съм гледал пазара",
        "👁 наваксвам от този бар нататък",
    ])


def _защо_мълчи(macro_raw, streaks, new_dir=None, стат=None):
    """ОДИТ-45 · ЗАЩО МЕРЕНОТО ПРАВИЛО МЪЛЧИ — с числата, не с усещане.

    Мерено на 1965 живи ръна: гейтът е отказал 100% от тях с `cell: mixed`,
    защото доларът пада (вдига златото), а лихвите растат (свалят го).
    Дотук това го знаеше само дневникът. Собственикът виждаше мълчащ бот.

    Връща списък от РЕДОВЕ (телеграф, един ред = едно нещо) или [] ако няма
    какво да се обясни."""
    if not isinstance(macro_raw, dict):
        return []
    д = macro_raw.get("долар"); л = macro_raw.get("лихви")
    if д is None or л is None:
        return ["⚠️ макро-фийдът мълчи · без вход, докато не се върне"]
    # знаците: числата са ВЕЧЕ обърнати (`-(промяна)`), значи ПЛЮС = добро за златото
    д_добро, л_добро = float(д) > 0, float(л) > 0
    Л = []
    Л.append(f"💵 доларът {'пада' if д_добро else 'расте'} {abs(float(д))*100:.1f}% · "
             f"{'вдига' if д_добро else 'сваля'} златото")
    Л.append(f"{'📉' if л_добро else '📈'} лихвите {'падат' if л_добро else 'растат'} "
             f"{abs(float(л)):.2f} · {'вдигат' if л_добро else 'свалят'} златото")
    if д_добро == л_добро:
        стр = int((streaks or {}).get("long" if д_добро else "short", 0))
        Л.append(f"✅ двете сочат {'НАГОРЕ' if д_добро else 'НАДОЛУ'} · "
                 f"{стр} {'ден' if стр == 1 else 'дни'} подред")
    else:
        Л.append("⏸ двете се бият · мереното правило мълчи")
        # 🔴 ОДИТ-48 · ЧИСЛОТО ИДВА ОТ КЛЕТКАТА, ПО КОЯТО СЪДИ ГЕЙТЪТ.
        # Дотук пишеше зазидано «−0.04$ (40094 сделки)» — числото от _meta,
        # което описва СЛЕТИТЕ кофи ПРЕДИ разделянето от 04.08. Гейтът обаче
        # съди по `/fresh/long/mixed/net` = −0.47$. Число на карта, което не
        # идва от клетката, по която се решава, е точно това, което този бот
        # не бива да прави.
        # 🔴 18.08 · ПОСОКАТА БЕШЕ ЗАКОВАНА НА «long». `new_dir` влизаше във
        # функцията и се изхвърляше, а клетките са РАЗЛИЧНИ:
        #     fresh/long/mixed  −0.47$
        #     fresh/short/mixed −1.30$   ← 2.8× по-лошо
        # Тоест шорт-картата цитираше чуждо, по-меко число. Това е точно
        # забраната от ОДИТ-48 осем реда по-горе, нарушена от самата поправка.
        _пос = new_dir if new_dir in ("long", "short") else "long"
        _кл = ((стат or {}).get("fresh", {}).get(_пос, {}).get("mixed", {})
               if isinstance(стат, dict) else {})
        _нет = _кл.get("net")
        if _нет is not None:
            Л.append(f"📌 в такъв пазар мереното дава "
                     f"{_пари(float(_нет))} на сделка"
                     + ("" if new_dir in ("long", "short") else " (за покупка)"))
        else:
            Л.append("📌 в такъв пазар мереното правило не носи нищо")
        # 🔴 18.08 · «КОГА». Дотук картата казваше КАКВО чака, но не КОЛКО.
        # Живо: 2552 от 2552 присъди за 15 работни дни са отказ — собственикът
        # вижда бот, който мълчи седмици, и няма как да различи «пазарът е
        # такъв» от «счупено е». Мерено на 5913 дни: подреждат се в 62.3% от
        # дните; тихите паузи са медиана 2 дни, най-дългата 30 (517 периода).
        # Числата идват от `_meta`, НЕ са заковани тук — сменят ли се при ново
        # измерване, картата ги следва.
        _ч = f"чакам {'лихвите' if д_добро else 'долара'} да тръгнат надолу" \
            if д_добро else "чакам долара да тръгне надолу"
        _т = ((стат or {}).get("_meta", {}) or {}).get("тишина_мерена") \
            if isinstance(стат, dict) else None
        # 🔴 ПОПРАВЕНО СЪЩИЯ ДЕН · ПЪРВОТО ЧИСЛО ОТГОВАРЯШЕ НА ГРЕШНИЯ ВЪПРОС.
        # Качих «паузите траят обикновено 2 дни» — това е медианата на ДЪЛЖИНАТА
        # НА ЕПИЗОД. Но картата се чете ВЪТРЕ в паузата, а тогава въпросът е
        # «колко ОЩЕ». Измерено (F32, 5913 дни, 517 епизода): оставащи от
        # произволен тих ден — медиана 4 дни, 72% свършват до седмица.
        # Дългите паузи съдържат повече дни → по-вероятно е да си в дълга.
        if isinstance(_т, dict) and _т.get("оставащи_медиана_дни"):
            Л.append(f"👁 {_ч} · още ~{_т['оставащи_медиана_дни']} дни в половината "
                     f"случаи · {_т['оставащи_до_седмица_pct']}% свършват до седмица")
        else:
            Л.append(f"👁 {_ч}")
    return Л


def _обрат_msg(старо, ново, macro_raw, streaks, стат=None):
    """ОДИТ-45в · МАКРОТО СМЕНИ СЪСТОЯНИЕТО. Това е събитието, което той чака.
    Измерено: за 9 дни (1965 ръна) състоянието НЕ се е сменяло нито веднъж —
    значи картата не може да стане спам."""
    _, л_ново = ново
    _, л_старо = старо
    подредено = ново[0] == ново[1]
    ико = "🟢" if (подредено and ново[0]) else "🔴" if подредено else "⏸"
    L = [f"{ико} <b>МАКРОТО СЕ {'ПОДРЕДИ' if подредено else 'РАЗБЪРКА'}</b> · {_sofia()}"]
    L += _защо_мълчи(macro_raw, streaks, стат=стат)
    if подредено:
        L.append("📌 това е пазарът, в който мереното правило работи")
    return "\n".join(L)


def _съгласни(board, посока):
    """ОДИТ-45 · ЧЕСТНОТО ЧИСЛО. Дотук пулсът броеше рамки — а те са копия.
    Мерено на 1965 ръна: в 84.6% седемте рамки са БУКВАЛНО еднакви и различни
    отчета никога не е имало повече от два. «7 от 7 съгласни» броеше седем
    копия на едно измерване. Сега броим РАЗЛИЧНИТЕ отчети."""
    if not board or not посока:
        return 0, 0
    от = [b for b in board if b[3] != "weak"]
    за = [b for b in от if b[1] == посока]
    return len(set((b[1], b[2], b[3]) for b in за)), len(set((b[1], b[2], b[3]) for b in от))


def _pulse_msg(part, board, best, new_dir, advice_txt, adv_ok, trade, s_trade,
               spot_g, spot_s, macro, shield, weekend, macro_raw=None, streaks=None,
               stats=None):
    """ОДИТ-29 · 3× на ден: жив съм, това гледам, това чакам."""
    ико, кога = {"09": ("☀️", "добро утро"), "14": ("🌤️", "докъде сме"),
                 "22": ("🌙", "как мина денят")}.get(part, ("📌", "какво гледам"))
    L = [f"{ико} {кога.capitalize()} · {_sofia()}"]
    if weekend:
        L.append("😴 борсата спи · отваря неделя вечер")
        return "\n".join(L)
    if spot_g:
        L.append(f"🥇 <code>{spot_g['mid']:,.2f}</code>"
                 + (" ⚠️резерва" if _от_резерва(spot_g) else "")
                 + (f" · 🥈 <code>{spot_s['mid']:,.3f}</code>"
                    + (" ⚠️резерва" if _от_резерва(spot_s) else "") if spot_s else ""))
    else:
        L.append("⚠️ живата цена мълчи · карам по бара")
    # 🔴 ОДИТ-45 · ДОТУК ТУК ПИШЕШЕ «{n}/7 мащаба» — НЕВЯРНО ЧИСЛО.
    # Мерено на 1965 живи ръна: в 84.6% седемте рамки са БУКВАЛНО еднакви и
    # различни отчета никога не е имало повече от ДВА. «7 от 7» броеше седем
    # копия на едно измерване, защото всички се съдят срещу ЕДНИ дневни нива.
    _обясн = _защо_мълчи(macro_raw, streaks, new_dir, стат=stats)
    _разбъркано = any(r.startswith("⏸") for r in _обясн)
    # ОДИТ-45б: при разбъркано макро НЕ обявяваме посока на дъската — два реда
    # по-долу пише, че няма да я ползваме. Един ред = едно нещо.
    if new_dir and not _разбъркано:
        _за, _общо = _съгласни(board, new_dir)
        L.append(f"{'🟢' if new_dir == 'long' else '🔴'} очертава се "
                 f"{'нагоре' if new_dir == 'long' else 'надолу'}"
                 + (f" · {_за} от {_общо} отчета" if _общо > 1 else ""))
    elif not new_dir and not _разбъркано:
        L.append("📌 посоката е разбъркана")
    # 🔴 ОДИТ-45 · И КАЗВА ЗАЩО МЪЛЧИ. Мерено: 93.2% от ръновете записваха само
    # «тихо (без събития)» и нищо не стигаше до него. Мълчанието Е решение —
    # трябва да се вижда, че е решение, а не повреда.
    L += _обясн
    има = False
    for нм, tr, sp, dec in (("🥇", trade, spot_g, 2), ("🥈", s_trade, spot_s, 3)):
        if tr:
            има = True
            прибр = [n for n, k in (("1️⃣", "tp1"), ("2️⃣", "tp2"), ("3️⃣", "tp3"))
                     if tr.get("hit", {}).get(k)]
            # 🔴 ОДИТ-61: ПО СТЪЛБАТА, не гола разлика. Редът над този изброява
            # прибраните трети — беше противоречие на едно и също място.
            пл, _ = _отворена_стълба(tr, sp, notes if 'notes' in dir() else None)
            L.append(f"{нм} държим от <code>{tr['entry']:,.{dec}f}</code>"
                     + (f" · {' '.join(прибр)} ✅" if прибр else "")
                     # 🔴 26.08 · САМО ДОЛАРИ, без пипсове. Собственикът:
                     # «парите не са нужни, пипсовете да са точни на макс —
                     # хората си играят с каквито лотове могат». Третата карта
                     # (ред 2960) отдавна ползва `_пари`, тези две — не.
                     + (f" · <b>{_пари(пл, tr.get('sym', 'XAUUSD'))}</b>"
                        if пл is not None else ""))
    if shield and new_dir == "short":
        L.append("👁 чакам американските данни")
    elif има:
        # ОДИТ-35: «до целите» обещаваше само единия край — сделката може да
        # свърши и на стоп, и той трябва да го чака, не да го смята за изключен.
        L.append("👁 следя до целите ИЛИ до стопа · пиша при всеки удар")
    elif new_dir and adv_ok:
        L.append("👁 чакам потвърждение · пращам вход")
    elif new_dir:
        # ОДИТ-45б: ако обяснението горе вече е казало ЗАЩО не влизаме,
        # този ред е трети път същото.
        if not _разбъркано:
            L.append("👁 не влизам · не е пресен")
    else:
        L.append("👁 нищо сега")
    return "\n".join(L)

def _cq_zone(score):
    """CQS скор → зона (по бандите на CyberQuant)."""
    if score < 40: return "Натрупване 🟢"
    if score < 60: return "Неутрална ⚪"
    if score < 75: return "Внимание 🟡"
    if score < 90: return "Опасност 🟠"
    return "Балон 🔴"


# 🔴 18.08 · KV_URL ПАДНА — нула употреби (AST обход + текстов грeп).
# 🔴 18.08 · CQ_CLUSTERS ПАДНА — четеше я САМО тест (зелена проверка върху
# мъртва константа), както беше с `_cq_clusters_line`.
# Историята на зоната от терминала (2013→днес, 4962 дни). Показва се като БАЗОВА ЧЕСТОТА,
# не като прогноза — това е за BTC, не за злато, и картата го казва изрично.
# 🔴 18.08 · CQ_ZONE_HIST ПАДНА — нула употреби. Картата отдавна не показва
# базовата честота на зоните, а коментарът още обясняваше как я показва.


# 🔴 18.08 · ТУК СТОЕШЕ ВТОРО, БАЙТ-ИДЕНТИЧНО ОПРЕДЕЛЕНИЕ НА `_cq_zone`
# (сверено с ast.dump). Второто мълчаливо засенчваше първото — а мълчаливо
# засенчване значи, че поправка в първото няма да свърши нищо и никой няма
# да разбере защо. Махнато е второто; първото остава непроменено.

def _cq_fetch(now_utc):
    """CyberQuant публично tRPC API, БЕЗ логин. Защитено — при всеки проблем връща None
    (никога не чупи бота). Дърпа CQS скор + страх/алчност + макро-календар. Веднъж на ден."""
    CQ = "https://cyberquant-g2mrw3tb.manus.space/api/trpc/"
    def _get(procs, inp):
        u = CQ + procs + "?batch=1&input=" + urllib.parse.quote(json.dumps(inp))
        with urllib.request.urlopen(urllib.request.Request(u, headers={"User-Agent": "Mozilla/5.0"}), timeout=12) as r:
            return json.loads(r.read().decode())
    # 🔴 21.08 · ТРИ РАЗЛИЧНИ НЕЩА В ЕДИН try. `score` се ползва САМО за реда
    # «🌡 крипто настроение … само за фон» — картата сама заявява, че е
    # декорация. А липсваше ли, ЦЕЛИЯТ календар изчезваше, тоест макро-щитът и
    # отброяването до новина висяха на козметично число.
    # ИЗПЪЛНЕНО с реални отговори от мрежата: «терминалът без score (календарът
    # е ЖИВ)» → None. Сега календарът има СВОЙ try и само той решава.
    score, fg = None, {}
    try:
        nul = {"json": None, "meta": {"values": ["undefined"]}}
        d = _get("terminal.getData,fearGreed.getAll", {"0": nul, "1": nul})
        try:
            score = float(d[0]["result"]["data"]["json"]["score"])
        except Exception:
            score = None
        try:
            fg = d[1]["result"]["data"]["json"] or {}
        except Exception:
            fg = {}
    except Exception:
        d, score, fg = None, None, {}
    try:
        c = _get("calendar.getUpcoming", {"0": {"json": {"days": 45}}})
        raw = c[0]["result"]["data"]["json"]
        events = []
        for e in raw:
            assets = str(e.get("affectsAssets", "")).upper()
            имe = str(e.get("title", ""))
            imp = str(e.get("impact", "")).lower()
            _по_актив = any(a in assets for a in ("GOLD", "XAU", "DXY", "USD"))
            # 🔴 21.08 · ВТОРИ, НЕЗАВИСИМ ПРИЗНАК: ИМЕТО. Дотук се съдеше САМО
            # по `affectsAssets` — ЧУЖДО поле с ЧУЖДА подредба. PCE е макро за
            # златото, но доставчикът го маркира като крипто/акции → изпадаше от
            # календара, тоест нито макро-щит, нито отброяване до новина.
            # Старият филтър НЕ се маха; този само добавя пропуснатите.
            _по_име = any(k in имe.upper() for k in МАКРО_ИМЕНА)
            if imp in ("high", "critical") and (_по_актив or _по_име):
                events.append({"name": имe[:60], "dt": str(e.get("eventDate", "")),
                               "impact": imp, "по": ("актив" if _по_актив else "име")})
        # КИБЕР КВАНТ: четирите клъстера (валуация/моментум/настроения/on-chain).
        # Защитено — липсват ли, останалото пак минава.
        cl = {}
        try:
            for k, v in (d[0]["result"]["data"]["json"].get("clusterScores") or {}).items():
                if v is not None:
                    cl[str(k)] = round(float(v), 1)
        except Exception:
            cl = {}
        # 🔴 21.08 · ПРАЗЕН КАЛЕНДАР ПРИ НЕПРАЗНА СУРОВИНА = СЧУПЕН ФИЛТЪР.
        # Филтърът съди по ЧУЖДА подредба (`affectsAssets`). Преименува ли
        # доставчикът полето, `events` става [], но dict-ът е валиден → кешът се
        # ПРЕЗАПИСВА с 0 събития и денят се маркира като успех. Оттам картата
        # казва «✅ няма голямо макро събитие пред нас» — мълчанието се преоблича
        # в ПОЛОЖИТЕЛНО потвърждение, а отброяването не пали нито веднъж.
        # ИЗПЪЛНЕНО: полето преименувано → dict? True · събития: 0 → ЗАПИСВА СЕ.
        if raw and not events:
            return None                              # за изхвърляне — кешът остава
        return {"score": (round(score, 1) if score is not None else None),
                "zone": (_cq_zone(score) if score is not None else ""),
                "raw_n": len(raw), "clusters": cl,
                "fg_crypto": fg.get("crypto", {}).get("value"), "fg_crypto_cls": fg.get("crypto", {}).get("classification", ""),
                "fg_stock": fg.get("stock", {}).get("value"), "fg_stock_cls": fg.get("stock", {}).get("classification", ""),
                "events": events, "fetched": now_utc}
    except Exception:
        return None


def _fng_live(timeout=8):
    """ЖИВИЯТ страх-и-алчност (alternative.me, без ключ) — сверено 04.08.2026: работи и от
    US рънър, ~0.5s. Кибер Квант чете точно него. Ползва се като СВЕЖА стойност срещу
    дневната снимка на терминала. Защитено: при всеки проблем → None, ботът не спира."""
    try:
        req = urllib.request.Request("https://api.alternative.me/fng/?limit=1",
                                     headers={"User-Agent": "Mozilla/5.0"})
        with urllib.request.urlopen(req, timeout=timeout) as r:
            d = json.loads(r.read().decode())
        it = (d.get("data") or [None])[0]
        v = int(it["value"])
        if not (0 <= v <= 100):
            return None
        return {"value": v, "cls": str(it.get("value_classification", ""))[:24]}
    except Exception:
        return None


def _cq_evt_dt(e):
    """ISO дата (с Z=UTC) → наивен UTC pd.Timestamp или None."""
    try:
        ts = pd.Timestamp(e.get("dt", ""))
        return ts.tz_convert("UTC").tz_localize(None) if ts.tz is not None else ts
    except Exception:
        return None


def _cq_macro_block(cq, now_utc):
    """(блокирай_ли, име) — голямо макро събитие (GOLD/DXY, high/critical) в прозорец
    −20…+40 мин около СЕГА? Блокира НОВ вход (двете посоки) — висока волатилност."""
    if not cq or not cq.get("events"):
        return False, None
    try:
        now = pd.Timestamp(now_utc)
    except Exception:
        return False, None
    for e in cq["events"]:
        evt = _cq_evt_dt(e)
        if evt is None:
            continue
        dmin = (now - evt).total_seconds() / 60.0
        if -20 <= dmin <= 40:
            return True, e.get("name", "макро събитие")
    return False, None


def _cq_next_event(cq, now_utc):
    """Най-близкото БЪДЕЩО голямо събитие → етикет (за референцията)."""
    if not cq or not cq.get("events"):
        return None
    try:
        now = pd.Timestamp(now_utc)
    except Exception:
        return None
    best = None
    for e in cq["events"]:
        evt = _cq_evt_dt(e)
        if evt is not None and evt > now and (best is None or evt < best[0]):
            best = (evt, e)
    if best is None:
        return None
    evt, e = best
    return f"{e.get('name', '')} — {_sofia_dt(evt.isoformat())} София"


def _остава(часове):
    """«15ч30» / «40 мин» — човешки, без десетични точки."""
    м = int(round(float(часове) * 60))
    if м < 60:
        return f"{max(м, 1)} мин"
    ч, ост = м // 60, м % 60
    if ост == 0:                       # «2ч00» е машинно; човек казва «2 часа»
        return "1 час" if ч == 1 else f"{ч} часа"
    return f"{ч}ч{ост:02d}"


def _news_due(cq, now_utc, meta):
    """(събитие, момент, часове_до, ключ, повод) или None — време ли е за карта?

    ОБЕЩАНИЕТО: първата дума идва поне НОВИНИ_ПРЕДИ_Ч часа преди събитието,
    после на всеки НОВИНИ_ПОВТОР_Ч часа, до самото него.
    Защитено: липсва ли календар или е повреден момент → None, ботът не спира.
    """
    if not cq or not cq.get("events"):
        return None
    try:
        now = pd.Timestamp(now_utc)
    except Exception:
        return None
    best = None
    for e in cq["events"]:
        evt = _cq_evt_dt(e)
        if evt is not None and evt > now and (best is None or evt < best[0]):
            best = (evt, e)
    if best is None:
        return None
    evt, e = best
    ч = (evt - now).total_seconds() / 3600.0
    # ЗАПАСЪТ: ботът се буди на 5 мин, но мерено е спал и по 15. Без запас
    # първата карта би паднала под обещаните 15 часа — тихо нарушено обещание.
    if ч > НОВИНИ_ПРЕДИ_Ч + НОВИНИ_ЗАПАС_Ч:
        return None
    ключ = f"{e.get('name', '')}|{e.get('dt', '')}"
    зап = meta.get("новина") or {}
    if isinstance(зап, dict) and зап.get("кой") == ключ:
        try:
            откога = (now - pd.Timestamp(зап.get("utc"))).total_seconds() / 3600.0
        except Exception:
            откога = 999.0
        if откога < НОВИНИ_ПОВТОР_Ч:
            return None
        повод = "повторение"
    else:
        повод = "първо"
    return (e, evt, ч, ключ, повод)


def _news_blizko(cq, now_utc):
    """Има ли събитие вътре в прозореца на отброяването? (за да не папагалства
    дневната карта, дори в рън, в който самото отброяване не е на ред)"""
    if not cq or not cq.get("events"):
        return False
    try:
        now = pd.Timestamp(now_utc)
    except Exception:
        return False
    for e in cq["events"]:
        evt = _cq_evt_dt(e)
        if evt is not None and now < evt <= now + pd.Timedelta(hours=НОВИНИ_ПРЕДИ_Ч + НОВИНИ_ЗАПАС_Ч):
            return True
    return False


def _news_msg(e, evt, ч, ключ=None, повод="първо"):
    """Картата с отброяването. Казва КАКВО, КОГА, СЛЕД КОЛКО, и — най-важното —
    КАКВО ПРАВИ БОТЪТ заради нея. Без лекции защо съществува макростатистика."""
    име = str(e.get("name", "макро събитие")).strip()
    гл = f"📅 ВАЖНА НОВИНА СЛЕД {_остава(ч)} · "
    _място = 78 - len(гл)                      # таванът на първия ред в стил.py
    if len(име) > _място:
        име = име[:max(10, _място - 1)].rstrip(" —-·,") + "…"
    _от = _sofia_dt((evt - pd.Timedelta(minutes=20)).isoformat())[-5:]
    _до = _sofia_dt((evt + pd.Timedelta(minutes=40)).isoformat())[-5:]
    L = [гл + име,
         f"⏰ {_sofia_dt(evt.isoformat())} София — тогава го обявяват",
         "⚠️ в такъв момент златото минава по 20-40$ за секунди в двете посоки",
         f"🛑 не отварям нов вход от {_от} до {_до} София",
         "📌 отворена сделка не се пипа — стопът и целите остават каквито са"]
    if ч <= НОВИНИ_ПОВТОР_Ч:
        L.append("👁 това е последното напомняне преди самото събитие")
    else:
        L.append(f"👁 ще ти напомня пак след {_остава(НОВИНИ_ПОВТОР_Ч)}")
    return "\n".join(L)


def _cq_msg(cq, now_utc, fng_live=None, отброяване=False):
    """ОДИТ-28/29 · от 12 реда за биткойн до три реда за онова, което мени
    поведението на бота: следващото голямо макро събитие."""
    съб = _cq_next_event(cq, now_utc)
    L = []
    if съб and отброяване:
        # 🔴 Отброяването вече го казва на всеки 2 часа. Дневната карта да не
        # повтаря същото като папагал — казва само че отделната карта я води.
        L.append(f"📌 ПАЗАРЕН ФОН · {_sofia()}")
        L.append("📅 за идващото събитие ти пращам отделна карта с отброяване")
    elif съб:
        L.append(f"📅 ИДВА · {съб}")
        L.append("⚠️ около такива новини цената скача на празно")
        L.append("👁 не отварям нов вход в този прозорец")
    else:
        L.append(f"📌 ПАЗАРЕН ФОН · {_sofia()}")
        L.append("✅ няма голямо макро събитие пред нас")
    зона = str(cq.get("zone", "")).strip()
    точки = cq.get("score")
    if зона and точки is not None:
        # 🔴 18.08 · `fng_live` СЕ ДЪРПАШЕ ПО МРЕЖАТА НА ВСЕКИ РЪН И СЕ ИЗХВЪРЛЯШЕ.
        # Картата печаташе ДНЕВНАТА снимка на терминала. Изпълнено: снимка
        # «82 Еуфория» + живо «12 Extreme Fear» → картата казваше «Еуфория».
        # Собствената docstring на `_fng_live` заявява целта си: «като СВЕЖА
        # стойност срещу дневната снимка». Целта не беше изпълнена, а заявката
        # се плащаше. Сега: показва се живото, а снимката — само ако се разминава.
        _жив = None
        if isinstance(fng_live, dict):
            _жив = fng_live.get("score", fng_live.get("value"))
        elif isinstance(fng_live, (int, float)):
            _жив = fng_live
        try:
            _жив = float(_жив) if _жив is not None else None
        except (TypeError, ValueError):
            _жив = None
        if _жив is not None and abs(_жив - float(точки)) >= 5:
            L.append(f"🌡 крипто настроение: {_жив:.0f}/100 сега · "
                     f"{зона} ({точки:.0f}) по дневната снимка · само за фон")
        else:
            L.append(f"🌡 крипто настроение: {зона} ({точки:.0f}/100) · само за фон")
    return "\n".join(L)

def track_trade(trade, bars, basis, now_price, now_utc, spot=None, скок_базис=False):
    """bars = фючърсни 5м (пълният път, ~10 мин назад), превеждани в спот
    чрез базиса. spot = живата цена (моментално, Ф7.1). Гап → реална цена.
    Връща (trade|None, events); event = (kind, price, when, via, gap).

    `скок_базис=True` → базисът току-що е презакотвен и скалата на баровете се
    е преместила с една стъпка. Тогава баровете НЕ се съдят: измерено, при
    скок +30.22$ върху 12 АБСОЛЮТНО ПЛОСКИ бара лонгът «удря стоп», а шортът
    «удря и трите цели» — за движение, което не се е случило. Спот-изходите
    (в спот-света, независими от базиса) и изходът по време ОСТАВАТ.
    """
    events = []
    if trade is None:
        return None, events
    since = pd.Timestamp(trade.get("checked", trade["opened"]))
    lv = trade["levels"]; d = trade["direction"]
    idx = bars.index if bars is not None else []
    if скок_базис and len(idx):
        # 🔴 21.08, ВТОРА ВЕРСИЯ. Първата само пропускаше баровете ТОЗИ рън, но
        # `checked` не мърдаше (при празен `processed` блокът долу не се стига),
        # а знамето е за ЕДИН рън. Значи на следващия рън СЪЩИТЕ барове пак са
        # `ts > checked` и се съдеха — вече с новия базис.
        # ИЗПЪЛНЕНО: рън на скока → събития []; СЛЕДВАЩИЯТ рън → ('sl', 4591.465)
        # и трите цели за шорта. Дефектът беше само ОТЛОЖЕН с пет минути, а
        # собственият ми тест го обяви за оправен, защото гледаше само първия рън.
        # Тези барове са двусмислени ПО УСТРОЙСТВО — не бива да се съдят нито
        # със стария, нито с новия базис. Затова се прескачат ОКОНЧАТЕЛНО.
        trade["checked"] = str(idx[-1])
        idx = []
    processed = []                                   # M1: следим кои барове реално обходихме
    for ts in idx:
        if ts <= since:
            continue
        hi = float(bars.loc[ts, "High"]) - basis
        lo = float(bars.loc[ts, "Low"]) - basis
        op = float(bars.loc[ts, "Open"]) - basis
        if pd.isna(hi) or pd.isna(lo) or pd.isna(op):  # M2: бар с NaN OHLC крие удар → пропусни
            continue
        processed.append(ts)
        sl_hit = (lo <= lv["sl"]) if d == "long" else (hi >= lv["sl"])
        # BE-стоп (sl=вход след ТП1) НЕ бива да пали на бара, който УДАРИ ТП1, при
        # преразглеждане (M1 оставя последния бар преразглеждаем) — иначе широк ТП1-бар
        # с фитил под входа затваря фалшиво печелившата сделка на нула.
        # 🔴 ОДИТ-5 (L1-01, критичен): тук се сравняваха НИЗОВЕ с РАЗЛИЧЕН формат.
        # Барният път пишеше be_since = str(ts) → "2026-07-29 03:00:00" (интервал на позиция 10),
        # спот-пътят пишеше now_utc → "2026-07-29T02:10" (буква T). ' '(0x20) < 'T'(0x54), значи
        # за ВСЕКИ бар от същия календарен ден сравнението даваше True и BE-стопът се ИЗКЛЮЧВАШЕ
        # до полунощ. Възпроизведено: ТП1 по спот в 02:10 → барът 02:15 минава ПРЕЗ входа и
        # track_trade не връща нищо; същият бар с дата 30.07 гърми нормално. Последици: сделката
        # виси отворена (→ повторното предлагане и насрещните карти мълчат), а после ботът може
        # да прати «ТП2 ПОСТИГНАТ» за позиция, която ти вече си затворил на нула.
        if sl_hit and lv["sl"] == trade["entry"] and trade.get("be_since") and _ts_le(ts, trade["be_since"]):
            sl_hit = False
        if sl_hit:                                   # консервативно: стопът първи
            gap = (op <= lv["sl"]) if d == "long" else (op >= lv["sl"])
            px = round(op, 3) if gap else lv["sl"]
            events.append(("sl", px, str(ts), "бар", gap)); trade["status"] = "closed_sl"
            break
        for k in ("tp1", "tp2", "tp3"):
            if not trade["hit"].get(k):
                tp_hit = (hi >= lv[k]) if d == "long" else (lo <= lv[k])
                if tp_hit:
                    gap = (op >= lv[k]) if d == "long" else (op <= lv[k])
                    px = round(op, 3) if gap else lv[k]
                    # 🔧 О12 · ПАЗИМ И ЦЕНАТА НА ПОПЪЛВАНЕ, не само че е ударена.
                    # При гап `px` е цената на ОТВАРЯНЕТО — по-добра от нивото.
                    # Дотук се изхвърляше и стълбата смяташе по НИВОТО, тоест
                    # подценяваше печалбата при всеки гап през цел.
                    trade["hit"][k] = True
                    trade.setdefault("hit_px", {})[k] = px
                    events.append((k, px, str(ts), "бар", gap))
                    if k == "tp1":                        # картата обещава «стоп на входа» → ПРАВИМ го
                        lv["sl"] = trade["entry"]         # иначе изходната сметка лъже (безрисково ≠ −$20)
                        trade["be_since"] = str(ts)       # BE-стопът важи от СЛЕДВАЩ бар (не този)
                    if k == "tp3":
                        trade["status"] = "closed_tp3"
        if trade.get("status", "open") != "open":
            break
    # Ф7.1 · МОМЕНТАЛНО: живият спот СЕГА (баровете са до 10-15 мин назад)
    if trade.get("status", "open") == "open" and spot:
        p = spot["mid"]
        if (p <= lv["sl"]) if d == "long" else (p >= lv["sl"]):
            # 🔴 19.08 · ДОТУК ТУК СЕ ПИШЕШЕ ТОЧНОТО НИВО И gap=False — ВИНАГИ.
            # Барният път три реда по-горе смята гапа честно; спот-пътят обявяваше
            # идеален фил. Собственият тракер веднъж е записал −23.88$ при стоп
            # −20.00$, тоест ботът съобщаваше по-добър изход, отколкото е получен.
            #
            # ПРИНЦИПЪТ: целта е ЛИМИТНА поръчка → пълни се ТОЧНО на нивото (и
            # затова долу НЕ се пипа). Стопът е ПАЗАРНА → пълни се където е
            # пазарът, от ЛОШАТА страна на спреда: лонг продава на BID, шорт
            # купува на ASK.
            #
            # ЗАЩО СЕГА: форуърд-тестът е единственото, което има значение оттук
            # нататък. Систематично занижени загуби го правят да изглежда
            # по-добър, отколкото е — най-опасната лъжа, защото кара да рискуваш
            # повече.
            _изх = float(spot.get("bid", p) if d == "long" else spot.get("ask", p))
            _отвъд = (lv["sl"] - _изх) if d == "long" else (_изх - lv["sl"])
            _спред = max(float(spot.get("ask", p)) - float(spot.get("bid", p)), 0.0)
            # «с гап» само ако филът е по-лош от нивото С ПОВЕЧЕ ОТ ЕДИН СПРЕД —
            # половин спред не е гап, а нормалната цена на излизане.
            events.append(("sl", round(_изх, 3) if _отвъд > 0 else lv["sl"],
                           now_utc, "спот", _отвъд > _спред))
            trade["status"] = "closed_sl"
        else:
            for k in ("tp1", "tp2", "tp3"):
                if not trade["hit"].get(k):
                    # 🔴 19.08 · СПУСЪКЪТ ПО СТРАНАТА, НА КОЯТО РЕАЛНО ТЪРГУВАШ.
                    # Дотук тук се съдеше по `p` = СРЕДАТА, а вчерашната поправка
                    # хвана само стопа. Мерено: от 4293 засечки 504 (11.7%) са в
                    # прозореца «средата мина нивото, страната НЕ»; 462 от тях се
                    # напълват по-късно на същото ниво (без разлика), но 41
                    # (0.96%) са ФАНТОМ — стопът удря, преди страната да стигне.
                    # Цена в производството: 0.014–0.043$/сделка.
                    _стр = float(spot.get("bid", p) if d == "long"
                                 else spot.get("ask", p))
                    if (_стр >= lv[k]) if d == "long" else (_стр <= lv[k]):
                        # ФИЛЪТ НЕ СЕ ПИПА: целта е ЛИМИТНА поръчка и се пълни
                        # ТОЧНО на нивото, дори цената да е минала отвъд. Тук
                        # `lv[k]` Е верният фил — за разлика от стопа горе.
                        # (П72 пази точно това — да не го «поправи» някой утре
                        # и да занижи печалбите също толкова несправедливо.)
                        trade["hit"][k] = True; events.append((k, lv[k], now_utc, "спот", False))
                        if k == "tp1":                    # стоп на входа (както картата казва)
                            lv["sl"] = trade["entry"]
                            trade["be_since"] = now_utc   # BE-стопът важи от следващ бар/тик
                        if k == "tp3":
                            trade["status"] = "closed_tp3"
    if trade.get("status", "open") == "open":
        age = (pd.Timestamp(now_utc) - pd.Timestamp(trade["opened"])).days
        if age >= ДНИ_МАКС:
            events.append(("time", now_price, now_utc, "време", False)); trade["status"] = "closed_time"
    # M1: за ОТВОРЕНА сделка НЕ напредвай checked отвъд ПРЕДПОСЛЕДНИЯ обходен бар —
    # последният може да е още оформящ се (yfinance връща частичния бар); остави го
    # преразглеждаем следващия рън, когато е завършен с пълния си диапазон. Идемпотентно:
    # маркиран ТП се пропуска (if not hit), а СТОП затваря сделката (не се пре-следи).
    if trade["status"] == "open":
        if len(processed) >= 2:
            trade["checked"] = str(processed[-2])
        # 0-1 нови барове → не мърдай checked (преразгледай ги наново следващия рън)
    elif processed:
        trade["checked"] = str(processed[-1])         # затворена — сделката тъй или иначе се трие
    return (None if trade["status"] != "open" else trade), events


def _migrate_trade(trade, basis, dec=2, notes=None):
    """v4 сделка (фючърсни нива) → спот-леджър: изместване с базиса, еднократно.
    Б5: мигрира САМО при ПОТВЪРДЕН базис (≠0). При базис 0 (спотът недостъпен този
    рън) отлага — иначе би маркирала «spot» с фючърсни нива необратимо."""
    if trade is None or trade.get("ledger") == "spot":
        return trade
    if not basis:                                        # базисът не е сиден този рън → чакай
        if notes is not None:
            notes.append("миграция на сделката отложена — базисът още не е потвърден")
        return trade
    if not trade.get("v2"):
        trade["checked"] = trade["opened"]; trade["v2"] = True
    trade["entry"] = round(trade["entry"] - basis, dec)
    trade["levels"] = {k: round(v - basis, dec) for k, v in trade["levels"].items()}
    trade["ledger"] = "spot"
    return trade


# ---------- пощенска кутия (Ф8.1): съобщение не се губи никога ----------
def _send_raw(text):
    tok = os.environ.get("TELEGRAM_TOKEN"); ch = os.environ.get("TELEGRAM_CHAT_ID")
    if not tok or not ch:
        return "DRY_RUN (няма токен)"
    url = f"https://api.telegram.org/bot{tok}/sendMessage"
    data = urllib.parse.urlencode({"chat_id": ch, "text": text[:4000], "parse_mode": "HTML"}).encode()
    last = ""
    for _ in range(2):                                    # 2 опита на пускане
        try:
            with urllib.request.urlopen(urllib.request.Request(url, data=data), timeout=15) as r:
                # 🔴 ОДИТ-13 (ПАРИ): 2xx НЕ значи доставено. Телеграм маркира отказа с
                # ok:false; прокси/капан-портал/грешен хост връща 200 с чуждо тяло.
                # Преди това тялото изобщо не се четеше → картата се ТРИЕШЕ от пощата И
                # влизаше в sent_log.jsonl като доставена, а одит-роботът, който чете
                # sent_log, го потвърждаваше. Двойно заглушаване.
                # Възпроизведено: 200 + {"ok":false,"description":"chat not found"} → 'SENT (200)'.
                # Без ok:true = МЕК провал (ретрай вечно), НЕ отровно — за да не хвърлим
                # изходна карта заради непознат, но валиден отговор.
                try:
                    _b = json.loads(r.read().decode("utf-8", "replace"))
                except Exception:
                    _b = None
                if isinstance(_b, dict) and _b.get("ok") is True:
                    return f"SENT ({r.status})"
                _why = (str(_b.get("description", "нечетлив отговор"))[:100]
                        if isinstance(_b, dict) else "нечетлив отговор")
                last = f"SEND_FAILED: HTTP {r.status} без ok:true — {_why}"
                import time; time.sleep(3)
                continue
        except urllib.error.HTTPError as e:               # HTTP статус от Телеграм
            # ДИАГНОСТИКА: прочети ТОЧНОТО описание от Телеграм (напр. «chat not found»,
            # «group upgraded to supergroup» + новото chat_id) — за да не гадаем при 400.
            desc = ""
            try:
                _b = json.loads(e.read().decode())
                desc = str(_b.get("description", ""))[:140]
                _mig = _b.get("parameters", {}).get("migrate_to_chat_id")
                if _mig:
                    desc += f" [НОВО chat_id={_mig}]"
            except Exception:
                pass
            # 429 (rate-limit при catch-up burst), 408 (timeout), 425 (too-early) = МЕКИ →
            # ретрай вечно. Инак 3 поредни 429 триеха реална карта с ПЕРФЕКТЕН HTML (🔴).
            if e.code in (429, 408, 425) or e.code >= 500:
                last = f"SEND_FAILED: HTTP {e.code} (rate/timeout/server) {desc}".strip()
                import time; time.sleep(3)
            elif e.code in (401, 403):
                # 🔴 21.08 · «МОЯТА КАРТА Е РАЗВАЛЕНА» ≠ «МОЯТА САМОЛИЧНОСТ Е
                # РАЗВАЛЕНА». 401 (отменен токен) и 403 (ботът изгонен от групата)
                # падаха в същата кофа като развален HTML → след 3 ръна картата се
                # хвърляше със статус «ОТРОВНО-ХВЪРЛЕНО (развален HTML)». Пазачът
                # за липсващ токен не палеше, защото токен ИМА — просто невалиден.
                # ИЗПЪЛНЕНО: рън 4 хвърли карта с изряден HTML `<b>ЛОНГ 4639</b>`.
                # Изходът на процеса беше 0, алармата не гръмна, дневникът зелен.
                # Този провал е ОБЩ ЗА ВСЯКА КАРТА — не бива да осъжда никоя.
                return f"AUTH_FAIL:{e.code} {desc}".strip()
            elif 400 <= e.code < 500:                      # 400/404/413 = истински «отровни»
                return f"HARD_FAIL:{e.code} {desc}".strip()   # + точната причина от Телеграм
            else:
                last = f"SEND_FAILED: HTTP {e.code} {desc}".strip()
                import time; time.sleep(3)
        except Exception as e:                            # мрежа/таймаут: МЕК провал → ретрай вечно
            last = f"SEND_FAILED: {str(e)[:80]}"
            import time; time.sleep(3)
    return last


POISON_HARD_FAILS = 3     # Б6: толкова ТВЪРДИ (4xx) провала = отровно (развален HTML) → хвърли
# ...но НИКОГА за тези: те съобщават пари, които вече са на риск (ОДИТ-5 / L2-01)
# 🔴 ОДИТ-56 · «brain-exit» ЛИПСВАШЕ. Това е картата «🛑 СТОПЪТ удари ·
# наблюдението от 20:26» — развръзката на сетъп, който собственикът е следил.
#  (сянката) Е в списъка, а тя е също толкова хипотетична. Значи
# мозъчните развръзки можеха да бъдат ИЗХВЪРЛЕНИ като отровни, орязани от
# тавана на опашката (v10.4) и да не се разпознаят като пари при повреден ред
# (v10.6). Мерено в живия sent_log: 7 такива карти вече са пратени.
EXIT_TAGS = ("exit", "s-exit", "sh-exit", "brain-exit")
def _strip_html(t):
    """Последен шанс за изходна карта, която Телеграм отказва заради HTML: гол текст."""
    import re as _re, html as _h
    return _h.unescape(_re.sub(r"<[^>]+>", "", t))
def _outbox_flush(out_dir, new_msgs, statuses, dry=False):
    """Стари неизпратени първо, после новите. Провалените остават за следващия рън.
    Връща set() с ТАГОВЕТЕ, реално пратени този рън (за да гейтнем записа — Б1).
    Б6: всяко съобщение носи first_ts + attempts (за журнал) + hard_fails; отровно се
    хвърля САМО при hard_fails≥3 (твърди 4xx). Мек/429/мрежов провал → ретрай вечно."""
    ob_f = out_dir / "outbox.jsonl"
    now_iso = datetime.now(timezone.utc).replace(tzinfo=None).isoformat(timespec="seconds")
    pending = []
    if ob_f.exists():
        # 🔴 ОДИТ-50 · ДОТУК ТУК СТОЕШЕ `except Exception: pass` — повреден ред
        # изчезваше БЕЗ СЛЕД. А редът може да е изходна карта («🛑 СТОПЪТ удари»),
        # тоест пари вече на риск — класът, който целият останал код пази изрично.
        # И записът с `"\n".join(...)` го прави вероятно: умре ли процесът по
        # средата (Actions има таймаут 8 мин), последният ред остава отрязан.
        _счуп = []
        for ln in ob_f.read_text(encoding="utf-8").splitlines():
            if not ln.strip():
                continue
            try:
                pending.append(json.loads(ln))
            except Exception:
                _счуп.append(ln)
        if _счуп:
            # нищо не се губи безвъзвратно — суровият текст отива настрана
            try:
                with (out_dir / "outbox_broken.jsonl").open("a", encoding="utf-8") as _bf:
                    for _l in _счуп:
                        _bf.write(json.dumps({"utc": now_iso, "raw": _l[:4000]},
                                             ensure_ascii=False) + "\n")
            except Exception:
                pass
            _пари = [l for l in _счуп
                     if any(t in l for t in EXIT_TAGS) or "СТОПЪТ" in l or "ТП" in l]
            if _пари:
                statuses.append(f"🔴 {len(_пари)} ПОВРЕДЕНИ реда в пощата приличат на "
                                f"ИЗХОДНА карта — виж outbox_broken.jsonl")
            else:
                statuses.append(f"⚠️ {len(_счуп)} повредени реда в пощата — "
                                f"запазени в outbox_broken.jsonl")
    for t, m in new_msgs:
        pending.append({"tag": t, "text": m, "first_ts": now_iso, "attempts": 0})
    # НАХОДКА B: signal/s-signal = «намерение да отвориш сделка СЕГА». Пренесен от минал рън
    # и НЕ регенериран този рън → условията са се сменили (щит/пауза/уикенд/F1) → изхвърли го,
    # инак картата стига до човека, но сделка НЕ се отваря/следи (осиротяла карта).
    fresh_tags = {t for t, _ in new_msgs}
    # 🔴 21.08 · ИЗХВЪРЛЯНЕТО СТАВАШЕ БЕЗМЪЛВНО. То е ПРЕДИ цикъла за пращане,
    # значи никога не стига до `statuses.append` — а дедупът точно отдолу СЕ
    # обажда. Междувременно на собственика вече е отпечатано «signal НЕ пратен
    # … (ще опита пак)», а втори опит НЯМА: щом реофер-вратите са затворени,
    # картата не се регенерира и изчезва. ДОКАЗАНО с истинската функция:
    # карта в пощата → statuses=[] · sent_tags=set() · outbox ПРАЗЕН.
    _осир = [m for m in pending
             if (m["tag"] in ("signal", "s-signal") and m["tag"] not in fresh_tags
                 and m.get("first_ts", now_iso) < now_iso)]
    if _осир:
        statuses.append(f"🔴 {len(_осир)} осиротели карти изхвърлени "
                        f"({', '.join(sorted(set(m['tag'] for m in _осир)))}) — "
                        f"условията се смениха, НЯМА да се опита пак")
    pending = [m for m in pending
               if not (m["tag"] in ("signal", "s-signal") and m["tag"] not in fresh_tags
                       and m.get("first_ts", now_iso) < now_iso)]
    # R1: дедуп по таг за ПРЕПОВТАРЯЩИТЕ се карти (signal/s-signal/digest/status) —
    # при срив на Телеграм не трупай N копия; пази само НАЙ-НОВОТО (последната цена).
    DEDUP = ("signal", "s-signal", "digest", "status", "pulse", "cq-ref", "standing")
    seen_last = {}
    for i, msg in enumerate(pending):
        if msg["tag"] in DEDUP:
            seen_last[msg["tag"]] = i          # последният индекс за тоя таг
    # 🔴 ОДИТ-62 · ДЕДУПЪТ ИЗХВЪРЛЯШЕ БЕЗ ДА КАЖЕ. «Колко карти се губят» беше
    # непреброимо от дневника — а точно това искаш да знаеш, когато чатът мълчи.
    _преди_дедуп = len(pending)
    pending = [m for i, m in enumerate(pending)
               if m["tag"] not in DEDUP or seen_last[m["tag"]] == i]
    if len(pending) < _преди_дедуп:
        statuses.append(f"📎 дедуп: {_преди_дедуп - len(pending)} стари копия махнати "
                        f"(пази се най-новото на всеки таг)")
    remaining = []; sent_tags = set(); no_token = False; auth_fail = ""
    # 🔴 ОДИТ-48 · ТАВАНЪТ БЕШЕ ОБЯВЕН И НЕ СЕ ПОЛЗВАШЕ НИКЪДЕ (мое, v9.8), а
    # тестът ми «го пазеше», защото проверяваше само декларацията. Сега реже.
    _орязани = 0
    for msg in pending:
        msg.setdefault("first_ts", now_iso); msg["attempts"] = msg.get("attempts", 0) + 1
        # ОТРОВНО = само ТВЪРДИ провали (развален HTML, 4xx); мрежов срив НЕ брои →
        # легитимен изход не се хвърля при дълъг Телеграм срив (краен-случай находка).
        # 🔴 ОДИТ-5 (L2-01, критичен): но ИЗХОДНИТЕ карти НИКОГА не се хвърлят. Те съобщават
        # пари, които ВЕЧЕ са на риск: сделката е затворена на диска, стоп-пазачът е ударил,
        # а човекът не знае, че е излязъл — държи позиция, за която ботът мисли, че е закрита.
        # 15 минути 4xx (3 ръна на 5-минутна каденция) стигаха, за да изчезне «СТОП УДАРЕН».
        # Изходите чакат вечно; при 3+ твърди провала пращаме гол текст без HTML (последен шанс).
        if msg.get("hard_fails", 0) >= POISON_HARD_FAILS:
            if msg["tag"].split(":")[0] in EXIT_TAGS:
                if not msg.get("plain"):
                    msg["plain"] = True
                    msg["text"] = _strip_html(msg["text"])
                    statuses.append(f"{msg['tag']}=ИЗХОД: HTML махнат, продължавам да опитвам")
                # пада надолу и се пробва пак — изходна карта НЕ се хвърля
            else:
                statuses.append(f"{msg['tag']}=ОТРОВНО-ХВЪРЛЕНО (развален HTML)")
                continue
        if dry:
            # 🔴 ОДИТ-13 (ПАРИ): сух рън НЕ е доставка. Преди това нямаше remaining.append,
            # значи съобщението се ТРИЕШЕ от пощата, и се добавяше в sent_tags, значи се
            # обявяваше за ПРАТЕНО. Едно `python live_bot.py --out live` без --send
            # изтриваше чакащата «СТОП УДАРЕН» карта за позиция, която е НА РИСК, и
            # маркираше meta["digest"] за деня, тъй че вечерната карта повече не излизаше.
            # Възпроизведено: 2 карти в пощата → 0 останали, обявени ['digest','exit:sl'].
            statuses.append(f"{msg['tag']}=DRY (остава в пощата)")
            remaining.append(msg); continue
        # ОДИТ-9 (П13): `_send_raw` лови всичко ВЪТРЕ в цикъла си, но кодът ПРЕДИ цикъла
        # (urlencode на текста) може да хвърли. Тогава изключението излизаше чак от main(),
        # ботът крашваше, а `outbox.jsonl` се записва ЧАК СЛЕД тази обиколка → ЦЯЛАТА поща
        # се губеше, включително изходни карти за пари, които вече са на риск.
        # Мерено с изпълнен тест: RuntimeError в _send_raw → traceback от main() + нула outbox.
        # Сега всяко изключение е МЕК провал: съобщението остава и се пробва пак.
        try:
            st = _send_raw(msg["text"])
        except Exception as _e:
            st = f"SEND_FAILED: изключение {type(_e).__name__}: {str(_e)[:60]}"
        statuses.append(f"{msg['tag']}={st}")
        if st.startswith("SENT"):
            sent_tags.add(msg["tag"])
            with (out_dir / "sent_log.jsonl").open("a", encoding="utf-8") as fh:
                fh.write(json.dumps({"utc": now_iso, "tag": msg["tag"], "text": msg["text"]},
                                    ensure_ascii=False) + "\n")
        elif st.startswith("AUTH_FAIL"):
            # Самоличността е обща за всяка карта → НЕ брои за «отровна» карта.
            # Съобщението остава в пощата и се вдига същата тревога като при
            # липсващ токен, за да гръмне `if: failure()` в workflow-а.
            remaining.append(msg)
            no_token = True
            auth_fail = st[len("AUTH_FAIL:"):].strip()[:70]
        elif st.startswith("HARD_FAIL"):
            msg["hard_fails"] = msg.get("hard_fails", 0) + 1
            remaining.append(msg)                         # ще опита още 2 пъти, после отровно
        elif st.startswith("DRY_RUN"):
            # 🔴 ОДИТ-5 (L2-02, критичен): «няма токен» НЕ е успешно пращане. Преди този клон
            # съобщението просто изчезваше — липсващ/изтекъл секрет изтриваше цялата поща, а
            # рънът оставаше ЗЕЛЕН. Конфигурационна грешка изглеждаше точно като тих пазар.
            remaining.append(msg)                         # ПАЗИ съобщението
            no_token = True
        else:
            remaining.append(msg)                         # мек провал → ретрай вечно (не брои за отровно)
    # 🔴 ОДИТ-48 · ТАВАНЪТ РЕАЛНО РЕЖЕ. Дотук беше само ОБЯВЕН (мое, v9.8), а
    # тестът ми «го пазеше», защото проверяваше единствено декларацията —
    # константа, която нищо не прави, и тест, който я пази. Хванато от армията.
    # ИЗХОДНИТЕ карти НИКОГА не се режат: те съобщават пари, вече на риск.
    if ОПАШКА_ТАВАН > 0 and len(remaining) > ОПАШКА_ТАВАН:
        _пази = [m for m in remaining
                 if str(m.get("tag", "")).split(":")[0] in EXIT_TAGS]
        _друго = [m for m in remaining
                  if str(m.get("tag", "")).split(":")[0] not in EXIT_TAGS]
        _място = max(0, ОПАШКА_ТАВАН - len(_пази))
        _орязани = len(_друго) - _място
        remaining = _пази + (_друго[-_място:] if _място else [])
        if _орязани > 0:
            statuses.append(f"🔴 опашката преля: {_орязани} НАЙ-СТАРИ карти "
                            f"изхвърлени (таван {ОПАШКА_ТАВАН}); изходните са запазени")
    ob_f.write_text("\n".join(json.dumps(m, ensure_ascii=False) for m in remaining), encoding="utf-8")
    if no_token:
        # 🔴 21.08 · ДВЕ РАЗЛИЧНИ БЕДИ, ЕДИН ТЕКСТ. «Няма токен» и «токенът е
        # отменен / ботът е изгонен» изискват различно действие от собственика,
        # а картата казваше едно и също. Числото и думата до него не бива да си
        # противоречат: щом токен ИМА, не пиши «липсва».
        if auth_fail:
            statuses.append(f"🔴 ТЕЛЕГРАМ ОТКАЗВА САМОЛИЧНОСТТА ({auth_fail}) — "
                            f"{len(remaining)} карти чакат в пощата, НИТО ЕДНА не е хвърлена")
            raise SystemExit(f"ТЕЛЕГРАМ: {auth_fail} — токенът е отменен или ботът е изгонен "
                             f"от групата; {len(remaining)} карти остават в outbox.jsonl")
        statuses.append(f"🔴 ЛИПСВА TELEGRAM_TOKEN/CHAT_ID — {len(remaining)} карти чакат в пощата")
        raise SystemExit(f"КОНФИГУРАЦИЯ: няма TELEGRAM_TOKEN/TELEGRAM_CHAT_ID; "
                         f"{len(remaining)} карти НЕ са изпратени и остават в outbox.jsonl")
    return sent_tags


# ================================================================== MAIN ===
